/* ===== START OF AIVisibilityModal.css ===== */

/* AI visibility — floating activity pill + per-run process-chain timeline. */

.aiviz-pill {
    align-items: center;
    ;
    background: none;
    border: none;
    border-radius: 999px;
    color: var(--palette-accent-cyan, #35d0d0);
    cursor: pointer;
    display: flex;
    font: 12px/1 var(--ui-font-main, sans-serif);
    letter-spacing: .04em;
    padding: 0px;
    position: fixed;
    top: 18px;
    right: 8px;
    z-index: 1200;
    width: 20px;
    height: 20px;
    text-align: center;
    font-family: courier;
    opacity: .2;
}

.aiviz-pill:hover,
.aviz-pill-waiting {
    opacity: .5 !important;
}

.aiviz-pill-active {
    opacity: 1;
}

.aiviz-pill-dot {
    background: var(--palette-text-muted, #8aa);
    border-radius: 10px;
    height: 7px;
    width: 7px;
}

.aiviz-pill-active .aiviz-pill-dot {
    animation: aiviz-pulse 1.2s ease-in-out infinite;
    background: var(--palette-success, #4cd67f);
}

.aiviz-pill-waiting .aiviz-pill-dot {
    background: var(--palette-warning, #e7b74a);
}

@keyframes aiviz-pulse {

    0%,
    100% {
        opacity: 1;
    }

    50% {
        opacity: .35;
    }
}

.aiviz-overlay {
    align-items: stretch;
    background: rgba(0, 0, 0, 0.45);
    display: flex;
    inset: 0;
    justify-content: stretch;
    position: fixed;
    z-index: 1300;
}

.aiviz-modal {
    background: var(--theme-components-overlays-aivisibility-modal-background, linear-gradient(135deg, rgba(6, 28, 40, 0.97) 0%, rgba(2, 14, 30, 0.98) 100%));
    border: 0;
    border-radius: 0;
    color: var(--palette-text, #d8e6ea);
    display: flex;
    flex-direction: column;
    height: 100vh;
    max-height: 100vh;
    overflow: hidden;
    width: 100vw;
    max-width: 100vw;
}

.aiviz-header {
    align-items: flex-start;
    border-bottom: 1px solid rgba(0, 200, 200, 0.15);
    display: flex;
    gap: 16px;
    justify-content: space-between;
    padding: 14px 20px;
}

.aiviz-header h2 {
    color: var(--palette-accent-cyan, #35d0d0);
    font: 700 1.1rem/1.2 var(--ui-font-main, sans-serif);
    margin: 0;
}

.aiviz-header p {
    color: var(--palette-text-muted, #8aa);
    font: .78rem/1.4 var(--ui-font-main, sans-serif);
    margin: 4px 0 0;
    max-width: 560px;
}

.aiviz-controls {
    align-items: center;
    display: flex;
    flex-shrink: 0;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: flex-end;
}

.aiviz-count-summary {
    color: var(--palette-text-muted, #8aa);
    font: 650 .7rem/1.2 var(--ui-font-main, sans-serif);
    letter-spacing: .03em;
}

.aiviz-toggle {
    border: 1px solid rgba(0, 200, 200, 0.25);
    border-radius: 8px;
    display: flex;
    overflow: hidden;
}

.aiviz-toggle button {
    background: transparent;
    border: 0;
    color: var(--palette-text-muted, #8aa);
    cursor: pointer;
    font: 650 .72rem/1 var(--ui-font-main, sans-serif);
    padding: 8px 12px;
}

.aiviz-toggle button.on {
    background: rgba(0, 200, 200, 0.18);
    color: var(--palette-accent-cyan, #35d0d0);
}

.aiviz-unfocus {
    background: transparent;
    border: 1px solid rgba(0, 200, 200, 0.25);
    border-radius: 8px;
    color: var(--palette-text-muted, #8aa);
    cursor: pointer;
    font: 650 .72rem/1 var(--ui-font-main, sans-serif);
    padding: 8px 12px;
}

.aiviz-close {
    background: transparent;
    border: 0;
    color: var(--palette-text-muted, #8aa);
    cursor: pointer;
    font-size: 22px;
    line-height: 1;
    min-height: 32px;
    min-width: 32px;
}

.aiviz-legend {
    border-bottom: 1px solid rgba(0, 200, 200, 0.1);
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    padding: 8px 20px;
}

.aiviz-legend span {
    align-items: center;
    color: var(--palette-text-muted, #8aa);
    display: flex;
    font: .7rem/1 var(--ui-font-main, sans-serif);
    gap: 6px;
}

.aiviz-legend .aiviz-node {
    cursor: default;
    position: static;
    transform: none;
}

.aiviz-body {
    display: flex;
    flex: 1;
    min-height: 0;
}

.aiviz-chains {
    flex: 1;
    min-width: 0;
    overflow-y: auto;
    padding: 10px 20px;
}

.aiviz-empty {
    color: var(--palette-text-muted, #8aa);
    font: .8rem/1.5 var(--ui-font-main, sans-serif);
    padding: 12px 0;
}

.aiviz-chain {
    border-bottom: 1px solid rgba(120, 160, 180, 0.1);
    padding: 8px 0 6px;
}

.aiviz-chain-title {
    align-items: baseline;
    background: transparent;
    border: 0;
    color: inherit;
    cursor: pointer;
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    padding: 0 0 2px;
    text-align: left;
    width: 100%;
}

.aiviz-chain-dot {
    align-self: center;
    background: var(--palette-text-muted, #8aa);
    border-radius: 50%;
    flex-shrink: 0;
    height: 7px;
    width: 7px;
}

.aiviz-status-active .aiviz-chain-dot {
    animation: aiviz-pulse 1.2s ease-in-out infinite;
    background: var(--palette-warning, #e7b74a);
}

.aiviz-status-paused .aiviz-chain-dot {
    background: var(--palette-warning, #e7b74a);
}

.aiviz-status-completed .aiviz-chain-dot {
    background: var(--palette-success, #4cd67f);
}

.aiviz-status-failed .aiviz-chain-dot {
    background: var(--palette-danger, #e2556a);
}

.aiviz-chain-title strong {
    font: 700 .8rem/1.2 var(--ui-font-main, sans-serif);
}

.aiviz-chain-sub {
    color: var(--palette-text-muted, #8aa);
    font: .72rem/1.2 var(--ui-font-main, sans-serif);
}

.aiviz-chain-status {
    font: 700 .68rem/1 var(--ui-font-main, sans-serif);
    font-style: normal;
    letter-spacing: .05em;
    margin-left: auto;
    text-transform: uppercase;
}

.aiviz-status-active .aiviz-chain-status {
    color: var(--palette-warning, #e7b74a);
}

.aiviz-status-paused .aiviz-chain-status {
    color: var(--palette-warning, #e7b74a);
}

.aiviz-status-completed .aiviz-chain-status {
    color: var(--palette-success, #4cd67f);
}

.aiviz-status-failed .aiviz-chain-status {
    color: var(--palette-danger, #e2556a);
}

.aiviz-chain-error {
    color: var(--palette-danger, #e2556a);
    font: .72rem/1.4 var(--ui-font-main, sans-serif);
    margin: 0 0 2px 17px;
    max-width: 92%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.aiviz-track {
    padding: 0 0 2px;
}

.aiviz-track-inner {
    height: 34px;
    margin: 0 14px;
    position: relative;
}

.aiviz-rail {
    background: rgba(120, 160, 180, 0.16);
    height: 2px;
    left: 0;
    position: absolute;
    right: 0;
    top: 50%;
}

.aiviz-rail-progress {
    background: rgba(53, 208, 208, 0.45);
    height: 2px;
    left: 0;
    position: absolute;
    top: 50%;
}

.aiviz-rail-progress.is-failed {
    background: rgba(226, 85, 106, 0.55);
}

.aiviz-gap {
    color: var(--palette-text-muted, #8aa);
    font: 650 .62rem/1 ui-monospace, SFMono-Regular, Menlo, monospace;
    letter-spacing: .02em;
    position: absolute;
    top: 1px;
    transform: translateX(-50%);
    white-space: nowrap;
}

.aiviz-gap::after {
    border-left: 1px dotted rgba(120, 160, 180, 0.4);
    content: "";
    height: 7px;
    left: 50%;
    position: absolute;
    top: 9px;
}

.aiviz-now {
    position: absolute;
    right: -2px;
    top: 50%;
    transform: translateY(-50%);
}

.aiviz-now-bar {
    animation: aiviz-pulse 1.2s ease-in-out infinite;
    background: var(--palette-warning, #e7b74a);
    border-radius: 1px;
    display: block;
    height: 16px;
    width: 2px;
}

.aiviz-axis {
    color: var(--palette-text-muted, #8aa);
    display: flex;
    font: .6rem/1 ui-monospace, SFMono-Regular, Menlo, monospace;
    justify-content: space-between;
    margin: 0 14px;
    opacity: .75;
}

.aiviz-node {
    align-items: center;
    background: var(--theme-components-overlays-aivisibility-node-background, rgba(4, 24, 38, 0.95));
    border: 1.5px solid rgba(120, 160, 180, 0.5);
    border-radius: 8px;
    color: var(--palette-text-muted, #9bc);
    cursor: pointer;
    display: flex;
    height: 24px;
    justify-content: center;
    padding: 0;
    position: absolute;
    top: 50%;
    transform: translate(-50%, -50%);
    width: 24px;
}

.aiviz-node svg {
    height: 13px;
    width: 13px;
}

.aiviz-legend .aiviz-node {
    transform: none;
}

.aiviz-stage-user {
    border-color: var(--palette-warning, #e7b74a);
    color: var(--palette-warning, #e7b74a);
}

.aiviz-stage-app {
    border-color: #a48af7;
    color: #a48af7;
}

.aiviz-stage-transmit {
    border-color: var(--palette-accent-cyan, #35d0d0);
    color: var(--palette-accent-cyan, #35d0d0);
}

.aiviz-stage-endpoint {
    border-color: var(--palette-success, #4cd67f);
    color: var(--palette-success, #4cd67f);
}

.aiviz-stage-response {
    border-color: #f08bd4;
    color: #f08bd4;
}

.aiviz-node-error {
    border-color: var(--palette-danger, #e2556a);
    color: var(--palette-danger, #e2556a);
}

.aiviz-node-selected {
    box-shadow: 0 0 0 3px rgba(0, 200, 200, 0.35);
}

.aiviz-inspector {
    border-left: 1px solid rgba(0, 200, 200, 0.15);
    display: flex;
    flex-direction: column;
    min-width: 0;
    overflow-y: auto;
    padding: 14px 16px;
    width: min(44%, 520px);
}

.aiviz-inspector header {
    align-items: center;
    display: flex;
    justify-content: space-between;
}

.aiviz-inspector h3 {
    color: var(--palette-accent-cyan, #35d0d0);
    font: 700 .85rem/1.2 var(--ui-font-main, sans-serif);
    letter-spacing: .06em;
    margin: 0;
    text-transform: uppercase;
}

.aiviz-inspector header button {
    background: transparent;
    border: 0;
    color: var(--palette-text-muted, #8aa);
    cursor: pointer;
    font-size: 20px;
    min-height: 28px;
    min-width: 28px;
}

.aiviz-inspect-error {
    color: var(--palette-danger, #e2556a);
    font: .78rem/1.4 var(--ui-font-main, sans-serif);
}

.aiviz-inspect-headline {
    color: var(--palette-text, #d8e6ea);
    font: 700 .82rem/1.35 var(--ui-font-main, sans-serif);
    margin: 10px 0 0;
}

.aiviz-inspect-content dl {
    display: grid;
    gap: 6px;
    margin: 10px 0;
}

.aiviz-inspect-content dl>div {
    display: flex;
    gap: 10px;
}

.aiviz-inspect-content dt {
    color: var(--palette-text-muted, #8aa);
    flex-shrink: 0;
    font: 700 .68rem/1.5 var(--ui-font-main, sans-serif);
    letter-spacing: .05em;
    text-transform: uppercase;
    width: 76px;
}

.aiviz-inspect-content dd {
    font: .74rem/1.5 ui-monospace, SFMono-Regular, Menlo, monospace;
    margin: 0;
    min-width: 0;
    overflow-wrap: anywhere;
    white-space: pre-wrap;
}

.aiviz-inspect-content dd code {
    color: var(--palette-accent-cyan, #35d0d0);
}

.aiviz-inspect-error-box {
    background: rgba(226, 85, 106, 0.1);
    border: 1px solid rgba(226, 85, 106, 0.4);
    border-radius: 8px;
    display: grid;
    gap: 6px;
    margin: 4px 0 10px;
    padding: 10px 12px;
}

.aiviz-inspect-error-box strong {
    color: var(--palette-danger, #e2556a);
    font: 700 .76rem/1.4 var(--ui-font-main, sans-serif);
    overflow-wrap: anywhere;
}

.aiviz-inspect-error-box span {
    color: var(--palette-text-muted, #8aa);
    font: 650 .68rem/1.3 ui-monospace, SFMono-Regular, Menlo, monospace;
}

.aiviz-inspect-error-box p {
    color: var(--palette-text, #d8e6ea);
    font: .74rem/1.5 var(--ui-font-main, sans-serif);
    margin: 0;
}

.aiviz-inspect-error-box em {
    color: var(--palette-warning, #e7b74a);
    font-style: normal;
    font-weight: 700;
}

.aiviz-inspect-section {
    border-top: 1px solid rgba(120, 160, 180, 0.12);
    padding: 8px 0;
}

.aiviz-inspect-section summary {
    color: var(--palette-text, #d8e6ea);
    cursor: pointer;
    font: 700 .74rem/1.4 var(--ui-font-main, sans-serif);
}

.aiviz-json {
    background: rgba(0, 0, 0, 0.3);
    border-radius: 8px;
    font: .68rem/1.45 ui-monospace, SFMono-Regular, Menlo, monospace;
    margin: 8px 0 0;
    max-height: 40vh;
    overflow: auto;
    padding: 10px;
    white-space: pre-wrap;
    word-break: break-word;
}

.aiviz-j-key {
    color: var(--palette-accent-cyan, #35d0d0);
}

.aiviz-j-str {
    color: #b9e08c;
}

.aiviz-j-num {
    color: #f0a86b;
}

.aiviz-j-kw {
    color: #c792ea;
}

@media (max-width: 900px) {
    .aiviz-body {
        flex-direction: column;
    }

    .aiviz-inspector {
        border-left: 0;
        border-top: 1px solid rgba(0, 200, 200, 0.15);
        width: 100%;
    }
}

/* ===== START OF ActionDeckColumn.legacy.css ===== */

/* =====================
   ActionDeck Column Styles
   ===================== */

.actiondeck-column {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
    min-height: 0;
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-column-background-o0md2, black);
    overflow: hidden;
}

.actiondeck-column.embedded {
    border: none;
    border-radius: 0;
    min-width: 0;
    transform: none;
    transform-origin: left center;
    filter: brightness(1) saturate(1);
    transition: width 0.55s cubic-bezier(0.16, 1, 0.3, 1), transform 0.55s cubic-bezier(0.16, 1, 0.3, 1), filter 0.55s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.55s cubic-bezier(0.16, 1, 0.3, 1);
}

.actiondeck-column.embedded.manifesting {
    width: 0.01px;
    transform: scaleX(0.0001);
    filter: brightness(30) saturate(2.8);
    opacity: 0.9;
}

.actiondeck-column.floating {
    position: fixed;
    width: min(640px, calc(100vw - 24px));
    height: min(78vh, 760px);
    max-width: calc(100vw - 16px);
    max-height: calc(100vh - 16px);
    min-width: 360px;
    min-height: 280px;
    border: 1px solid var(--theme-components-overlays-actiondeckcolumn-actiondeck-column-floating-border-p7cl8, rgba(0, 200, 200, 0.35));
    border-radius: 10px;
    box-shadow: 0 18px 48px var(--theme-components-overlays-actiondeckcolumn-actiondeck-column-floating-box-shadow-uygbx, rgba(0, 0, 0, 0.65));
    z-index: 19;
    resize: both;
    overflow: hidden;
    perspective: 1200px;
}

.actiondeck-column.floating.dragging {
    box-shadow: 0 22px 56px var(--theme-components-overlays-actiondeckcolumn-actiondeck-column-floating-dragging-box-shadow-10xyf, rgba(0, 0, 0, 0.8));
}

.actiondeck-flip-stage {
    position: relative;
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
}

.actiondeck-face {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-column-background-o0md2, black);
    backface-visibility: hidden;
    transform-style: preserve-3d;
    transition: transform 0.55s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.35s ease;
}

.actiondeck-face-back {
    transform: rotateY(-180deg);
    opacity: 0;
    pointer-events: none;
}

.actiondeck-column.floating.settings-open .actiondeck-face-front {
    transform: rotateY(180deg);
    opacity: 0;
    pointer-events: none;
}

.actiondeck-column.floating.settings-open .actiondeck-face-back {
    transform: rotateY(0deg);
    opacity: 1;
    pointer-events: auto;
}

.actiondeck-header,
.actiondeck-settings-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    min-height: 36px;
    padding: 0 10px 0 12px;
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-header-background-gradient, linear-gradient(to top, transparent, rgba(103, 255, 166, 0.5)));
    border: 0.6px solid var(--theme-components-overlays-actiondeckcolumn-actiondeck-header-border-1ck3l, rgba(0, 255, 0, 0.584));
    border-radius: 10px 10px 0 0;
    flex-shrink: 0;
    height: 34px;
    transition: height 0.2s ease, background 0.2s ease, border-color 0.2s ease;
}

.actiondeck-column.floating.dragging .actiondeck-header.draggable {
    cursor: grabbing;
    height: 70px;
}

.actiondeck-header.draggable {
    cursor: grab;
    user-select: none;
}

.actiondeck-column.dragging .actiondeck-header.draggable {
    cursor: grabbing;
}

.actiondeck-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-title-color-26sfj, lime);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.actiondeck-controls {
    display: flex;
    gap: 6px;
    align-items: center;
}

.actiondeck-btn {
    width: 30px;
    min-width: 30px;
    height: 28px;
    border-radius: 4px;
    border: 1px solid var(--theme-components-overlays-actiondeckcolumn-actiondeck-column-floating-border-p7cl8, rgba(0, 200, 200, 0.35));
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-background-idkl8, rgba(0, 60, 60, 0.6));
    color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-color-1xy18, #b5d9d9);
    font-size: 12px;
    cursor: pointer;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.actiondeck-btn.mode {
    border-color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-mode-border-color-13w00, rgba(5, 250, 160, 0.45));
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-mode-background-1pyby, rgba(20, 170, 0, 0.5));
    color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-mode-color-7ji4k, #ffd18a);
}

.actiondeck-btn.star {
    border-color: rgba(255, 214, 102, 0.42);
    background: rgba(80, 62, 10, 0.7);
    color: #ffd96b;
}

.actiondeck-btn.star.active {
    background: rgba(168, 130, 18, 0.82);
    border-color: rgba(255, 225, 126, 0.68);
    color: #fff4ca;
}

.actiondeck-btn:hover {
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-hover-background-1atdb, rgba(0, 90, 90, 0.8));
    border-color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-hover-border-color-1hyjj, rgba(0, 229, 229, 0.65));
    color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-hover-color-1plkp, white);
}

.actiondeck-btn.close {
    border-color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-close-border-color-tqncr, rgba(170, 30, 30, 0.6));
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-close-background-18w58, rgba(110, 10, 10, 0.7));
}

.actiondeck-btn.close:hover {
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-close-hover-background-1nk37, rgba(150, 30, 30, 0.7));
    border-color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-close-hover-border-color-1evgc, rgba(255, 100, 100, 0.6));
    color: var(--theme-components-overlays-actiondeckcolumn-actiondeck-btn-close-hover-color-l2prx, #ffb1b1);
}

.actiondeck-content {
    flex: 1;
    min-height: 0;
    position: relative;
    overflow: hidden;
}

.actiondeck-frame {
    width: 100%;
    height: 100%;
    border: none;
    opacity: 0;
    transition: opacity 0.3s ease;
}

.actiondeck-frame.loaded {
    opacity: 1;
}

.actiondeck-placeholder {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    background: var(--theme-components-overlays-actiondeckcolumn-actiondeck-placeholder-background-gradient, linear-gradient(135deg, #0d1f3c 0%, #0a1628 100%));
    transition: opacity 0.3s ease;
}

.actiondeck-placeholder.hidden {
    opacity: 0;
    pointer-events: none;
}

.actiondeck-placeholder .placeholder-icon {
    font-size: 48px;
    opacity: 0.6;
}

.actiondeck-placeholder h3 {
    font-size: 18px;
