/* ===== START OF App.css ===== */

/* ConsoliChrome shared scales */

:root {
    --cc-font-size-tiny: 9.5px;
    --cc-font-size-small: 13px;
    --cc-font-size-medium: 16px;
    --cc-font-size-large: 22px;
    --cc-font-size-huge: 40px;
    --cc-radius-none: 0px;
    --cc-radius-slight: 3.5px;
    --cc-radius-medium: 10px;
    --cc-radius-large: 24px;
    --cc-radius-huge: 999px;
    --cc-gap-none: 0px;
    --cc-gap-small: 1.5px;
    --cc-gap-medium: 5px;
    --cc-gap-large: 9.5px;
    --cc-gap-huge: 18px;
    --cc-padding-tiny: 0px;
    --cc-padding-small: 1.5px;
    --cc-padding-medium: 5px;
    --cc-padding-large: 11px;
    --cc-padding-huge: 20px;
    --cc-app-header-height: 70px;
}

:root[data-theme='medieval-taurus'],
:root[data-theme='caspian-sea'] {
    --cc-font-size-tiny: 10.05px;
    --cc-font-size-small: 17.42px;
    --cc-font-size-medium: 21.44px;
    --cc-font-size-large: 29.48px;
    --cc-font-size-huge: 53.6px;
}

/* ===== pasted.css ===== */

@keyframes hueroto {
    0% {
        filter: hue-rotate(0deg)
    }

    100% {
        filter: hue-rotate(360deg);
    }
}

@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes pulse {

    0%,
    100% {
        opacity: 0.4;
    }

    50% {
        opacity: 1;
    }
}

@keyframes spin {
    from {
        transform: rotate(0deg);
    }

    to {
        transform: rotate(360deg);
    }
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px) scale(0.98);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

@keyframes recordPulse {

    0%,
    100% {
        opacity: 1;
        box-shadow: 0 0 8px #ff4444;
    }

    50% {
        opacity: 0.5;
        box-shadow: 0 0 16px #ff4444;
    }
}

@keyframes backflow {
    0% {
        background-position: 0% 50%;
    }

    100% {
        background-position: 400% 50%;
    }
}

@keyframes porygon {
    0% {
        transform: rotate(0deg);
    }

    100% {
        transform: rotate(360deg);
    }
}

@keyframes streamPulse {

    0%,
    100% {
        opacity: 0.3;
    }

    50% {
        opacity: 1;
    }
}

@keyframes slideInFromLeft {
    from {
        transform: translateX(-100%);
        opacity: 0;
    }

    to {
        transform: translateX(0);
        opacity: 1;
    }
}

body {
    background: var(--ui-body-bg, black);
    color: var(--ui-text-primary);
    border-radius: var(--cc-radius-none);
}

.app {
    display: flex;
    flex-direction: column;
    position: relative;
    height: 100vh;
    background: linear-gradient(var(--ui-body-bg), var(--ui-app-bg));
    background-repeat: var(--ui-bg-repeat, no-repeat);
    color: var(--ui-text-primary);
    font-family: BC Alphapipe, Jost, AWeber, Ashemore, Chillax, Aisha Latin, Afacad Flux, 'Forma DJR Variable', -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', Roboto, sans-serif;
    overflow: hidden;
    border: var(--ui-app-border);
    border-radius: var(--ui-app-border-radius);
    box-shadow: var(--ui-app-shadow);
    font-family: var(--ui-font-main, Chillax);
}

.app.theme-studio-docked {
    width: calc(100% - var(--theme-studio-width, 320px));
}

@media (max-width: 920px) {
    .app.theme-studio-docked {
        width: 100%;
    }
}

.app-header {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
    gap: var(--cc-gap-huge);
    position: relative;
    height: var(--cc-app-header-height);
    top: 0;
    z-index: 34;
    color: var(--ui-header-text, whitesmoke);
    padding: 0;
    background: var(--ui-header-bg);
    flex-shrink: 0;
    border-radius: var(--cc-radius-none) !important;
    user-select: none;
    overflow: hidden;
    ;
    transition: all .15s cubic-bezier(.3, .8, .7, 1.1);
    ;
    transition-delay: 0s;
    ;
}

.app-header:hover {
    height: var(--cc-app-header-height);
    transform: scale(1);
    transition-delay: 0s;
}

.app-header.shrinkable {
    overflow: hidden;
    transition: all .2s cubic-bezier(.5, .9, .5, 1);
    transition-delay: 5s;
}

.app-header.shrunk {
    transition-delay: 5s;
}

.app-header.shrinkable:hover,
.app-header.shrunk:hover {
    height: var(--cc-app-header-height);
    transition-delay: 0s;
}

.app-header.shrunk:not(:hover) .title-text,
.app-header.shrunk:not(:hover) .header-dock-slot,
.app-header.shrunk:not(:hover) .header-right {
    opacity: 0;
    transition: all 1s;
    transition-delay: 4s;
    pointer-events: none;
    user-select: none;
}

.app-header.shrunk:hover .title-text,
.app-header.shrunk:hover .header-dock-slot,
.app-header.shrunk:hover .header-right {
    opacity: 1;
    transition-delay: 0s;
    pointer-events: all;
    user-select: all;
}

.header-shrink-toggle {
    opacity: .1;
    -webkit-app-region: no-drag;
    appearance: none;
    position: absolute;
    bottom: 4px;
    right: 4px;
    z-index: 4000;
    display: grid;
    width: 30px;
    height: 40px;
    padding: 0;
    place-items: center;
    border: 1px solid color-mix(in oklab, var(--palette-accent-primary, #42dbe8) 74%, transparent);
    border-radius: var(--cc-radius-slight);
    background: color-mix(in oklab, var(--ui-header-bg, #050708) 88%, transparent);
    color: var(--palette-accent-primary, #42dbe8);
    box-shadow: 0 0 0 1px color-mix(in oklab, var(--palette-accent-primary, #42dbe8) 20%, transparent), 0 0 10px color-mix(in oklab, var(--palette-accent-primary, #42dbe8) 24%, transparent);
    cursor: pointer;
    font-family: 'SF Pro Display', 'SF Pro Symbols', 'Apple Symbols', sans-serif !important;
    font-size: 19px;
    line-height: 1;
    text-shadow: 0 0 7px currentColor;
    transition: color .15s ease, background .15s ease, border-color .15s ease, box-shadow .15s ease;
}

.header-shrink-toggle:hover,
.header-shrink-toggle:focus-visible,
.header-shrink-toggle.is-active {
    border-color: var(--palette-accent-primary, #42dbe8);
    background: color-mix(in oklab, var(--ui-header-bg, #050708) 72%, var(--palette-accent-primary, #42dbe8));
    color: color-mix(in oklab, var(--palette-accent-primary, #42dbe8) 74%, white);
    box-shadow: 0 0 0 1px color-mix(in oklab, var(--palette-accent-primary, #42dbe8) 34%, transparent), 0 0 14px color-mix(in oklab, var(--palette-accent-primary, #42dbe8) 48%, transparent);
    outline: none;
    opacity: 1;
}

.header-shrink-toggle.is-active {
    right: 50%;
    transform: translateX(50%)scaleY(.5);
}

.header-shrink-toggle:focus-visible {
    outline: 1px solid currentColor;
    outline-offset: 2px;
}

.app:not(.app--vertical-header) .header-right {
    padding-right: 32px;
}

.app--vertical-header .header-shrink-toggle {
    display: none;
}

.header-title {
    width: 30vw;
    height: 100%;
    color: var(--ui-header-titlecolor, white);
    display: flex;
    align-items: center;
    gap: var(--cc-gap-large);
    padding: var(--cc-padding-tiny) !important;
    height: 100%;
    pointer-events: all !important;
    justify-self: start;
    min-width: 0;
    border-radius: var(--cc-radius-none) !important;
}

.header-dock-slot {
    justify-self: center;
    width: 75vw;
    min-width: 260px;
    max-width: 100%;
}

.header-right {
    display: flex;
    align-items: center;
    justify-self: end;
    gap: var(--cc-gap-large);
    min-width: 0;
}

.title-icon {
    display: contents;
    color: var(--ui-title-icon);
    font-size: var(--cc-font-size-large);
    text-shadow: var(--ui-title-icon-glow);
    transition: all 1.4s cubic-bezier(0.5, .2, 0.7, 1.1), filter 5s ease;
}

.title-icon::before {
    content: "᳀";
    filter: brightness(1)blur(0px);
    transition: all 1.4s cubic-bezier(0.5, .2, 0.7, 1.1), filter 2.5s ease;
}

.title-icon:hover .title-icon::before,
.app-header:hover .title-icon::before {
    transform: scale(2.5)rotate(720deg);
}

.title-icon:active .title-icon::before,
.header-title:active .title-icon::before {
    transform: scale(4)rotate(720deg);
    filter: brightness(3)blur(1px);
    transition: transform .3s ease, filter 1s ease;
}

.title-text {
    -webkit-app-region: drag;
    text-transform: var(--ui-title-transform, none);
    font-size: var(--ui-title-size, var(--cc-font-size-large));
    font-weight: var(--ui-title-weight, 400);
    background: var(--ui-title-gradient);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    -webkit-text-stroke: var(--ui-title-stroke);
    transition: all .2s ease;
    background-size: 400% 400%;
    animation: backflow 10s linear infinite;
    animation-duration: var(--ui-title-duration, 10s);
    letter-spacing: 1.5px;
}

/* Header date/time/weather widget */

.header-datetime-weather {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    margin: 0;
    font-size: var(--cc-font-size-small);
    letter-spacing: 1px;
    opacity: 0.7;
    -webkit-app-region: drag !important;
}

.header-time {
    color: var(--palette-accent-primary);
    font-weight: 600;
}

.header-date {
    font-weight: 400;
    color: var(--palette-accent-primary);
}

.header-weather {
    font-weight: 600;
}

/* Vertical Ambient header ------------------------------------------------
   The top bar becomes a permanent left rail without moving any control out
   of its existing header region: identity above, actions centered, status
   below. The main workspace simply yields the rail's width. */

.app--vertical-header {
    --vertical-header-width: 96px;
    position: relative;
}

.app--vertical-header .app-header {
    position: absolute;
    inset: 0 auto 0 0;
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr) auto;
    width: var(--vertical-header-width);
    height: 100%;
    box-sizing: border-box;
    gap: var(--cc-gap-none);
    padding: var(--cc-padding-large) var(--cc-padding-medium) var(--cc-padding-huge);
    margin: 0;
    overflow: visible;
    border-right: 1px solid color-mix(in oklab, var(--palette-accent-primary, #ac4bd9) 52%, transparent);
    background: var(--ui-header-bg);
    box-shadow: inset -1px 0 rgba(235, 242, 245, 0.12), inset -13px 0 22px color-mix(in oklab, var(--palette-accent-primary, #7f4fe0) 22%, transparent), 7px 0 18px rgba(0, 0, 0, 0.3);
}

.app--vertical-header .header-title {
    grid-row: 1;
    width: 100%;
    height: 76px;
    min-width: 0;
    align-items: flex-start;
    justify-content: center;
    justify-self: stretch;
}

.app--vertical-header .title-icon {
    display: grid;
    width: 68px;
    height: 68px;
    place-items: center;
    color: var(--ui-title-icon);
    font-size: var(--cc-font-size-large);
    line-height: 1;
}

.app--vertical-header .title-icon::before {
    font-size: var(--cc-font-size-large);
    line-height: 1;
}

.app--vertical-header .app-header:hover .title-icon::before {
    transform: none;
}

.app--vertical-header .title-text,
.app--vertical-header .title-icon\:before {
    display: none;
}

.app--vertical-header .header-dock-slot {
    grid-row: 2;
    display: flex;
    width: 100%;
    height: 100%;
    min-width: 0;
    max-width: none;
    align-items: center;
    justify-content: center;
    justify-self: stretch;
}

.app--vertical-header .header-right {
    grid-row: 3;
    display: flex;
    width: 100%;
    min-width: 0;
    align-items: center;
    justify-content: center;
    justify-self: stretch;
}

.app--vertical-header .header-datetime-weather {
    align-items: center;
    gap: var(--cc-gap-medium);
    color: color-mix(in oklab, var(--palette-accent-primary, #d7dfa1) 44%, #eef0c7);
    font-family: var(--ui-font-main);
    font-size: var(--cc-font-size-medium);
    line-height: 1.12;
    letter-spacing: 0.08em;
    text-align: center;
    opacity: 0.92;
}

.app--vertical-header .header-date {
    order: -1;
    width: 100%;
    color: inherit;
    font-size: var(--cc-font-size-tiny);
    font-weight: 600;
    line-height: 1.18;
    overflow-wrap: anywhere;
}

.app--vertical-header .header-time {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--cc-gap-medium);
    color: inherit;
    font-size: var(--cc-font-size-medium);
    line-height: 1.1;
}

.app--vertical-header .header-weather {
    display: block;
    color: inherit;
    font-size: var(--cc-font-size-medium);
}

.app--vertical-header .app-main {
    height: 100%;
    min-width: 0;
    margin-left: var(--vertical-header-width);
}

.app--vertical-header #controlBar {
    margin-left: var(--vertical-header-width);
}

@media (max-height: 700px) {
    .app--vertical-header .app-header {
        padding-block: 8px 12px;
    }

    .app--vertical-header .header-title {
        height: 58px;
    }

    .app--vertical-header .title-icon,
    .app--vertical-header .title-icon::before {
        font-size: var(--cc-font-size-large);
    }

    .app--vertical-header .header-datetime-weather,
    .app--vertical-header .header-date,
    .app--vertical-header .header-time,
