@container (max-width: 680px) {
    .media-workspace.with-queue {
        grid-template-columns: minmax(0, 1fr);
    }

    .media-playlist {
        max-height: 180px;
    }

    .media-stage {
        min-height: 200px;
    }

    .media-volume {
        width: 100%;
        margin-left: 0;
        padding-left: var(--cc-padding-tiny);
        border-left: none;
    }

    .media-volume-slider {
        flex: 1;
    }
}

.media-panel-resize-handle {
    position: absolute;
    right: 0;
    bottom: 0;
    width: 120px;
    height: 20px;
    cursor: nwse-resize;
    opacity: 0;
    transition: opacity 0.2s ease;
    z-index: 6;
}

.media-panel-resize-handle::after {
    content: '';
    position: absolute;
    right: 4px;
    bottom: 4px;
    width: 10px;
    height: 10px;
    background-image: linear-gradient(135deg, transparent 40%, rgba(255, 255, 255, 0.5) 40%, rgba(255, 255, 255, 0.5) 50%, transparent 50%), linear-gradient(135deg, transparent 60%, rgba(255, 255, 255, 0.5) 60%, rgba(255, 255, 255, 0.5) 70%, transparent 70%), linear-gradient(135deg, transparent 80%, rgba(255, 255, 255, 0.5) 80%, rgba(255, 255, 255, 0.5) 90%, transparent 90%);
    border-radius: var(--cc-radius-none) var(--cc-radius-none) var(--cc-radius-medium) var(--cc-radius-none);
}

.media-floating-panel:hover .media-panel-resize-handle,
.media-floating-panel.resizing .media-panel-resize-handle {
    opacity: 1;
}

@media (max-width: 980px) {

    /* Keep the two global controls anchored; the application launchers get
       the remaining horizontal track and scroll inside it. */
    .app:not(.app--vertical-header) .app-header {
        grid-template-columns: 48px minmax(0, 1fr);
        gap: var(--cc-gap-none);
        padding-inline: 4px;
    }

    .app:not(.app--vertical-header) .header-title {
        width: 48px;
        min-width: 48px;
        gap: var(--cc-gap-none);
    }

    .app:not(.app--vertical-header) .title-text,
    .app:not(.app--vertical-header) .header-right {
        display: none;
    }

    .app:not(.app--vertical-header) #settings-btn {
        display: grid;
        place-items: center;
        box-sizing: border-box;
        width: 44px;
        min-width: 44px;
        height: 48px;
    }

    .app:not(.app--vertical-header) .header-dock-slot {
        display: block;
        margin-left: auto;
        margin-right: 40px;
        width: 95%;
        min-width: 0;
        max-width: none;
        justify-self: stretch;
    }

    #controlBarToggle {
        transform: scale(.8);
    }
}

.panel.sources-panel {
    border-right: 1px solid rgba(0, 200, 200, 0.1);
    height: 10%;
    min-height: 0;
    overflow: hidden;
    box-shadow: inset 0 -15px 25px var(--palette-accent-primary-soft);
}

.panel.sources-panel .panel-content::-webkit-scrollbar {
