/* Theme transition animation */

@keyframes themeTransitionFlash {
    0% {
        filter: brightness(0.7);
    }

    40% {
        filter: brightness(1.2);
    }

    100% {
        filter: brightness(1);
    }
}

.theme-transitioning {
    animation: themeTransitionFlash 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.briiz-logo {
