:root[data-theme='burnt-chestnut'] {
    --chat-input-text-color: #F0EAD6;
    /* Palette based on Cherry Blossom, Burnt Chestnut, Tapioca, Salmon */
    --palette-accent-salmon: #FA8072;
    --palette-accent-salmon-soft: #FB9A8D;
    --palette-accent-pink: #FFB7C5;
    /* Cherry Blossom */
    --palette-success: #8DB38B;
    /* Muted Sage Green */
    --palette-warning: #E5B873;
    /* Soft Gold */
    --palette-danger: #E57373;
    /* Muted Red */
    --palette-text-main: #F0EAD6;
    /* Tapioca */
    --palette-text-faint: #D8CFC0;
    --palette-text-soft: #C0B4A8;
    --palette-text-subtle: #A89990;
    --palette-text-muted: #908078;
    --palette-text-dim: #786860;
    --palette-white: #fff;
    --palette-burnt-chestnut: #582C2B;
    --palette-burnt-chestnut-dark: #2C5234;
    /* UI Globals */
    --ui-body-bg: linear-gradient(to right, orange, rgb(48, 12, 0), darkred);
    ;
    --ui-app-bg: linear-gradient(to bottom right, black 60%, rgb(40, 30, 10));
    --ui-app-border: 3px solid #1E1212;
    --ui-app-shadow: inset 0 0 10px rgba(250, 128, 114, 0.2);
    --ui-text-primary: var(--palette-text-main);
    --ui-header-text: var(--palette-text-main);
    --ui-header-bg: linear-gradient(to bottom, #2C1A1A 80%, var(--palette-accent-salmon));
    --ui-title-icon: var(--palette-accent-salmon);
    --ui-title-icon-glow: 0 0 8px var(--palette-accent-salmon);
    --ui-title-gradient: linear-gradient(120deg, var(--palette-burnt-chestnut), var(--palette-accent-salmon), var(--palette-accent-pink), var(--palette-burnt-chestnut));
    --ui-title-stroke: 0.1px var(--palette-text-main);
    /* Buttons */
    --ui-button-ghost-border-strong: rgba(240, 234, 214, 0.3);
    --ui-button-ghost-text: var(--palette-text-subtle);
    --ui-button-ghost-text-hover: var(--palette-text-main);
    --ui-button-ghost-bg-hover: rgba(240, 234, 214, 0.1);
    /* Panels & Chat */
    --ui-panel-header-text: var(--palette-text-subtle);
    --ui-panel-btn: var(--palette-text-muted);
    --ui-panel-btn-hover: var(--palette-accent-salmon);
    --ui-chat-header-text: #582C2B;
    --ui-chat-header-bg: rgba(100, 83, 27, 1);
    /* Cherry Blossom */
    --ui-chat-header-border: var(--palette-accent-pink);
    --ui-chat-input-bg: linear-gradient(rgba(88, 44, 43, 0.8), rgba(61, 37, 37, 0.6));
    --ui-chat-input-text: var(--palette-text-main);
    --ui-chat-placeholder: rgba(255, 183, 197, 0.6);
    /* Modal */
    --ui-modal-bg: linear-gradient(135deg, rgba(255, 183, 197, 0.1) 0%, rgba(88, 44, 43, 0.2) 100%);
    --ui-modal-border: rgba(250, 128, 114, 0.4);
    --ui-modal-header-bg: rgba(88, 44, 43, 0.2);
    --ui-modal-header-border: rgba(250, 128, 114, 0.2);
    --ui-modal-title: var(--palette-accent-salmon);
    --ui-modal-close: var(--palette-text-muted);
    --ui-modal-tabs-bg: rgba(88, 44, 43, 0.3);
    --ui-modal-tabs-border: rgba(250, 128, 114, 0.15);
    --ui-modal-tab-text: var(--palette-text-muted);
    --ui-modal-tab-hover-text: var(--palette-text-soft);
    --ui-modal-tab-hover-bg: rgba(250, 128, 114, 0.1);
    --ui-modal-tab-active-text: var(--palette-accent-salmon);
    --ui-modal-tab-active-bg: rgba(250, 128, 114, 0.15);
    /* Settings */
    --ui-settings-section-desc: var(--palette-text-subtle);
    --ui-settings-label: var(--palette-text-soft);
    --ui-settings-hint: var(--palette-text-muted);
    --ui-settings-input-bg: rgba(88, 44, 43, 0.6);
    --ui-settings-input-border: rgba(250, 128, 114, 0.2);
    --ui-settings-input-text: var(--palette-text-main);
    --ui-settings-input-placeholder: var(--palette-text-dim);
    --ui-settings-input-focus-border: rgba(250, 128, 114, 0.5);
    --ui-settings-input-focus-shadow: 0 0 10px rgba(250, 128, 114, 0.2);
    --ui-settings-toggle-bg: rgba(180, 120, 110, 0.3);
    --ui-settings-toggle-border: rgba(250, 128, 114, 0.2);
    --ui-settings-toggle-text: var(--palette-accent-salmon);
    --ui-settings-toggle-bg-hover: rgba(200, 140, 130, 0.4);
    --ui-settings-toggle-border-hover: rgba(250, 128, 114, 0.4);
    --ui-settings-radio-bg: rgba(88, 44, 43, 0.4);
    --ui-settings-radio-border: rgba(250, 128, 114, 0.15);
    --ui-settings-radio-bg-hover: rgba(180, 120, 110, 0.3);
    --ui-settings-radio-border-hover: rgba(250, 128, 114, 0.3);
    --ui-settings-radio-bg-active: rgba(200, 140, 130, 0.3);
