    --ui-settings-radio-label: var(--palette-text-main);
    --ui-settings-radio-label-active: var(--palette-accent-salmon);
    /* Modal Footer */
    --ui-modal-footer-bg: rgba(88, 44, 43, 0.3);
    --ui-modal-footer-border: rgba(250, 128, 114, 0.1);
