:root[data-theme='verdigris'] {
    --chat-input-text-color: gold;
    --palette-accent-primary: #3a9f9a;
    /* muted verdigris (patina) */
    --palette-accent-primary-soft: #2f8e89;
    --palette-neon-accent: #4fbf91;
    /* oxidized-copper green */
    --palette-success: #5a9b63;
    /* subdued, matte */
    --palette-warning: #c9a24a;
    /* antique gold */
    --palette-danger: #b45a4f;
    /* oxidized red-brown */
    --palette-text-main: #e6dccf;
    /* warm parchment */
    --palette-text-faint: #d2c6b7;
    --palette-text-soft: #b9ac9d;
    --palette-text-subtle: #9a8d7f;
    --palette-text-muted: #7c7166;
    --palette-text-dim: #60584f;
    --palette-white: #f3eadf;
    --ui-body-bg: white;
    /* matte soot-brown */
    --ui-app-bg: #0b0705;
    --ui-app-border: 3px solid rgba(92, 63, 36, 0.65);
    /* tarnished bronze edge */
    --ui-app-shadow: inset 0 0 12px rgba(41, 26, 14, 0.85);
    --ui-text-primary: var(--palette-text-main);
    --ui-header-text: var(--palette-white);
    --ui-header-bg: linear-gradient(to bottom, #0b0705 75%, rgba(153, 102, 51, 0.55));
    /* burnished bronze falloff */
    --ui-title-icon: #b07a44;
    /* bronze highlight */
    --ui-title-icon-glow: 0 0 8px rgba(176, 122, 68, 0.25);
    /* matte "glow" */
    --ui-title-gradient: linear-gradient(120deg, #6d4b2c,
            /* engraved bronze */
            #0b0705,
            /* soot */
            #8a5a2f,
            /* burnished copper */
            rgba(33, 54, 49, 0.65),
            /* tarnish/patina */
            #a66d3c,
            /* warm brass */
            #0b0705, #5c3f24);
    --ui-title-stroke: 0.1px rgba(243, 234, 223, 0.65);
    --ui-button-ghost-border-strong: rgba(230, 220, 207, 0.14);
    --ui-button-ghost-text: var(--palette-text-subtle);
    --ui-button-ghost-text-hover: var(--palette-text-soft);
    --ui-button-ghost-bg-hover: rgba(176, 122, 68, 0.08);
    /* rubbed bronze */
    --ui-panel-header-text: var(--palette-text-subtle);
    --ui-panel-btn: var(--palette-text-muted);
    --ui-panel-btn-hover: #c08a52;
    /* brightened bronze */
    --ui-chat-header-text: #d8b17a;
    /* antique brass */
    --ui-chat-header-bg: rgba(106, 70, 38, 0.55);
    /* varnished bronze wash */
    --ui-chat-header-border: rgba(192, 138, 82, 0.65);
    --ui-chat-input-bg: linear-gradient(rgba(34, 26, 18, 0.78),
            /* matte umber */
            rgba(18, 14, 10, 0.72)
            /* soot */
        );
    --ui-chat-input-text: var(--palette-white);
    --ui-chat-placeholder: rgba(216, 177, 122, 0.45);
    --ui-modal-bg: linear-gradient(135deg, rgba(92, 63, 36, 0.22) 0%,
            /* tarnished bronze */
            rgba(11, 7, 5, 0.55) 100%
            /* matte soot */
        );
    --ui-modal-border: rgba(176, 122, 68, 0.26);
    --ui-modal-header-bg: rgba(18, 12, 8, 0.55);
    --ui-modal-header-border: rgba(176, 122, 68, 0.14);
    --ui-modal-title: #c08a52;
    /* burnished label */
    --ui-modal-close: var(--palette-text-muted);
    --ui-modal-tabs-bg: rgba(16, 11, 7, 0.55);
    --ui-modal-tabs-border: rgba(176, 122, 68, 0.10);
    --ui-modal-tab-text: var(--palette-text-muted);
    --ui-modal-tab-hover-text: var(--palette-text-soft);
    --ui-modal-tab-hover-bg: rgba(176, 122, 68, 0.08);
    --ui-modal-tab-active-text: #d2a06b;
    /* polished brass */
    --ui-modal-tab-active-bg: rgba(176, 122, 68, 0.14);
    --ui-settings-section-desc: var(--palette-text-subtle);
    --ui-settings-label: var(--palette-text-soft);
    --ui-settings-hint: var(--palette-text-muted);
    --ui-settings-input-bg: rgba(20, 14, 10, 0.72);
    /* matte "oiled" metal */
    --ui-settings-input-border: rgba(176, 122, 68, 0.20);
    --ui-settings-input-text: var(--palette-text-main);
    --ui-settings-input-placeholder: var(--palette-text-dim);
    --ui-settings-input-focus-border: rgba(192, 138, 82, 0.45);
    --ui-settings-input-focus-shadow: 0 0 10px rgba(176, 122, 68, 0.10);
    --ui-settings-toggle-bg: rgba(60, 40, 22, 0.38);
    --ui-settings-toggle-border: rgba(176, 122, 68, 0.22);
    --ui-settings-toggle-text: #d2a06b;
    --ui-settings-toggle-bg-hover: rgba(74, 50, 28, 0.46);
    --ui-settings-toggle-border-hover: rgba(192, 138, 82, 0.38);
    --ui-settings-radio-bg: rgba(24, 16, 11, 0.55);
    --ui-settings-radio-border: rgba(176, 122, 68, 0.16);
    --ui-settings-radio-bg-hover: rgba(60, 40, 22, 0.40);
    --ui-settings-radio-border-hover: rgba(176, 122, 68, 0.28);
    --ui-settings-radio-bg-active: rgba(92, 63, 36, 0.35);
    --ui-settings-radio-border-active: rgba(192, 138, 82, 0.50);
    --ui-settings-radio-shadow-active: 0 0 15px rgba(176, 122, 68, 0.10);
    --ui-settings-radio-label: var(--palette-text-main);
    --ui-settings-radio-label-active: #d2a06b;
    --ui-modal-footer-bg: rgba(16, 11, 7, 0.55);
    --ui-modal-footer-border: rgba(176, 122, 68, 0.10);
    --ui-modal-save-bg: rgba(92, 63, 36, 0.55);
    --ui-modal-save-border: rgba(192, 138, 82, 0.40);
    --ui-modal-save-text: #f0d8bf;
    /* pale brass */
    --ui-modal-save-bg-hover: rgba(120, 80, 44, 0.65);
    --ui-modal-save-shadow-hover: 0 0 15px rgba(192, 138, 82, 0.18);
    --ui-provider-tab-bg: rgba(230, 220, 207, 0.03);
    --ui-provider-tab-border: rgba(230, 220, 207, 0.10);
    --ui-provider-tab-text: var(--palette-text-subtle);
    --ui-provider-tab-bg-hover: rgba(176, 122, 68, 0.08);
    --ui-provider-tab-text-hover: var(--palette-text-faint);
    --ui-provider-tab-bg-active: rgba(176, 122, 68, 0.18);
    --ui-provider-tab-border-active: rgba(192, 138, 82, 0.30);
    --ui-provider-tab-text-active: #d2a06b;
    --ui-slider-thumb-bg: #c08a52;
    --ui-slider-thumb-shadow: 0 0 6px rgba(192, 138, 82, 0.28);
    --ui-markdown-code-bg: rgba(176, 122, 68, 0.12);
    --ui-markdown-code-color: #d2a06b;
    --ui-markdown-th-bg: rgba(176, 122, 68, 0.10);
    --ui-controlbar-bg: linear-gradient(120deg, #5c3f24,
            /* bronze */
            #0b0705,
            /* soot */
            #7a4f2a,
            /* copper */
            rgba(33, 54, 49, 0.55),
            /* patina */
            #8a5a2f,
            /* burnish */
            #0b0705, #4a331e);
    --ui-controlbar-shadow: inset 0 0 10px rgba(243, 234, 223, 0.10), inset 0 0 22px rgba(176, 122, 68, 0.22);
    --ui-controlbar-filter: blur(0px) brightness(0.95) saturate(0.55);
    --ui-controlbar-filter-hover: blur(0px) brightness(1.10) saturate(0.70);
    --layout-bg-primary: #0b0705;
    --layout-bg-panel: #0b0705;
    --layout-bg-panel-header: #0a0604;
    --layout-accent-cyan: #b07a44;
    /* repurposed as bronze accent */
    --layout-accent-cyan-dim: rgba(176, 122, 68, 0.30);
    --layout-accent-cyan-glow: rgba(176, 122, 68, 0.45);
    --layout-accent-orange: #c08a52;
    /* antique brass */
    --layout-accent-orange-dim: rgba(192, 138, 82, 0.30);
    --layout-border-color: rgba(92, 63, 36, 0.28);
    /* engraved seam */
    --layout-border-color-hover: rgba(192, 138, 82, 0.45);
    --layout-border-color-active: rgba(210, 160, 107, 0.60);
    --layout-gap: 1px;
    --layout-panel-radius: 6px;
    --layout-header-height: 36px;
    --layout-resize-handle-size: 24px;
    --layout-transition-fast: 0.15s ease;
    --layout-transition-normal: 0.2s ease;
}

.tile-layout {
    position: relative;
    height: 100%;
    width: 100%;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.tile-layout-content {
    flex: 1;
    display: flex;
    overflow: hidden;
    gap: var(--layout-gap);
    height: 100%;
    min-height: 0;
}

.panel:hover {
    border-color: var(--layout-border-color-hover);
}

.panel.focused,
.panel.active {
    border-color: var(--layout-border-color-active);
    box-shadow: 0 0 12px rgba(0, 200, 200, 0.1);
}

.panel.dragging {
    opacity: 0.7;
    filter: blur(2px);
    border-color: var(--layout-accent-orange-dim);
}

.panel.drop-target {
    border-color: var(--layout-accent-cyan);
    box-shadow: 0 0 20px rgba(0, 229, 229, 0.2);
}

.panel.minimized {
    flex: 0 0 auto;
    height: auto;
    min-height: var(--layout-header-height);
}

.panel.minimized .panel-content {
    display: none;
}

.panel.maximized {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 12;
    border-color: var(--layout-accent-cyan);
    box-shadow: 0 0 30px rgba(0, 200, 200, 0.2);
}

.panel-header-left {
    display: flex;
    align-items: center;
    gap: var(--cc-gap-large);
    flex: 1;
    min-width: 0;
}

.panel-header-icon {
    font-size: var(--cc-font-size-medium);
    color: var(--layout-accent-cyan);
    flex-shrink: 0;
}

.panel-header-title {
    font-size: var(--cc-font-size-small);
    font-weight: 500;
    color: var(--palette-text-subtle);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.panel-header-right {
    display: flex;
    align-items: center;
    gap: var(--cc-gap-large);
}

.panel-control-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    background: transparent;
    border: none;
    border-radius: var(--cc-radius-slight);
    color: var(--palette-text-muted);
    cursor: pointer;
    transition: all var(--layout-transition-fast);
    padding: var(--cc-padding-tiny);
    font-size: var(--cc-font-size-medium);
}

.panel-control-btn:hover {
    background: rgba(0, 200, 200, 0.1);
    color: var(--layout-accent-cyan);
}

.panel-control-btn:active {
    background: rgba(0, 200, 200, 0.2);
}

.panel-control-btn.close:hover {
    background: rgba(255, 100, 100, 0.2);
    color: var(--palette-danger);
}

.panel-control-btn.maximize:hover {
    background: rgba(0, 200, 200, 0.15);
    color: var(--layout-accent-cyan);
}

.panel-control-btn.minimize:hover {
    background: rgba(255, 200, 100, 0.15);
    color: var(--palette-warning);
}

.panel-drag-handle {
    cursor: grab;
    padding: var(--cc-padding-small) var(--cc-padding-medium);
    margin: 0 -4px;
}

.panel-drag-handle:active {
    cursor: grabbing;
}

.panel-content::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

.panel-content::-webkit-scrollbar-track {
    background: rgba(0, 0, 0, 0.2);
}

.panel-content::-webkit-scrollbar-thumb {
    background: var(--layout-accent-primary-soft) !important;
    border-radius: var(--cc-radius-slight);
}

.panel-content::-webkit-scrollbar-thumb:hover {
    background: var(--layout-accent-primary) !important;
}

.panel-footer {
    display: flex;
    align-items: center;
    padding: var(--cc-padding-medium) var(--cc-padding-large);
    background: var(--layout-bg-panel-header);
    border-top: 1px solid var(--layout-border-color);
    font-size: var(--cc-font-size-small);
    color: var(--palette-text-muted);
}

.resize-handle {
    position: relative;
    background: transparent;
    transition: zz var(--layout-transition-fast);
    flex-shrink: 0;
}

.resize-handle[data-panel-group-direction="horizontal"],
.resize-handle.horizontal {
    width: var(--layout-resize-handle-size);
    cursor: col-resize;
}

.resize-handle[data-panel-group-direction="vertical"],
.resize-handle.vertical {
    height: var(--layout-resize-handle-size);
    cursor: row-resize;
}

.resize-handle::before {
    content: '';
    position: absolute;
    background: var(--layout-accent-cyan);
    opacity: 0;
    transition: opacity var(--layout-transition-fast);
}

.resize-handle[data-panel-group-direction="horizontal"]::before,
.resize-handle.horizontal::before {
    top: 20%;
    bottom: 20%;
    left: 50%;
    width: 2px;
    transform: translateX(-50%);
    transition: width .1s ease;
}

.resize-handle[data-panel-group-direction="vertical"]::before,
.resize-handle.vertical::before {
    left: 20%;
    right: 20%;
    top: 50%;
    height: 2px;
    transform: translateY(-50%);
}

.resize-handle:hover::before {
    opacity: 0.5;
}

.resize-handle:active::before,
.resize-handle[data-resize-handle-active]::before {
    opacity: 1;
}

.resize-handle:hover {
    background: rgba(0, 200, 200, 0.05);
}

.resize-handle:active,
.resize-handle[data-resize-handle-active] {
    background: rgba(0, 200, 200, 0.1);
}

.panel-group {
    display: flex;
    height: 100%;
    width: 100%;
}

.panel-group.horizontal {
    flex-direction: row;
}

.panel-group.vertical {
    flex-direction: column;
}

.widget-container {
    height: 100%;
    width: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.widget-empty {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: var(--palette-text-dim);
    font-size: var(--cc-font-size-small);
    font-style: italic;
}

.widget-placeholder {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    height: 100%;
    padding: var(--cc-padding-huge);
    border: 2px dashed var(--layout-border-color);
    border-radius: var(--layout-panel-radius);
    background: rgba(0, 200, 200, 0.02);
    color: var(--palette-text-muted);
    font-size: var(--cc-font-size-small);
    text-align: center;
    transition: all var(--layout-transition-normal);
}

.widget-placeholder:hover {
    border-color: var(--layout-accent-cyan-dim);
    background: rgba(0, 200, 200, 0.05);
}

.widget-placeholder.drag-over {
    border-color: var(--layout-accent-cyan);
    background: rgba(0, 200, 200, 0.1);
    box-shadow: inset 0 0 20px rgba(0, 200, 200, 0.1);
}

.widget-placeholder-icon {
    font-size: var(--cc-font-size-large);
    margin-bottom: 8px;
    color: var(--layout-accent-cyan-dim);
}

.panel-tabs {
    display: flex;
    gap: var(--cc-gap-small);
    padding: var(--cc-padding-small) var(--cc-padding-medium);
    background: var(--layout-bg-panel-header);
    border-bottom: 1px solid var(--layout-border-color);
    overflow-x: auto;
}

.panel-tab {
    display: flex;
    align-items: center;
    gap: var(--cc-gap-large);
    padding: var(--cc-padding-small) var(--cc-padding-large);
    background: transparent;
    border: none;
    border-radius: var(--cc-radius-slight) var(--cc-radius-slight) var(--cc-radius-none) var(--cc-radius-none);
    color: var(--palette-text-subtle);
    font-size: var(--cc-font-size-small);
    cursor: pointer;
    transition: all var(--layout-transition-fast);
    white-space: nowrap;
}

.panel-tab:hover {
    background: rgba(0, 200, 200, 0.08);
    color: var(--palette-text-soft);
}

.panel-tab.active {
    background: var(--layout-bg-panel);
    color: var(--layout-accent-cyan);
    border-bottom: 2px solid var(--layout-accent-cyan);
}

.panel-tab-icon {
    font-size: var(--cc-font-size-small);
}

.panel-tab-close {
    width: 14px;
    height: 14px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--cc-radius-slight);
    font-size: var(--cc-font-size-small);
    opacity: 0;
    transition: opacity var(--layout-transition-fast);
}

.panel-tab:hover .panel-tab-close {
    opacity: 0.6;
}

.panel-tab-close:hover {
    opacity: 1;
    background: rgba(255, 100, 100, 0.2);
    color: var(--palette-danger);
}

.layout-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(4px);
    z-index: 16;
    display: flex;
    align-items: center;
    justify-content: center;
}

.layout-maximized-panel {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 12;
    margin: 8px;
}

.drop-zone {
    position: absolute;
    background: rgba(0, 229, 229, 0.1);
    border: 2px dashed var(--layout-accent-cyan);
    border-radius: var(--layout-panel-radius);
    pointer-events: none;
    opacity: 0;
    transition: opacity var(--layout-transition-fast);
}

.drop-zone.active {
    opacity: 1;
}

.drop-zone.left {
    top: 0;
    left: 0;
    width: 50%;
    height: 100%;
}

.drop-zone.right {
    top: 0;
    right: 0;
    width: 50%;
    height: 100%;
}

.drop-zone.top {
    top: 0;
    left: 0;
    width: 100%;
    height: 50%;
}

.drop-zone.bottom {
    bottom: 0;
    left: 0;
    width: 100%;
    height: 50%;
}

.drop-zone.center {
    top: 25%;
    left: 25%;
    width: 50%;
    height: 50%;
}

.panel-enter {
    opacity: 0;
    transform: scale(0.95);
}

.panel-enter-active {
    opacity: 1;
    transform: scale(1);
    transition: opacity 0.2s ease, transform 0.2s ease;
}

.panel-exit {
    opacity: 1;
    transform: scale(1);
}

.panel-exit-active {
    opacity: 0;
    transform: scale(0.95);
    transition: opacity 0.15s ease, transform 0.15s ease;
}

.layout-no-select {
    user-select: none;
    -webkit-user-select: none;
}

.layout-hidden {
    display: none !important;
}

.layout-flex-grow {
    flex-grow: 1;
}

.layout-flex-shrink-0 {
    flex-shrink: 0;
}

.tile-layout.resizing {
    cursor: col-resize;
}

.tile-layout.resizing .panel {
    pointer-events: none;
    user-select: none;
}

.tile-layout-empty,
.tile-layout-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    width: 100%;
    color: var(--palette-text-muted);
    font-size: var(--cc-font-size-medium);
    font-style: italic;
    background: var(--layout-bg-panel);
    border-radius: var(--layout-panel-radius);
}

.tile-layout-container {
    height: 100%;
    width: 100%;
    display: flex;
    flex-direction: column;
}

.panel-wrapper {
    position: relative;
    height: 100%;
    width: 100%;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    min-height: 0;
    cursor: default !important;
}

.panel-wrapper>.panel {
    flex: 1;
    min-height: 0;
}

.panel-wrapper .panel-header {
    cursor: grab;
}

.panel-wrapper .panel-header:active {
    cursor: grabbing;
}

.panel-wrapper.dragging {
    opacity: 0.5;
    border: 2px dashed var(--layout-accent-orange);
    border-radius: var(--layout-panel-radius);
    background: rgba(255, 107, 53, 0.1);
    cursor: grabbing !important;
}

.panel-wrapper.drop-target {
    border: 2px solid var(--layout-accent-cyan);
    border-radius: var(--layout-panel-radius);
    box-shadow: 0 0 20px rgba(0, 229, 229, 0.3);
    background: rgba(0, 229, 229, 0.1);
}

/* Drop zone overlays */

.drop-zone-overlay {
    position: absolute;
    pointer-events: none;
    z-index: 6;
    background: rgba(0, 229, 229, 0.12);
    border: 2px solid rgba(0, 229, 229, 0.4);
    border-radius: var(--cc-radius-slight);
    transition: all 0.1s ease;
}

.drop-zone-center {
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
}

.drop-zone-top {
    top: 0;
    left: 0;
    right: 0;
    height: 50%;
}

.drop-zone-bottom {
    bottom: 0;
    left: 0;
    right: 0;
    height: 50%;
}

.drop-zone-left {
    top: 0;
    left: 0;
    bottom: 0;
    width: 50%;
}

.drop-zone-right {
    top: 0;
    right: 0;
    bottom: 0;
    width: 50%;
}

/* Stack column container */

.stack-column {
    height: 100%;
    width: 100%;
}

.tile-layout-nested {
    height: 100%;
    width: 100%;
}

.resizable-panel {
    height: 100%;
    overflow: hidden;
    contain: layout style paint;
}

[data-group] {
    height: 100%;
    width: 100%;
}

[data-panel] {
    height: 100%;
    overflow: hidden;
}

[data-separator] {
    flex-shrink: 0;
    transition: background-color 0.15s ease;
    position: relative;
    z-index: 6;
    touch-action: none;
}

[data-group][aria-orientation="horizontal"]>[data-separator],
[data-group][data-orientation="horizontal"]>[data-separator] {
    width: var(--layout-resize-handle-size);
    cursor: col-resize !important;
}

[data-group][aria-orientation="vertical"]>[data-separator],
[data-group][data-orientation="vertical"]>[data-separator] {
    height: 10px;
    cursor: row-resize !important;
}

[data-separator]:hover,
[data-separator="active"] {
    background: rgba(0, 200, 200, 0.4);
}

[data-separator]::after {
    content: '';
    position: absolute;
    background: var(--layout-accent-cyan);
    opacity: 0.4;
    transition: opacity 0.15s ease;
    pointer-events: none;
}

[data-group][aria-orientation="horizontal"]>[data-separator]::after,
[data-group][data-orientation="horizontal"]>[data-separator]::after {
    top: 30%;
    bottom: 30%;
    left: 50%;
    width: 2px;
    transform: translateX(-50%);
}

[data-group][aria-orientation="vertical"]>[data-separator]::after,
[data-group][data-orientation="vertical"]>[data-separator]::after {
    left: 30%;
    right: 30%;
    top: 50%;
    height: 2px;
    transform: translateY(-50%);
}

[data-separator]:hover::after,
[data-separator="active"]::after {
    opacity: 1;
}

@media (max-width: 768px) {
    :root {
        --layout-header-height: 32px;
        --layout-resize-handle-size: 2px;
    }

    .panel-header-title {
        font-size: var(--cc-font-size-small);
    }

    .panel-control-btn {
        height: 28px;
    }
}

@supports (corner-shape: bevel) {

    .control-bar-dock--macos,
    .panel,
    .panel-header,
    .notes-drawer,
    .media-floating-panel,
    .media-panel-close-btn,
    .media-error,
    .media-dropzone,
    .media-browse-button,
    .media-stage,
    .media-audio-card,
    .media-controls,
    .media-control-btn,
    .media-playlist,
    .media-playlist-actions button,
    .media-track-actions button,
    .media-track-row,
    .source-header,
    .source-item,
    .log-section,
    .log-header-btn,
    .log-filter-select,
    .action-btn,
    .suggestion-chip,
    .chat-thread,
    .task-item,
    .task-progress,
    .record-btn,
    .chat-message,
    .tool-message,
    .config-warning,
    .task-input,
    .task-add-btn,
    .overall-progress,
    .progress-bar-container,
    .file-tree-item.selected,
    .modal-container,
    .settings-input,
    .settings-toggle-btn,
    .settings-choose-chatview-btn,
    .settings-radio,
    .modal-btn,
    .view-sessions-btn,
    .session-item,
    .session-action-btn,
    .back-btn,
    .playback-controls,
    .event-item,
    .token-usage,
    .context-file,
    .interaction-panel.drop-active,
    .drop-overlay,
