.chat-input-wrapper {
    background: var(--ui-chat-input-bg);
    background-clip: padding-box;
}

.panel.sources-panel .panel-header,
.panel.tasks-panel .panel-header {
    border-radius: var(--cc-radius-none) !important;
}

/* ===== START OF Briizify.css ===== */

/* briizify — Tasks Panel prioritize feature.
   Every color rides an app.css theme token (with conservative
   fallbacks); the glassy translucent card language echoes the
   rest of briizOS rather than any external reference. */

.briizify-section {
    --bzf-accent: var(--palette-accent-primary, #00e5e5);
    --bzf-glow: var(--palette-neon-accent, #00ff88);
    --bzf-warn: var(--palette-warning, #ffd54f);
    --bzf-danger: var(--palette-danger, #ff6b6b);
    --bzf-orange: var(--layout-accent-orange, #ff6b35);
    --bzf-violet: #bd00ff;
    /* matches TasksPanel status accent */
    --bzf-text: var(--palette-text-main, #eee);
    --bzf-text-soft: var(--palette-accent-primary-soft, #aaa);
    --bzf-text-muted: var(--palette-text-muted, #666);
    --bzf-radius: var(--ui-border-radius, 16px);
    --bzf-glass: rgba(255, 255, 255, 0.08);
    --bzf-glass-strong: rgba(255, 255, 255, 0.14);
    /* static on purpose: the corner tab positions against .tasks-panel */
    position: static;
    font-family: var(--ui-font-main, inherit);
    padding-left: 6%;
    padding-right: 6%;
    scrollbar-width: none;
    flex: 1;
}

.briizify-section::-webkit-scrollbar,
.bzf-drawer::-webkit-scrollbar {
    display: none;
}

.tasks-panel {
    position: relative;
}

/* ── floating corner tab (pins over the Phantom row) ─────────── */

.briizify-tab-dock {
    position: absolute;
    right: 6px;
    bottom: 0;
    z-index: 7;
    display: flex;
    width: 25%;
    height: 30px;
    overflow: hidden;
    border: 1px solid color-mix(in srgb, var(--bzf-orange) 60%, transparent);
    border-bottom: none;
    border-radius: 10px 10px 0 0;
    box-shadow: 0 -4px 14px rgba(0, 0, 0, 0.35);
    transition: width 220ms cubic-bezier(0.22, 1, 0.36, 1), height 220ms cubic-bezier(0.22, 1, 0.36, 1);
}

.briizify-tab-dock:hover:not(.engaged) {
    height: 35px;
    width:50%;
}

.briizify-tab-dock.engaged {
    height: 70px;
    width: 50%;
}

.briizify-tab {
    flex: 1;
    min-width: 30% !important;
    display: inline-flex;
    align-items: baseline;
    gap: 6px;
    padding: 5px 14px 6px;
    border: none;
    background: linear-gradient(180deg, color-mix(in srgb, var(--bzf-orange) 78%, #ffd28a), color-mix(in srgb, var(--bzf-orange) 55%, #442200));
    color: #1a0e00 !important;
    cursor: pointer;
    transition: filter var(--layout-transition-fast, 0.15s ease);
}

.briizify-tab:hover {
    filter: saturate(0) brightness(1.12);
}

.briizify-tab:active,
.briizify-tab-dock.engaged .briizify-tab {
    filter: saturate(1.2);
}

.briizify-tab-strong {
    font-weight: 700;
    font-size: var(--cc-font-size-small);
    letter-spacing: 0.01em;
    color: black;
}

.briizify-tab-soft {
    font-weight: 400;
    font-size: var(--cc-font-size-tiny);
    opacity: 0.85;
    color: darkred;
}

.briizify-focus-btn {
    flex: 0 0 clamp(76px, 24%, 104px);
    border: none;
    border-left: 1px solid color-mix(in srgb, var(--bzf-violet) 48%, transparent);
    background: color-mix(in srgb, var(--bzf-violet) 24%, var(--bzf-orange));
    color: color-mix(in srgb, var(--bzf-text) 88%, var(--bzf-violet));
    font: italic 600 var(--cc-font-size-small) var(--ui-font-main, inherit);
    cursor: pointer;
    transition: filter 180ms ease-out, background-color 180ms ease-out;
}

.briizify-focus-btn:hover {
    filter: brightness(1.16) saturate(1.08);
}

.briizify-focus-btn:active {
    filter: brightness(0.92) saturate(1.25);
}

.briizify-tab-dock.focused .briizify-focus-btn {
    background: color-mix(in srgb, var(--bzf-violet) 58%, var(--bzf-orange));
    color: var(--bzf-text);
}

.briizify-tab:focus-visible,
.briizify-focus-btn:focus-visible {
    position: relative;
    z-index: 1;
    outline: 2px solid color-mix(in srgb, var(--bzf-text) 86%, var(--bzf-violet));
    outline-offset: -3px;
}

/* ── logo ────────────────────────────────────────────────────── */

.briizify-logo {
    font-family: var(--ui-font-main, inherit);
    font-weight: 600;
    font-size: var(--cc-font-size-small);;
    background: var(--ui-header-bg);
    color:transparent;
    background-clip: text;
    filter:hue-rotate(180deg)invert(1);
    letter-spacing: 0.01em;
    user-select: none;
    margin:0;

}

.briizify-logo.rail {
    margin-top: auto;
    padding: 6px 2px 2px;
    font-size: 15px;
}

/* ── setup drawer ────────────────────────────────────────────── */

.bzf-drawer {
    position: relative;
    margin: 4px 6px 2px;
    padding: 8px 10px 10px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: calc(var(--bzf-radius) * 0.75);
    background: linear-gradient(165deg, var(--bzf-glass), transparent 55%), rgba(0, 0, 0, 0.35);
    backdrop-filter: blur(6px);
    max-height: 46vh;
    overflow-y: auto;
    border: .5px solid var(--palette-accent-primary-soft);
}

.bzf-drawer-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.bzf-close {
    border: none;
    background: transparent;
    color: var(--bzf-text-muted);
    font-size: 13px;
    cursor: pointer;
}

.bzf-close:hover {
    color: var(--bzf-text);
}

.bzf-body {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.bzf-main {
    display: flex;
    gap: 10px;
    align-items: stretch;
}

.bzf-sec {
    position: relative;
    padding: 8px;
    border: 1px solid transparent;
    border-radius: 10px;
    transition: border-color var(--layout-transition-normal, 0.2s ease);
}

.bzf-sec.active {
    border-color: color-mix(in srgb, var(--bzf-glow) 45%, transparent);
    background: color-mix(in srgb, var(--bzf-glow) 4%, transparent);
}

.bzf-row {
    display: flex;
    gap: 6px;
    align-items: center;
    flex-wrap: wrap;
}

.bzf-frame-chip {
    padding: 3px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.16);
    background: var(--bzf-glass);
    color: var(--bzf-text-soft);
    font-size: 12px;
    cursor: pointer;
}

.bzf-frame-chip.active {
    color: black;
    border-color: color-mix(in srgb, var(--bzf-warn) 55%, transparent);
    background:var(--bzf-orange);
}

.bzf-check {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 6px;
    font-size: 11.5px;
    color: var(--bzf-text-soft);
    cursor: pointer;
    user-select: none;
}

/* channel switches */

.bzf-channels {
    display: flex;
    flex-wrap: wrap;
    gap: 10px 18px;
}

.bzf-channel {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    cursor: pointer;
}

.bzf-channel-label {
    font-size: 12px;
    font-weight: 600;
    color: var(--bzf-warn);
}

.bzf-switch {
    position: relative;
    width: 60px;
    height: 12px;
    border-radius: 999px;
    border: 1px solid color-mix(in srgb, var(--bzf-glow) 45%, transparent);
    background: rgba(0, 0, 0, 0.4);
    cursor: pointer;
    transition: background var(--layout-transition-fast, 0.15s ease);
}

.bzf-switch.on {
    background: color-mix(in srgb, #6a76ff 55%, rgba(0, 0, 0, 0.4));
}

.bzf-switch-knob {
    position: absolute;
    top: -4px;
    left: 2px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    height: 18px;
    padding: 0 3px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.9);
    color: #223;
    font-size: 7.5px;
    font-weight: 700;
    transition: transform var(--layout-transition-fast, 0.15s ease);
}

.bzf-switch.on .bzf-switch-knob {
    transform: translateX(40px);
}

.bzf-switch:not(.on) .bzf-switch-knob {
    background: rgba(255, 255, 255, 0.45);
}

/* PROCEED — only one on screen at a time */

.bzf-proceed-slot {
    display: flex;
    align-items: center;
    gap: 8px;
    justify-content: flex-end;
    margin-top: 8px;
}

.bzf-proceed-hint {
    font-size: 10.5px;
    color: var(--bzf-text-muted);
}

.bzf-proceed {
    padding: 5px 18px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.35);
    background: rgba(255, 255, 255, 0.06);
    color: var(--bzf-text);
    font-size: 11.5px;
    letter-spacing: 0.08em;
    cursor: pointer;
    transition: background var(--layout-transition-fast, 0.15s ease), box-shadow var(--layout-transition-fast, 0.15s ease);
}

.bzf-proceed:hover:not(:disabled) {
    background: color-mix(in srgb, var(--bzf-glow) 14%, transparent);
    box-shadow: 0 0 12px color-mix(in srgb, var(--bzf-glow) 25%, transparent);
}

.bzf-proceed:disabled {
    opacity: 0.4;
    cursor: default;
}

/* miniCal time-range picker */

.bzf-sec-minical {
    width: 178px;
    flex-shrink: 0;
}

.bzf-minical-hint {
    font-size: 9.5px;
    color: var(--bzf-text-muted);
    margin-bottom: 4px;
}

.bzf-minical {
    display: flex;
    gap: 8px;
}

.bzf-minical-track {
    position: relative;
    width: 46px;
    height: 190px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: repeating-linear-gradient(to bottom, transparent 0 11px, rgba(255, 255, 255, 0.06) 11px 12px), rgba(0, 0, 0, 0.35);
    touch-action: none;
}

.bzf-minical-block {
    position: absolute;
    left: 4px;
    right: 4px;
    border-radius: 3px;
    background: color-mix(in srgb, var(--bzf-danger) 40%, rgba(255, 255, 255, 0.08));
    min-height: 3px;
}

.bzf-minical-selection {
    position: absolute;
    left: 0;
    right: 0;
    background: linear-gradient(180deg, color-mix(in srgb, var(--bzf-violet) 30%, transparent), color-mix(in srgb, var(--bzf-accent) 24%, transparent));
    border-left: 2px solid color-mix(in srgb, var(--bzf-glow) 50%, transparent);
}

.bzf-minical-handle {
    position: absolute;
    left: -12px;
    right: -12px;
    height: 44px;
    padding: 0;
    transform: translateY(-22px);
    border: none;
    background: transparent;
    cursor: ns-resize;
    z-index: 2;
    touch-action: none;
    user-select: none;
    -webkit-user-select: none;
    -webkit-app-region: no-drag;
    outline: none;
}

.bzf-minical-handle::before {
    content: '';
    position: absolute;
    left: 0;
    right: 0;
    top: 21px;
    height: 2px;
    border-radius: 999px;
    background: var(--bzf-warn);
    box-shadow: 0 0 6px color-mix(in srgb, var(--bzf-warn) 60%, transparent);
    transition: height 140ms ease, box-shadow 140ms ease, opacity 140ms ease;
}

.bzf-minical-handle::after {
    content: '';
    position: absolute;
    top: 17px;
    left: 50%;
    width: 18px;
    height: 10px;
    border: 1px solid color-mix(in srgb, var(--bzf-warn) 76%, white);
    border-radius: 999px;
    background: color-mix(in srgb, var(--bzf-warn) 55%, rgba(15, 18, 25, 0.92));
    box-shadow: 0 0 8px color-mix(in srgb, var(--bzf-warn) 40%, transparent);
    transform: translateX(-50%) scale(0.78);
    transition: transform 140ms ease, background 140ms ease, box-shadow 140ms ease;
}

.bzf-minical-handle span {
    position: absolute;
    left: calc(100% + 4px);
    top: 50%;
    transform: translateY(-50%);
    white-space: nowrap;
    font-size: 9px;
    letter-spacing: 0.06em;
    color: var(--bzf-text-soft);
    background: rgba(0, 0, 0, 0.55);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 4px;
    padding: 1px 5px;
    pointer-events: none;
    transition: color 140ms ease, border-color 140ms ease, background 140ms ease;
}

.bzf-minical-handle:hover::before,
.bzf-minical-handle.is-dragging::before {
    height: 3px;
    box-shadow: 0 0 10px color-mix(in srgb, var(--bzf-warn) 78%, transparent);
}

.bzf-minical-handle:hover::after,
.bzf-minical-handle:focus-visible::after,
.bzf-minical-handle.is-dragging::after {
    transform: translateX(-50%) scale(1);
    background: color-mix(in srgb, var(--bzf-warn) 76%, rgba(15, 18, 25, 0.92));
    box-shadow: 0 0 12px color-mix(in srgb, var(--bzf-warn) 64%, transparent);
}

.bzf-minical-handle:focus-visible::after {
    outline: 2px solid color-mix(in srgb, var(--bzf-glow) 72%, white);
    outline-offset: 2px;
}

.bzf-minical-handle:hover span,
.bzf-minical-handle:focus-visible span,
.bzf-minical-handle.is-dragging span {
    color: var(--bzf-text);
    border-color: color-mix(in srgb, var(--bzf-warn) 48%, rgba(255, 255, 255, 0.18));
    background: rgba(0, 0, 0, 0.76);
}

.bzf-minical-handle.is-dragging {
    cursor: grabbing;
    z-index: 4;
}

.bzf-minical-stats {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    gap: 2px;
    padding-bottom: 2px;
}

.bzf-minical-stat-big {
    font-size: 16px;
    color: var(--bzf-text);
}

.bzf-minical-stat-small {
    font-size: 9.5px;
    color: var(--bzf-text-muted);
    max-width: 96px;
}

/* candidates */

.bzf-sec-options {
    flex: 1;
    min-width: 0;
}

.bzf-source-label {
    font-size: 10px;
    letter-spacing: 0.22em;
    color: var(--bzf-text-soft);
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
    padding-bottom: 3px;
    margin: 8px 0 6px;
}

.bzf-source-label:first-child {
    margin-top: 0;
}

.bzf-chip-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 5px 8px;
}

.bzf-candidate {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 2px 10px;
    border-radius: 999px;
    border: 1px solid transparent;
    background: transparent;
    color: var(--bzf-text-soft);
    font-size: 12px;
    cursor: pointer;
    max-width: 100%;
}

.bzf-candidate:hover {
    color: var(--bzf-text);
}

.bzf-candidate.selected {
    color: #f4e9d6;
    border-color: color-mix(in srgb, var(--bzf-warn) 55%, transparent);
    background: linear-gradient(180deg, color-mix(in srgb, var(--bzf-warn) 26%, rgba(60, 42, 12, 0.7)), rgba(38, 26, 8, 0.7));
    font-size: 13px;
}

.bzf-candidate-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: rgba(240, 255, 240, 0.85);
    color: #2a3a2a;
    font-size: 9px;
    font-weight: 700;
}

.bzf-candidate-remove {
    border: none;
    background: transparent;
    color: inherit;
    opacity: 0.7;
    font-size: 10px;
    cursor: pointer;
}

.bzf-exogenous {
    display: flex;
    gap: 6px;
    margin-top: 10px;
}

.bzf-input {
    flex: 1;
    min-width: 0;
    padding: 5px 10px;
    border-radius: 8px;
    border: 1px solid var(--ui-settings-input-border, rgba(255, 255, 255, 0.15));
    background: var(--ui-settings-input-bg, rgba(0, 0, 0, 0.35));
    color: var(--ui-settings-input-text, var(--bzf-text));
    font-size: 11.5px;
}

.bzf-input::placeholder {
    color: var(--ui-settings-input-placeholder, var(--bzf-text-muted));
    font-size: 10px;
    letter-spacing: 0.05em;
}

.bzf-mini-btn {
    padding: 0 10px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: var(--bzf-glass);
    color: var(--bzf-text);
    cursor: pointer;
}

.bzf-mini-btn:disabled {
    opacity: 0.35;
    cursor: default;
}

.bzf-muted {
    font-size: 11px;
    color: var(--bzf-text-muted);
}

/* clarify + thinking + error */

.bzf-clarify {
    padding: 6px 2px;
}

.bzf-clarify-question {
    font-size: 12.5px;
    color: var(--bzf-warn);
    margin-bottom: 8px;
}

.bzf-clarify-form {
    display: flex;
    gap: 6px;
}

.bzf-thinking {
    margin-top: 8px;
    font-size: 11.5px;
    color: var(--bzf-glow);
    letter-spacing: 0.04em;
}

.bzf-dots::after {
    content: '…';
    animation: bzf-pulse 1.2s infinite;
}

@keyframes bzf-pulse {

    0%,
    100% {
        opacity: 0.35;
    }

    50% {
        opacity: 1;
    }
}

.bzf-error {
    margin-top: 8px;
    font-size: 11px;
    color: var(--bzf-danger);
}

/* ── priorifact (ambient artifact) ───────────────────────────── */

.priorifact {
    position: relative;
    margin: 4px 26px 12px;
    padding: 14px 10px 18px;
    border-radius: calc(var(--bzf-radius) * 0.85);
    border: 1.5px solid var(--palette-accent-primary);
    background: linear-gradient(120deg, color-mix(in srgb, var(--bzf-accent) 16%, transparent), color-mix(in srgb, var(--bzf-violet) 14%, transparent) 60%, color-mix(in srgb, var(--bzf-violet) 22%, transparent)), linear-gradient(165deg, var(--bzf-glass-strong), transparent 60%), rgba(0, 0, 0, 0.3);
    backdrop-filter: blur(0px);
    box-shadow: 0 0 14px inset var(--palette-accent-primary), 0 -5px 8px lightgreen, 0 5px 6px orange, 0 0 5px blue, 0 0 5px deeppink;
    transform: scale(1.13);
    border-radius: var(--ui-border-radius);
    corner-shape: var(--ui-corner-shape);
}

/* Focus mode makes the priorifact the Tasks workspace while keeping
   the task header, overall progress, and Phantom dock in place. */

.briizify-section.focused {
    flex: 100 1 0;
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    min-height: 0;
    overflow: hidden;
    padding: 0 6%;
}

.briizify-section.focused::before {
    content: '';
    position: absolute;
    z-index: -1;
    inset: 4% 2% 7%;
    background: radial-gradient(ellipse at 18% 52%, color-mix(in srgb, var(--bzf-warn) 9%, transparent), transparent 46%), radial-gradient(ellipse at 78% 52%, color-mix(in srgb, var(--bzf-violet) 11%, transparent), transparent 52%);
    opacity: 0.8;
    pointer-events: none;
}

.briizify-section.focused .priorifact {
    width: min(100%, 1180px);
    min-height: clamp(280px, 46vh, 420px);
    box-sizing: border-box;
    margin: 0 auto;
    padding: clamp(52px, 9vh, 80px) clamp(28px, 3.5vw, 40px);
    transform: scale(1.03);
    transition: transform 240ms cubic-bezier(0.22, 1, 0.36, 1), opacity 180ms ease-out;
}

.briizify-section.focused .priorifact-rail {
    position: absolute;
    top: clamp(52px, 9vh, 80px);
    bottom: clamp(52px, 9vh, 80px);
    left: clamp(28px, 3.5vw, 40px);
}

.briizify-section.focused .priorifact-main {
    margin-left: 116px;
    justify-content: center;
}

.briizify-section.focused .bzf-timeline {
    margin-top: 14px;
    margin-bottom: 12px;
}

.briizify-section.focused .bzf-cards.focused-overview {
    gap: clamp(8px, 1vw, 16px);
    padding-top: 6px;
    padding-bottom: 10px;
}

.briizify-section.focused .focused-overview .bzf-card {
    width: clamp(112px, 14%, 156px);
    min-height: 116px;
    padding: 10px;
}

.briizify-section.focused .focused-overview .bzf-card.current {
    width: clamp(146px, 18%, 190px);
}

.briizify-section.focused .focused-overview .bzf-card.break {
    width: clamp(58px, 7%, 78px);
}

.bzf-toggle-row {
    position: absolute;
    top: -9px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 10px;
    max-width: calc(100% - 18px);
    padding: 0 12px;
    border-radius: 999px;
    background: var(--ui-body-bg);
    border: 1px solid rgba(255, 255, 255, 0.12);
    white-space: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
    z-index: 2;
}

.bzf-toggle-row::-webkit-scrollbar {
    display: none;
}

.bzf-toggle-channels,
.bzf-flow-actions {
    display: flex;
    align-items: center;
    gap: 14px;
}

.bzf-flow-actions {
    gap: 10px;
}

.bzf-toggle-divider {
    width: 1px;
    height: 12px;
    flex: 0 0 1px;
    background: rgba(255, 255, 255, 0.22);
}

.bzf-toggle {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    border: none;
    background: transparent;
    color: var(--bzf-text-soft);
    font-size: 11.5px;
    cursor: pointer;
    padding: 2px 0;
}

.bzf-toggle-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: currentColor;
    opacity: 0.55;
}

.bzf-toggle:hover {
    color: var(--bzf-text);
}

.bzf-toggle.active {
    color: #fff;
    text-shadow: 0 0 8px rgba(255, 255, 255, 0.6);
}

.bzf-toggle.active .bzf-toggle-dot {
    opacity: 1;
}

.bzf-toggle:focus-visible,
.bzf-flow-action:focus-visible,
.priorifact-extend:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--bzf-glow) 80%, white);
    outline-offset: 2px;
}

.bzf-flow-action {
    border: none;
    background: transparent;
    color: color-mix(in srgb, var(--bzf-glow) 78%, var(--bzf-text));
    font-size: 11.5px;
    font-weight: 650;
    cursor: pointer;
    padding: 2px 0;
    transition: color 180ms ease-out, opacity 180ms ease-out;
}

.bzf-flow-action:hover:not(:disabled) {
    color: #fff;
}

.bzf-flow-action:active:not(:disabled) {
    opacity: 0.68;
}

.bzf-flow-action.complete {
    color: color-mix(in srgb, var(--bzf-glow) 72%, white);
}

.bzf-flow-action:disabled {
    cursor: default;
    opacity: 0.62;
}

.bzf-flow-action.pause.active {
    color: color-mix(in srgb, var(--palette-warning) 82%, white);
    text-shadow: 0 0 8px color-mix(in srgb, var(--palette-warning) 34%, transparent);
}

.priorifact-body {
    display: flex;
    gap: 10px;
    align-items: stretch;
}

/* left rail: chips in original order + logo */

.priorifact-rail {
    display: flex;
    flex-direction: column;
    gap: 5px;
    width: 96px;
    flex-shrink: 0;
}

.bzf-chip {
    position: relative;
    overflow: hidden;
    padding: 3px 10px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.16);
    background: color-mix(in srgb, #16303f 75%, transparent);
    color: var(--bzf-text-soft);
    font-size: 11px;
    text-align: left;
    cursor: pointer;
}

.bzf-chip.done {
    opacity: 0.45;
}

.bzf-chip.current {
    border-color: color-mix(in srgb, var(--bzf-warn) 50%, transparent);
    background: color-mix(in srgb, #4a3a14 80%, transparent);
    color: var(--palette-warning);
    font-weight: 700;
}

.bzf-chip.current.in-progress {
    animation: bzf-active-breathe 3.8s ease-in-out infinite;
}

@keyframes bzf-active-breathe {

    0%,
    100% {
        opacity: 0.56;
    }

    50% {
        opacity: 1;
    }
}

.bzf-chip-fill {
    position: absolute;
    inset: 0 auto 0 0;
    background: linear-gradient(90deg, var(--bzf-glow), color-mix(in srgb, var(--bzf-glow) 65%, #baff90));
    transition: width 0.6s ease;
}

.bzf-chip-label {
    position: relative;
    z-index: 1;
}

.bzf-chip.current .bzf-chip-label {
    mix-blend-mode: normal;
}

/* main area */

.priorifact-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.priorifact-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    flex-wrap: wrap;
}

.priorifact-clock {
    font-size: 15px;
    font-weight: 700;
    color: #fff;
}

.priorifact-target {
    position: absolute;
    right: 2%;
    top: 5%;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0;
}

.priorifact-extend {
    width: 22px;
    height: 18px;
    margin-right: -3px;
    border: none;
    background: transparent;
    color: color-mix(in srgb, var(--palette-warning) 86%, white);
    font-size: 18px;
    font-weight: 500;
    line-height: 1;
    cursor: pointer;
    opacity: 0.78;
    transition: opacity 180ms ease-out, transform 180ms cubic-bezier(0.22, 1, 0.36, 1);
}

.priorifact-extend:hover:not(:disabled) {
    opacity: 1;
    transform: translateY(-1px);
}

.priorifact-extend:active:not(:disabled) {
    transform: translateY(0);
}

.priorifact-extend:disabled {
    cursor: default;
    opacity: 0.25;
}

.priorifact-remaining {
    color: var(--palette-warning);
    font-size: var(--cc-font-size-large);
    line-height: 1;
    opacity: 0.72;
}

.priorifact-header-sep {
    color: rgba(255, 255, 255, 0.4);
    font-size: 11px;
}

.priorifact-header-btn {
    border: none;
    background: transparent;
    color: rgba(255, 255, 255, 0.85);
    font-size: 12.5px;
    cursor: pointer;
    padding: 0;
}

.priorifact-header-btn:hover:not(:disabled) {
    color: #fff;
    text-shadow: 0 0 8px rgba(255, 255, 255, 0.5);
}

.priorifact-header-btn:disabled {
    opacity: 0.4;
    cursor: default;
}

.priorifact-header-btn.danger {
    color: color-mix(in srgb, var(--bzf-danger) 80%, #fff);
}

.priorifact-header-btn.collapse {
    margin-left: auto;
}

.bzf-action-error {
    max-width: calc(100% - 8px);
    color: color-mix(in srgb, var(--bzf-danger) 82%, white);
    font-size: 10.5px;
    line-height: 1.25;
}

/* cards row */

.bzf-cards {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    padding: 2px 2px 6px;
    scrollbar-width: thin;
}

.bzf-cards.editing {
    flex-wrap: wrap;
    overflow-x: visible;
    gap: 10px;
    padding-bottom: 22px;
}

.bzf-card {
    position: relative;
    flex-shrink: 0;
    width: 108px;
    min-height: 88px;
    padding: 8px;
    border-radius: 14px;
    border: 1px solid rgba(255, 255, 255, 0.18);
    color: rgba(255, 255, 255, 0.92);
    display: flex;
    flex-direction: column;
    gap: 4px;
    background: linear-gradient(155deg, rgba(255, 255, 255, 0.16), transparent 45%), color-mix(in srgb, var(--bzf-accent) 30%, rgba(20, 40, 70, 0.6));
    opacity: .7;
}

.bzf-card.bzf-hue-1 {
    background: linear-gradient(155deg, rgba(255, 255, 255, 0.14), transparent 45%), color-mix(in srgb, var(--bzf-violet) 26%, rgba(30, 30, 80, 0.6));
}

.bzf-card.bzf-hue-2 {
    background: linear-gradient(155deg, rgba(255, 255, 255, 0.12), transparent 45%), color-mix(in srgb, var(--bzf-violet) 42%, rgba(40, 20, 70, 0.65));
}

.bzf-card.current {
    border-color: color-mix(in srgb, var(--bzf-warn) 60%, transparent);
    background: linear-gradient(155deg, rgba(255, 255, 255, 0.22), transparent 50%), color-mix(in srgb, var(--bzf-warn) 45%, rgba(90, 62, 14, 0.75));
    opacity: 1;
    width: 140px;
}

.bzf-card.current .bzf-card-title {
    font-weight: 600;
    font-size: var(--cc-font-size-medium);
}

.bzf-card.done {
    opacity: 0.5;
}

.bzf-card.dragging {
    opacity: 0.38;
}

.bzf-card.drop-target {
    border-color: color-mix(in srgb, var(--bzf-glow) 84%, white);
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--bzf-glow) 30%, transparent);
    transform: translateY(-3px);
}

.bzf-card.break {
    width: 54px;
    min-height: 88px;
    align-items: center;
    justify-content: center;
    border-style: dashed;
    background: rgba(255, 255, 255, 0.05);
    color: var(--bzf-text-soft);
}

.bzf-cards.editing .bzf-card.break {
    width: 76px;
}

.bzf-card-break-label {
    font-size: 10px;
    letter-spacing: 0.12em;
}

.bzf-card-top.break-time {
    width: 100%;
    justify-content: center;
}

.bzf-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.bzf-card-time {
    padding: 1px 8px;
    border-radius: 999px;
    background: rgba(0, 0, 0, 0.35);
    border: 1px solid rgba(255, 255, 255, 0.2);
    font-size: 10.5px;
}

.bzf-card-duration {
    font-size: 9.5px;
    opacity: 0.75;
}

.bzf-card-duration sup {
    font-size: 7px;
}

.bzf-card-title {
    margin-top: auto;
    font-size: 13px;
    line-height: 1.15;
    word-break: break-word;
}

.bzf-card-editable {
    min-width: 0;
    margin: 0;
    border: 1px dashed transparent;
    background: transparent;
    color: inherit;
    font: inherit;
    line-height: inherit;
    text-align: inherit;
    cursor: text;
    transition: border-color 180ms ease-out, background-color 180ms ease-out;
}

.bzf-card-editable:hover:not(:disabled) {
    border-color: rgba(255, 255, 255, 0.48);
    background: rgba(0, 0, 0, 0.12);
}

.bzf-card-editable:disabled {
    cursor: default;
    opacity: inherit;
}

.bzf-card-title.bzf-card-editable {
    width: 100%;
    padding: 2px;
}

.bzf-card-time.bzf-card-editable,
.bzf-card-duration.bzf-card-editable {
    padding: 1px 5px;
}

.bzf-card-editor {
    min-width: 0;
    border: 1px dashed color-mix(in srgb, var(--bzf-glow) 72%, white);
    border-radius: 7px;
    outline: none;
    background: rgba(3, 8, 18, 0.72);
    color: rgba(255, 255, 255, 0.96);
    font: inherit;
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--bzf-glow) 18%, transparent);
}

.bzf-card-time.bzf-card-editor {
    width: 72px;
    padding: 2px 4px;
    color-scheme: dark;
}

.bzf-card-duration.bzf-card-editor {
    width: 42px;
    padding: 2px 3px;
}

.bzf-card-title.bzf-card-editor {
    width: 100%;
    margin-top: auto;
    padding: 4px 5px;
    box-sizing: border-box;
}

.bzf-card-break-label.bzf-card-editor {
    width: calc(100% - 8px);
    padding: 3px;
    text-align: center;
    box-sizing: border-box;
}

.bzf-card-remove {
    position: absolute;
    top: 4px;
    right: 4px;
    border: none;
    border-radius: 50%;
    width: 16px;
    height: 16px;
    background: rgba(0, 0, 0, 0.45);
    color: rgba(255, 255, 255, 0.75);
    font-size: 9px;
    cursor: pointer;
    opacity: 0;
    transition: opacity var(--layout-transition-fast, 0.15s ease);
}

.bzf-card:hover .bzf-card-remove {
    opacity: 1;
}

.bzf-card-remove:disabled {
    cursor: default;
    opacity: 0.18;
}

.bzf-card-drag-handle {
    position: absolute;
    left: 50%;
    bottom: -20px;
    width: 48px;
    height: 18px;
    transform: translateX(-50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    border: none;
    background: transparent;
    cursor: grab;
}

.bzf-card-drag-handle:active {
    cursor: grabbing;
}

.bzf-card-drag-handle span {
    width: 34px;
    height: 2px;
    border-radius: 2px;
    background: rgba(255, 255, 255, 0.82);
    transition: width 180ms cubic-bezier(0.22, 1, 0.36, 1), opacity 180ms ease-out;
}

.bzf-card-drag-handle span:last-child {
    width: 26px;
    opacity: 0.58;
}

.bzf-card-drag-handle:hover:not(:disabled) span:first-child {
    width: 40px;
}

.bzf-card-drag-handle:disabled {
    cursor: default;
    opacity: 0.28;
}

.bzf-add-activity {
    align-self: stretch;
    width: 58px;
    min-height: 88px;
    margin-bottom: -2px;
    border: 1px dashed transparent;
    border-radius: 14px;
    background: transparent;
    color: rgba(255, 255, 255, 0.88);
    font-size: 50px;
    font-weight: 200;
    line-height: 1;
    cursor: pointer;
    transition: color 180ms ease-out, border-color 180ms ease-out, transform 180ms cubic-bezier(0.22, 1, 0.36, 1);
}

.bzf-add-activity:hover:not(:disabled) {
    color: color-mix(in srgb, var(--bzf-glow) 76%, white);
    border-color: rgba(255, 255, 255, 0.2);
    transform: translateY(-2px);
}

.bzf-add-activity:disabled {
    cursor: default;
    opacity: 0.3;
}

/* channel detail (borrows the miniCal space) */

.bzf-detail {
    display: flex;
    gap: 10px;
    align-items: stretch;
}

.bzf-detail-panel {
    flex: 1;
    min-width: 0;
    border-radius: 12px;
    background: rgba(0, 0, 0, 0.082);
    color: var(--palette-accent-neon);
    ;
    padding: 8px 12px;
    backdrop-filter: blur(4px);
    max-height: 120px;
    overflow-y: auto;
    scrollbar-width: none;
}

.bzf-detail-label {
    font-size: 12px;
    font-weight: 600;
    margin-bottom: 2px;
}

.bzf-detail-list {
    margin: 0;
    padding-left: 18px;
    font-size: 12.5px;
    line-height: 1.45;
}

.bzf-detail-panel .bzf-muted {
    color: #555;
}

/* expanded timeline */

.priorifact.expanded {
    max-height: 60vh;
    overflow-y: auto;
}

.bzf-timeline {
    position: relative;
    height: 26px;
    margin: 4px 6px 2px;
}

.bzf-timeline-track {
    position: absolute;
    left: 0;
    right: 0;
    top: 11px;
    height: 4px;
    border-radius: 2px;
    background: rgba(255, 255, 255, 0.22);
}

.bzf-timeline-progress {
    position: absolute;
    left: 0;
    top: 11px;
    height: 4px;
    border-radius: 2px;
    background: var(--bzf-glow);
    box-shadow: 0 0 8px color-mix(in srgb, var(--bzf-glow) 55%, transparent);
}

.bzf-timeline-marker {
    position: absolute;
    top: 6px;
    width: 13px;
    height: 13px;
    border-radius: 3px;
    transform: translateX(-50%);
    background: color-mix(in srgb, var(--bzf-accent) 70%, #2255aa);
}

.bzf-timeline-marker.current {
    background: var(--bzf-warn);
    box-shadow: 0 0 8px color-mix(in srgb, var(--bzf-warn) 60%, transparent);
}

.bzf-timeline-marker.done {
    background: color-mix(in srgb, var(--bzf-glow) 60%, #114422);
}

.bzf-timeline-marker.break {
    width: 7px;
    height: 7px;
    top: 9px;
    border-radius: 50%;
    background: rgba(255, 255, 255, 0.5);
}

.bzf-timeline-divider {
    position: absolute;
    top: -4px;
    bottom: -4px;
    width: 2px;
    transform: translateX(-50%);
    background: rgba(255, 255, 255, 0.85);
}

.bzf-timeline-divider span {
    position: absolute;
    top: -14px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 10px;
    color: rgba(255, 255, 255, 0.85);
    white-space: nowrap;
}

.priorifact-summary {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.75);
}

.priorifact-done {
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 12.5px;
    color: var(--bzf-glow);
    padding: 6px 2px;
}

.bzf-delete-plan {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 10px;
    margin-top: 10px;
    padding: 9px 2px 0;
    border-top: 1px solid rgba(255, 255, 255, 0.09);
    color: color-mix(in srgb, var(--bzf-danger) 70%, white);
    font-size: 11px;
}

.bzf-delete-plan button {
    border: none;
    background: transparent;
    color: rgba(255, 255, 255, 0.72);
    font: inherit;
    cursor: pointer;
    padding: 3px 5px;
}

.bzf-delete-plan button:hover {
    color: white;
}

.bzf-delete-plan button:disabled {
    cursor: default;
    opacity: 0.32;
}

.bzf-delete-plan button.danger {
    color: color-mix(in srgb, var(--bzf-danger) 78%, white);
}

.bzf-delete-plan.confirming {
    justify-content: flex-start;
    background: color-mix(in srgb, var(--bzf-danger) 7%, transparent);
}

.priorifact.paused .bzf-card.current {
    border-style: dashed;
    box-shadow: none;
}

.priorifact.paused .bzf-timeline-progress {
    opacity: 0.5;
}

.bzf-card-editable:focus-visible,
.bzf-card-drag-handle:focus-visible,
.bzf-add-activity:focus-visible,
.bzf-delete-plan button:focus-visible {
    outline: 2px solid color-mix(in srgb, var(--bzf-glow) 80%, white);
    outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
    .bzf-chip.current.in-progress {
        animation: none;
    }

    .briizify-tab-dock,
    .briizify-tab,
    .briizify-focus-btn,
    .briizify-section.focused .priorifact,
    .priorifact-extend,
    .bzf-flow-action,
    .bzf-card,
    .bzf-card-drag-handle span,
    .bzf-add-activity,
    .bzf-minical-handle::before,
    .bzf-minical-handle::after,
    .bzf-minical-handle span {
        transition: none;
    }
}

@media (max-width: 760px) {
    .briizify-tab-dock.engaged {
        width: min(72%, 360px);
    }

    .briizify-section.focused {
        align-items: flex-start;
        overflow-y: auto;
        padding: 34px 12px 82px;
    }

    .briizify-section.focused::before {
        inset: 0;
    }

    .briizify-section.focused .priorifact {
        min-height: 0;
        padding: 42px 16px 24px;
        transform: none;
    }

    .briizify-section.focused .priorifact-rail {
        position: static;
        width: 80px;
    }

    .briizify-section.focused .priorifact-main {
        margin-left: 0;
    }
}

/* ===== START OF BriiztormOverlay.css ===== */

/* =====================
   Briiztorm Overlay Styles
   ===================== */

.briiztorm-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--theme-components-overlays-briiztormoverlay-briiztorm-overlay-background-afq8i, #0a0a0a);
    z-index: 1200;
    display: flex;
    flex-direction: column;
    transform: translateY(-100%);
    transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* State: Opening/Open - slide down */

.briiztorm-overlay.opening,
.briiztorm-overlay.open,
.briiztorm-overlay.sleeping,
.briiztorm-overlay.closing {
    transform: translateY(0);
}

/* State: Closing - slide up after blur */

.briiztorm-overlay.closed {
    transform: translateY(-100%);
}

/* Header Bar */

.briiztorm-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 16px;
    background: var(--theme-components-overlays-briiztormoverlay-briiztorm-header-background-gradient, linear-gradient(90deg, rgba(0, 50, 70, 0.9) 0%, rgba(0, 30, 50, 0.9) 100%));
    border-bottom: 1px solid var(--theme-components-overlays-briiztormoverlay-briiztorm-header-border-bottom-1jdub, rgba(0, 200, 200, 0.3));
    flex-shrink: 0;
}

.briiztorm-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--palette-accent-cyan);
    text-transform: uppercase;
    letter-spacing: 1px;
    text-shadow: 0 0 10px var(--theme-components-overlays-briiztormoverlay-briiztorm-title-text-shadow-19dnh, rgba(0, 200, 200, 0.5));
}

.briiztorm-controls {
    display: flex;
    gap: 8px;
}

.briiztorm-btn {
    width: 1 28px;
    height: 28px;
    border-radius: 4px;
    border: 1px solid var(--theme-components-overlays-briiztormoverlay-briiztorm-btn-border-1i94y, rgba(255, 255, 255, 0.2));
    background: var(--theme-components-overlays-briiztormoverlay-briiztorm-btn-background-yovd6, rgba(0, 0, 0, 0.4));
    color: var(--palette-text-soft);
    font-size: 14px;
    cursor: pointer;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.briiztorm-btn:hover {
    background: var(--theme-components-overlays-briiztormoverlay-briiztorm-btn-hover-background-1trbk, rgba(0, 100, 120, 0.5));
    border-color: var(--theme-components-overlays-briiztormoverlay-briiztorm-title-text-shadow-19dnh, rgba(0, 200, 200, 0.5));
    color: var(--palette-white);
}

.briiztorm-btn.close:hover {
    background: var(--theme-components-overlays-briiztormoverlay-briiztorm-btn-close-hover-background-1fshh, rgba(150, 30, 30, 0.6));
    border-color: var(--theme-components-overlays-briiztormoverlay-briiztorm-btn-close-hover-border-color-1lj9y, rgba(255, 100, 100, 0.5));
    color: var(--palette-danger);
}

/* Content Container */

.briiztorm-content {
    flex: 1;
    position: relative;
    overflow: hidden;
}

/* The iframe/webview */

.briiztorm-frame {
    width: 100%;
    height: 100%;
    border: none;
    filter: blur(0px) hue-rotate(0deg);
    transition: filter 0.4s ease-out;
}

/* State: Opening - start blurred, clear up */

.briiztorm-overlay.opening .briiztorm-frame {
    filter: blur(20px) hue-rotate(10deg);
    animation: wake-up 0.4s ease-out forwards;
}

@keyframes wake-up {
    from {
        filter: blur(20px) hue-rotate(10deg);
    }

    to {
        filter: blur(0px) hue-rotate(0deg);
    }
}

/* State: Sleeping - blur + animated hue drift */

.briiztorm-overlay.sleeping .briiztorm-frame {
    filter: blur(30px) saturate(1.2);
    animation: hue-drift 3s ease-in-out infinite;
}

@keyframes hue-drift {
    0% {
        filter: blur(30px) hue-rotate(0deg) saturate(1.2);
    }

    50% {
        filter: blur(30px) hue-rotate(45deg) saturate(1.4);
    }

    100% {
        filter: blur(30px) hue-rotate(0deg) saturate(1.2);
    }
}

/* State: Closing - blur out */

.briiztorm-overlay.closing .briiztorm-frame {
    filter: blur(30px) hue-rotate(20deg);
    transition: filter 0.3s ease-out;
}

/* Sleep Indicator Overlay */

.briiztorm-overlay.sleeping::after {
    content: '💤';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 48px;
    opacity: 0.6;
    animation: sleep-bounce 2s ease-in-out infinite;
    pointer-events: none;
}

@keyframes sleep-bounce {

    0%,
    100% {
        transform: translate(-50%, -50%) scale(1);
        opacity: 0.4;
    }

    50% {
        transform: translate(-50%, -60%) scale(1.1);
        opacity: 0.7;
    }
}

