/* ===== Canvases Popover ===== */

.canvases-popover {
    position: absolute;
    top: calc(100% + 12px);
    right: 0;
    width: 360px;
    z-index: 28;
    background: var(--ui-header-bg);
    border: 1px solid var(--chat-input-border-color);
    border-radius: 10px;
    box-shadow: 0 12px 40px rgba(0, 0, 0, 0.6), 0 0 24px rgba(0, 200, 220, 0.15);
    backdrop-filter: blur(14px) saturate(140%);
    -webkit-backdrop-filter: blur(14px) saturate(140%);
    color: #cfefff;
    display: flex;
    flex-direction: column;
    overflow: visible;
    corner-shape: var(--ui-corner-shape);
    z-index: 28;
    font-family: SF Pro, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* The compact header scrolls its launcher row. Rendering this surface at the
   document layer keeps it anchored to Canvases without clipping it to that
   horizontal scrollport. */

.canvases-popover--portaled {
    width: min(360px, calc(100vw - 16px));
    z-index: 60;
}

.canvases-popover--portaled.canvases-popover--vertical {
    max-height: min(70vh, 640px);
}

.control-bar-dock--vertical .canvases-popover {
    top: 50%;
    right: auto;
    left: calc(100% + 18px);
    max-height: min(70vh, 640px);
    transform: translateY(-50%);
}

.control-bar-dock--vertical .canvases-popover-tail {
    top: 50%;
    right: auto;
    left: -7px;
    transform: translateY(-50%) rotate(45deg);
}

.canvases-popover--vertical .canvases-popover-tail {
    top: 50%;
    right: auto;
    left: -7px;
    transform: translateY(-50%) rotate(45deg);
}

.canvases-popover.is-creating .canvases-popover-header,
.canvases-popover.is-creating .canvases-popover-body,
.canvases-popover.is-creating .canvases-popover-plus {
    display: none;
}

/* Tail pointer */

.canvases-popover-tail {
    position: absolute;
    top: -7px;
    right: 26px;
    width: 12px;
    height: 12px;
    background: var(--chat-input-border-color);
    border-left: 1px solid rgba(0, 200, 220, 0.45);
    border-top: 1px solid rgba(0, 200, 220, 0.45);
    transform: rotate(45deg);
    backdrop-filter: blur(14px) saturate(140%);
}

.canvases-popover-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 10px 14px;
    border-bottom: 1px solid rgba(0, 200, 220, 0.2);
    flex-shrink: 0;
}

.canvases-popover-title {
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #00ffff;
    text-shadow: 0 0 6px rgba(0, 255, 255, 0.4);
}

.canvases-popover-close {
    background: transparent;
    border: 1px solid rgba(0, 200, 220, 0.3);
    color: #cfefff;
    width: 22px;
    height: 22px;
    border-radius: 4px;
    cursor: pointer;
    font-size: 12px;
    line-height: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.canvases-popover-close:hover {
    background: rgba(0, 200, 220, 0.2);
    border-color: rgba(0, 255, 255, 0.6);
}

.canvases-popover-body {
    flex: 1;
    min-height: 120px;
    overflow: visible;
    padding: 10px 10px 52px 10px;
    position: relative;
}

.canvases-popover-loading {
    text-align: center;
    padding: 40px 0;
    color: rgba(207, 239, 255, 0.55);
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.canvases-popover-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

/* Empty state */

.canvases-popover-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
    padding: 40px 20px;
    min-height: 180px;
}

.canvases-empty-plus {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    border: 1px solid rgba(0, 255, 255, 0.6);
    background: rgba(0, 150, 180, 0.3);
    color: #00ffff;
    font-size: 28px;
    cursor: pointer;
    box-shadow: 0 0 20px rgba(0, 255, 255, 0.25);
    transition: all 0.2s ease;
}

.canvases-empty-plus:hover {
    transform: scale(1.05);
    background: rgba(0, 200, 220, 0.4);
    box-shadow: 0 0 30px rgba(0, 255, 255, 0.45);
}

.canvases-empty-label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.8px;
    color: rgba(207, 239, 255, 0.65);
}

/* Floating "+" in the bottom-right of the popover */

.canvases-popover-plus {
    position: absolute;
    bottom: 12px;
    right: 12px;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    border: 1px solid rgba(0, 255, 255, 0.55);
    background: rgba(0, 150, 180, 0.55);
    color: #eafcff;
    font-size: 20px;
    line-height: 1;
    cursor: pointer;
    box-shadow: 0 4px 16px rgba(0, 255, 255, 0.25);
    transition: all 0.2s ease;
    z-index: 2;
}

.canvases-popover-plus:hover {
    transform: translateY(-2px);
    background: rgba(0, 200, 220, 0.65);
    box-shadow: 0 6px 20px rgba(0, 255, 255, 0.4);
}

/* ===== Canvas Card ===== */

.canvas-card {
    position: relative;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 10px;
    background: rgba(0, 40, 50, 0.45);
    border: 1px solid rgba(0, 200, 220, 0.25);
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.canvas-card:hover {
    background: rgba(0, 80, 100, 0.55);
    border-color: rgba(0, 255, 255, 0.55);
    transform: translateX(2px);
}

/* When the ... menu is open, crown this card the stacking-context king
   so its absolutely-positioned menu draws above sibling cards and their
   hover zones don't steal pointer events from menu items. */

.canvas-card.menu-open {
    z-index: 6;
}

.canvas-card-icon {
    width: 28px;
    height: 28px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #6cf;
    font-size: 18px;
}

.canvas-card-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.canvas-card-title {
    font-size: 12px;
    font-weight: 500;
    color: #eafcff;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.canvas-card-rename {
    font-size: 12px;
    background: rgba(0, 0, 0, 0.4);
    border: 1px solid rgba(0, 255, 255, 0.55);
    color: #eafcff;
    padding: 2px 4px;
    border-radius: 3px;
    outline: none;
    width: 100%;
}

.canvas-card-meta {
    display: flex;
    align-items: center;
    gap: 6px;
}

.canvas-badge {
    font-size: 9px;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    padding: 1px 6px;
    border-radius: 8px;
    font-weight: 600;
    border: 1px solid transparent;
}

.canvas-badge-float {
    background: rgba(0, 160, 200, 0.3);
    color: #8ff;
    border-color: rgba(0, 200, 220, 0.5);
}

.canvas-badge-tile {
    background: rgba(80, 180, 80, 0.25);
    color: #afe;
    border-color: rgba(120, 220, 120, 0.5);
}

.canvas-badge-hybrid {
    background: rgba(200, 120, 255, 0.22);
    color: #fbf;
    border-color: rgba(200, 150, 255, 0.5);
}

.canvas-badge-widget {
    background: rgba(255, 180, 80, 0.2);
    color: #fda;
    border-color: rgba(255, 180, 80, 0.45);
}

.canvas-badge-webplus {
    background: rgba(255, 255, 255, 0.08);
    color: #f7fbff;
    border-color: rgba(255, 255, 255, 0.18);
}

.canvas-card-when {
    font-size: 9px;
    color: rgba(207, 239, 255, 0.45);
}

.canvas-card-more {
    background: transparent;
    border: none;
    color: rgba(207, 239, 255, 0.6);
    cursor: pointer;
    font-size: 16px;
    padding: 2px 6px;
    border-radius: 4px;
}

.canvas-card-more:hover {
    background: rgba(0, 200, 220, 0.2);
    color: #0ff;
}

/* Context menu */

.canvas-card-menu {
    position: absolute;
    right: 4px;
    top: calc(100% + 4px);
    min-width: 140px;
    background: rgba(4, 16, 24, 0.96);
    border: 1px solid rgba(0, 200, 220, 0.5);
    border-radius: 6px;
    padding: 4px;
    z-index: 6;
    display: flex;
    flex-direction: column;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.6);
}

.canvas-card-menu button {
    background: transparent;
    border: none;
    color: #cfefff;
    text-align: left;
    padding: 5px 8px;
    font-size: 11px;
    cursor: pointer;
    border-radius: 4px;
}

.canvas-card-menu button:hover {
    background: rgba(0, 200, 220, 0.2);
    color: #0ff;
}

.canvas-card-menu button.is-active {
    background: rgba(0, 200, 220, 0.25);
    color: #0ff;
}

.canvas-card-menu-section {
    margin: 2px 0;
    padding: 4px 4px 2px 4px;
    border-top: 1px solid rgba(0, 200, 220, 0.15);
    border-bottom: 1px solid rgba(0, 200, 220, 0.15);
}

.canvas-card-menu-label {
    font-size: 9px;
    text-transform: uppercase;
    color: rgba(207, 239, 255, 0.45);
    padding: 2px 8px;
    letter-spacing: 0.6px;
}

.canvas-card-menu-danger {
    color: #ff9da0 !important;
}

.canvas-card-menu-danger:hover {
    background: rgba(255, 80, 80, 0.2) !important;
    color: #ffb9bc !important;
}

/* New canvas flow overlay */

.canvases-popover-overlay {
    position: static;
    background: rgba(0, 8, 14, 0.85);
    backdrop-filter: blur(6px);
    z-index: 10;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
}

/* ===== START OF ControlBar.css ===== */

.control-bar-dock {
    display: flex;
    justify-content: center;
    top: 0;
    z-index: 27;
    min-height: 100%;
    align-items: flex-end;
    padding: 0;
    overflow: visible;
    margin-top: -10px;
}

/* Desktop keeps one continuous visual strip. At compact widths this becomes
   the scrollable application region while the Ctrl Bar launcher stays beside
   Settings. */

.control-bar-dock__scroll {
    display: contents;
}

.control-bar-rail {
    display: flex;
    align-items: center;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    min-width: 0;
    padding-left: 10px;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
}

.control-bar-rail::-webkit-scrollbar {
    display: none;
}

.cb-canvases-wrap {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: visible;
}

.control-bar-dock>.cb-toggle,
.control-bar-dock>.cb-canvases-wrap,
.control-bar-dock__scroll>.cb-toggle,
.control-bar-dock__scroll>.cb-canvases-wrap {
    order: var(--cb-dock-order, 0);
}

/* A removed launcher stays mounted so the editor can pin it again, but it
   must not occupy the header dock. This wins over each child’s flex layout. */

.control-bar-dock>[hidden],
.control-bar-dock__scroll>[hidden] {
    display: none !important;
}

.cb-tab-shape {
    display: none;
}

.cb-toggle {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    min-width: 42px;
    padding: 0;
    background: transparent;
    border: none;
    border-radius: 20px;
    cursor: pointer;
    color: inherit;
    transition: transform 0.28s ease, filter 0.3s ease, opacity 0.3s ease;
}

.cb-toggle::before {
    content: '';
    position: absolute;
    inset: -8px -10px -12px;
    border-radius: 18px;
    background: transparent;
    border: none;
    opacity: 0;
    transition: opacity 0.3s ease, background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease;
}

.cb-toggle::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -9px;
    width: 44px;
    height: 3px;
    border-radius: 999px;
    background: linear-gradient(90deg, rgba(255, 255, 255, 0), var(--palette-accent-primary, white), rgba(255, 255, 255, 0));
    opacity: 0;
    transform: translateX(-50%) scaleX(0.72);
    transition: all .2s ease;
    pointer-events: none;
}

.cb-toggle:hover::before {
    opacity: 0.55;
}

.cb-toggle:hover::after {
    opacity: 0;
}

.cb-toggle.active::before,
.cb-toggle:focus-visible::before {
    opacity: 1;
}

.cb-toggle.active::after,
.cb-toggle:focus-visible::after {
    opacity: 0.95;
    transform: translateX(-50%) scaleX(1);
}

.cb-icon {
    position: relative;
    z-index: 1;
    font-family: SF Pro, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
    font-size: 22px;
    line-height: 1;
    opacity: 0.75;
    filter: blur(0px) saturate(0.3);
    transition: opacity 0.3s ease, filter 0.3s ease, transform 0.3s ease, text-shadow 0.3s ease;
}

.cb-icon.cb-vector-icon {
    width: 23px;
    height: 23px;
}

.control-bar-dock:hover .cb-icon,
.control-bar-dock:focus-within .cb-icon {
    opacity: 0.82;
    filter: blur(0px) saturate(1);
}

.cb-toggle.active .cb-icon,
.cb-toggle:focus-visible .cb-icon,
.cb-toggle:hover .cb-icon {
    opacity: 1;
    filter: blur(0px) saturate(2);
}

/* Hover motion lives on the glyph alone; the button box (and the activity
   light anchored to it) never moves, so the row stays aligned. */

.cb-toggle:hover .cb-icon {
    transform: translateY(-2px);
}

.control-bar-dock.control-bar-dock--current:not(.control-bar-dock--vertical) .cb-toggle:active .cb-icon {
    transform: translateY(0) scale(0.94);
}

#notes-icon {
    color: var(--theme-components-controlbar-controlbar-notes-icon-color-qo8di, palegoldenrod);
    -webkit-text-stroke: 0.5px var(--theme-components-controlbar-controlbar-notes-icon-webkit-text-stroke-o0md2, black);
}

#organizer-icon {
    color: var(--theme-components-controlbar-controlbar-organizer-icon-color-26sfj, lime);
    -webkit-text-stroke: 0.5px var(--theme-components-controlbar-controlbar-organizer-icon-webkit-text-stroke-b5mm4, green);
}

#calendar-icon {
    color: var(--theme-components-controlbar-controlbar-calendar-icon-color-i0tgi, red);
    -webkit-text-stroke: 1px var(--theme-components-controlbar-controlbar-calendar-icon-webkit-text-stroke-1g777, rgb(255, 161, 102));
}

#media-icon {
    color: var(--theme-components-controlbar-controlbar-media-icon-color-j5w4n, #9fffe7);
    -webkit-text-stroke: 0.5px var(--theme-components-controlbar-controlbar-media-icon-webkit-text-stroke-8rq2p, rgba(7, 15, 26, 0.92));
}

#briiztorm-icon {
    color: var(--theme-components-controlbar-controlbar-briiztorm-icon-color-hav81, rgb(255, 53, 161));
    -webkit-text-stroke: 0.5px var(--theme-components-controlbar-controlbar-briiztorm-icon-webkit-text-stroke-9ja92, pink);
}

#canvases-icon {
    color: var(--theme-components-controlbar-controlbar-canvases-icon-color-bgkk1, cyan);
    -webkit-text-stroke: 0.5px var(--theme-components-controlbar-controlbar-canvases-icon-webkit-text-stroke-ujr2d, rgba(0, 255, 255, 0.45));
    font-family: SF Pro, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

#journal-icon {
    color: #e5a76a;
}

#forest-icon {
    color: #7ee7a1;
}

#notefalls-icon {
    color: #bda6ff;
}

#sources-icon {
    color: #74dcea;
}

#tasks-icon {
    color: #ffd36b;
}

.cb-label {
    position: relative;
    display: flex;
    z-index: 1;
    font-size: 9px;
    font-weight: 400;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--theme-components-controlbar-controlbar-cb-label-color-sqqmz, rgba(255, 255, 255, 0.8));
    opacity: 0;
    pointer-events: none;
    user-select: none;
    /* The label slot is always reserved so revealing it never resizes the
     button — icons stay on one line whether an app is active or not. */
    max-height: 14px;
    justify-content: center;
    width: 60px;
    text-align: center;
    transform: translateY(-6px);
    transition: opacity 0.25s ease, transform 0.25s ease;
}

#controlBar-icon {
    color: var(--palette-accent-primary);
    font-size: 25px;
}

/* Labels are hover/focus-only, matching the App Dock behavior; an active
   app announces itself with the base light, not a persistent caption. */

.cb-toggle:focus-visible .cb-label,
.cb-toggle:hover .cb-label {
    opacity: 1;
    transform: translateY(0);
}

.cb-toggle--control-bar::after {
    display: none;
}

.cb-toggle--control-bar.active #controlBar-icon {
    transform: none;
    filter: drop-shadow(0 0 2px gold);
}

/* Each dock view consumes the same semantic accent. The renderer changes;
   the identity and active state of every control stay consistent. */

.cb-toggle[data-dock-item="controlBar"] {
    --cb-accent: black;
    ;
}

.cb-toggle[data-dock-item="chat"] {
    --cb-accent: #16df69;
}

.cb-toggle[data-dock-item="briiztorm"] {
    --cb-accent: #f54ba3;
}

.cb-toggle[data-dock-item="organizer"] {
    --cb-accent: #2bff36;
}

.cb-toggle[data-dock-item="calendar"] {
    --cb-accent: #ff7149;
}

.cb-toggle[data-dock-item="media"] {
    --cb-accent: #43e8dd;
}

.cb-toggle[data-dock-item="notes"] {
    --cb-accent: #e7dc91;
}

.cb-toggle[data-dock-item="canvases"] {
    --cb-accent: #24d9e6;
}

.cb-toggle[data-dock-item="journal"] {
    --cb-accent: #e5a76a;
}

.cb-toggle[data-dock-item="forest"] {
    --cb-accent: #7ee7a1;
}

.cb-toggle[data-dock-item="notefalls"] {
    --cb-accent: #bda6ff;
}

.cb-toggle[data-dock-item="sources"] {
    --cb-accent: #74dcea;
}

.cb-toggle[data-dock-item="tasks"] {
    --cb-accent: #ffd36b;
}

/* Ambient vertical rail ------------------------------------------------- */

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical {
    flex-direction: column;
    justify-content: center;
    /* In a column the cross axis is horizontal: the base flex-end (which seats
     icons on the header base in horizontal mode) would pack the rail right. */
    align-items: center;
    gap: clamp(16px, 3vh, 34px);
    width: 100%;
    height: 100%;
    min-height: 0;
    padding: 10px 0;
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle {
    flex: 0 0 44px;
    width: 52px;
    min-width: 52px;
    height: 44px;
    min-height: 44px;
    gap: 0;
    transform: none;
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical:hover .cb-toggle,
.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical:focus-within .cb-toggle {
    transform: none;
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle:hover {
    transform: scale(1.08);
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle:active {
    transform: scale(0.94);
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle::before {
    inset: -4px;
    border-radius: 13px;
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle::after {
    top: 50%;
    right: -12px;
    bottom: auto;
    left: auto;
    width: 3px;
    height: 30px;
    background: linear-gradient(180deg, transparent, rgba(255, 255, 255, 0.72), transparent);
    transform: translateY(-50%) scaleY(0.72);
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle.active::after,
.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle:focus-visible::after {
    transform: translateY(-50%) scaleY(1);
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle.active .cb-icon,
.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle:focus-visible .cb-icon,
.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle:hover .cb-icon {
    transform: none;
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-label {
    display: none;
}

@media (max-height: 700px) {
    .control-bar-dock.control-bar-dock--current.control-bar-dock--vertical {
        gap: 10px;
        padding-block: 4px;
    }
}

/* Ambient gives Ctrl Bar the one visual exception: it is a compact launcher,
   not an app tab. Its glyph claims the normal icon + label footprint and never
   grows an underline or a second text line. */

.control-bar-dock.control-bar-dock--current .cb-toggle--control-bar {
    width: 50px;
    min-width: 50px;
    height: 48px;
    gap: 0;
}

.control-bar-dock.control-bar-dock--current .cb-toggle--control-bar .cb-label {
    display: none;
}

.control-bar-dock.control-bar-dock--current .cb-toggle--control-bar .cb-icon,
.control-bar-dock.control-bar-dock--current:hover .cb-toggle--control-bar .cb-icon,
.control-bar-dock.control-bar-dock--current:focus-within .cb-toggle--control-bar .cb-icon {
    font-size: 39px;
    opacity: 0.68;
    filter: blur(0) saturate(1.1);
    transform: none;
}

.control-bar-dock.control-bar-dock--current .cb-toggle--control-bar:hover .cb-icon,
.control-bar-dock.control-bar-dock--current .cb-toggle--control-bar.active .cb-icon,
.control-bar-dock.control-bar-dock--current .cb-toggle--control-bar:focus-visible .cb-icon {
    opacity: 1;
    filter: drop-shadow(0 0 4px color-mix(in oklab, goldenrod 62%, transparent));
    transform: none;
}

.control-bar-dock.control-bar-dock--current.control-bar-dock--vertical .cb-toggle--control-bar {
    flex-basis: 52px;
    width: 52px;
    height: 52px;
}

/* The activity light belongs to the header's base, not to the button unit:
   it glows on beneath a running app and stays put through hover motion. */

.control-bar-dock.control-bar-dock--current .cb-toggle::after {
    box-shadow: 0 0 9px 1px color-mix(in oklab, var(--palette-accent-primary, white) 40%, transparent);
}

.control-bar-dock.control-bar-dock--macos .cb-toggle {
    width: 42px;
    height: 42px;
    gap: 0px;
    padding: 0;
    border: 1px solid color-mix(in oklab, var(--cb-accent) 58%, rgba(255, 255, 255, 0.58));
    border-radius: 11px;
    color: var(--cb-accent);
    background: linear-gradient(160deg, rgba(255, 255, 255, 0.36), transparent 42%), linear-gradient(145deg, color-mix(in oklab, var(--cb-accent) 0%, #28384b), color-mix(in oklab, var(--cb-accent) 55%, #10151d));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.38), inset 0 -1px 0 rgba(0, 0, 0, 0.28), 0 3px 7px rgba(0, 0, 0, 0.26);
    transform: none;
    transform-origin: center top;
    transition: transform 220ms cubic-bezier(0.22, 1, 0.36, 1), filter 120ms ease-out;
}

.control-bar-dock.control-bar-dock--macos .cb-toggle::before {
    inset: -1px;
    display: block;
    border: 1px solid transparent;
    border-radius: inherit;
    background: transparent;
    box-shadow: none;
}

.control-bar-dock.control-bar-dock--macos .cb-toggle::after {
    left: 50%;
    bottom: -7px;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: rgba(242, 248, 252, 0.82);
    transform: translateX(-50%) scale(0.45);
    transition: opacity 120ms ease-out, transform 120ms ease-out;
}

.control-bar-dock.control-bar-dock--macos .cb-toggle.active::before,
.control-bar-dock.control-bar-dock--macos .cb-toggle:focus-visible::before {
    border-color: color-mix(in oklab, var(--cb-accent) 62%, white);
    box-shadow: inset 0 0 2px rgba(255, 255, 255, 1);
}

.control-bar-dock.control-bar-dock--macos .cb-toggle.active::after,
.control-bar-dock.control-bar-dock--macos .cb-toggle:focus-visible::after {
    opacity: 1;
    transform: translateX(-50%) scale(1);
}

.control-bar-dock.control-bar-dock--macos .cb-icon,
.control-bar-dock.control-bar-dock--macos:hover .cb-icon,
.control-bar-dock.control-bar-dock--macos:focus-within .cb-icon {
    font-size: 23px;
    color: rgba(247, 252, 255, 0.95);
    opacity: 1;
    filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.42));
    -webkit-text-stroke: 0;
    transform: none;
}

.control-bar-dock.control-bar-dock--macos #chatpanel-icon,
.control-bar-dock.control-bar-dock--macos #briiztorm-icon,
.control-bar-dock.control-bar-dock--macos #organizer-icon,
.control-bar-dock.control-bar-dock--macos #calendar-icon,
.control-bar-dock.control-bar-dock--macos #media-icon,
.control-bar-dock.control-bar-dock--macos #notes-icon,
.control-bar-dock.control-bar-dock--macos #canvases-icon,
.control-bar-dock.control-bar-dock--macos #journal-icon,
.control-bar-dock.control-bar-dock--macos #forest-icon,
.control-bar-dock.control-bar-dock--macos #notefalls-icon,
.control-bar-dock.control-bar-dock--macos #sources-icon,
.control-bar-dock.control-bar-dock--macos #tasks-icon {
    color: rgba(247, 252, 255, 0.95);
    -webkit-text-stroke: 0;
}

.control-bar-dock.control-bar-dock--macos .cb-label {
    position: absolute;
    bottom: calc(50% -5px);
    left: 50%;
    width: max-content;
    max-height: none;
    padding: 4px 7px;
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 5px;
    background: var(--layout-bg-panel, rgba(0, 0, 0));
    color: rgba(246, 250, 252, 0.94);
    font-size: 9px;
    letter-spacing: 0.03em;
    text-transform: none;
    white-space: nowrap;
    opacity: 0;
    filter: brightness(50);
    pointer-events: none;
    transform: translateY(-100%)translateX(-50%)scale(.1);
    transition: all .3s ease, transform 540ms cubic-bezier(0.22, 1, 0.36, 1);
}

.control-bar-dock.control-bar-dock--macos .cb-toggle:hover {
    z-index: 4;
    filter: saturate(1.15) brightness(1.04);
    transform: translateY(-3px) scale(1.18);
}

.control-bar-dock.control-bar-dock--macos .cb-toggle:hover .cb-label,
.control-bar-dock.control-bar-dock--macos .cb-toggle:focus-visible .cb-label {
    opacity: 1;
    filter: brightness(1);
    transform: translateY(-90%)translateX(-50%)scale(1.1);
}

.control-bar-dock.control-bar-dock--macos .cb-toggle:active {
    transform: translateY(-5px) scale(1.16);
}

.control-bar-dock.control-bar-dock--macos .cb-toggle:focus-visible {
    border: 2px solid var(--cb-accent);
    outline: none;
}

/* Keeper-inspired folder tabs ------------------------------------------ */

.control-bar-dock.control-bar-dock--tabs {
    --cb-tab-width: 68px;
    --cb-tab-active-width: 114.4px;
    box-sizing: border-box;
    align-items: flex-end;
    justify-content: center;
    height: 100%;
    min-height: 0;
    width: 100%;
    /* Tabs sit on the header's bottom edge; their feet rest on the shelf line. */
    margin: 0;
    padding-bottom: 3px;
}

/* The shelf line passes in front of resting tabs and behind raised ones,
   so only active tabs read as pulled through to the page below. */

.control-bar-dock.control-bar-dock--tabs::after {
    content: '';
    position: absolute;
    z-index: 10;
    right: 0;
    bottom: 2px;
    left: 0;
    height: 1px;
    background: color-mix(in oklab, var(--palette-accent-cyan, #22dce8) 70%, transparent);
    box-shadow: 0 -1px 8px color-mix(in oklab, var(--palette-accent-cyan, #22dce8) 34%, transparent);
}

/* Stacking follows click recency (--cb-tab-recency, set inline by the dock):
   a tab's tails may only rest on tabs raised longer ago. */

.control-bar-dock.control-bar-dock--tabs .cb-toggle {
    z-index: calc(2 + var(--cb-tab-recency, 0));
    width: var(--cb-tab-width);
    min-width: var(--cb-tab-width);
    height: 40px;
    margin: 0 -8px;
    flex-direction: row;
    gap: 5px;
    border-radius: 0;
    color: var(--cb-accent);
    opacity: .5;
    transform: none;
    transition: all 180ms cubic-bezier(0.22, 1, 0.36, 1);
}

.control-bar-dock.control-bar-dock--tabs .cb-toggle::before,
.control-bar-dock.control-bar-dock--tabs .cb-toggle::after {
    display: none;
}

.control-bar-dock.control-bar-dock--tabs .cb-tab-shape {
    position: absolute;
    inset: 0;
    display: block;
    width: 100%;
    height: 100%;
    overflow: visible;
    pointer-events: none;
}

.control-bar-dock.control-bar-dock--tabs .cb-tab-occluder {
    fill: oklch(10% 0.015 275);
    stroke: none;
}

.control-bar-dock.control-bar-dock--tabs .cb-tab-face {
    fill: color-mix(in oklab, var(--ui-header-bg, #071015) 72%, #8a9297);
    stroke: rgba(208, 217, 221, 0.2);
    stroke-width: 1;
    vector-effect: non-scaling-stroke;
    transition: all 180ms ease;
}

.control-bar-dock.control-bar-dock--tabs .cb-icon,
.control-bar-dock.control-bar-dock--tabs:hover .cb-icon,
.control-bar-dock.control-bar-dock--tabs:focus-within .cb-icon {
    font-size: 21px;
    color: color-mix(in oklab, var(--cb-accent) 68%, #596064);
    opacity: 0.76;
    filter: saturate(0.7);
    -webkit-text-stroke: 0.35px rgba(4, 8, 10, 0.72);
    transform: none;
    transition: all 180ms ease;
}

.control-bar-dock.control-bar-dock--tabs .cb-label {
    display: none;
}

/* Hover brightens but never restacks — tails only move forward on click. */

.control-bar-dock.control-bar-dock--tabs .cb-toggle:hover {
    opacity: .7;
}

.control-bar-dock.control-bar-dock--tabs .cb-toggle:hover .cb-tab-face {
    fill: color-mix(in oklab, var(--ui-header-bg, #071015) 62%, #b2bbc0);
    stroke: rgba(244, 248, 249, 0.84);
}

.control-bar-dock.control-bar-dock--tabs .cb-toggle:focus-visible {
    z-index: 40;
}

.control-bar-dock.control-bar-dock--tabs .cb-toggle.active {
    z-index: calc(20 + var(--cb-tab-recency, 0));
    width: var(--cb-tab-active-width);
    min-width: var(--cb-tab-active-width);
    height: 48px;
    margin-left: -10px;
    margin-right: -10px;
    opacity: 1;
}

.control-bar-dock.control-bar-dock--tabs .cb-toggle.active .cb-tab-face,
.control-bar-dock.control-bar-dock--tabs .cb-toggle:focus-visible .cb-tab-face {
    fill: color-mix(in oklab, var(--ui-header-bg, #071015) 92%, #020404);
    stroke: color-mix(in oklab, var(--palette-accent-cyan, #22dce8) 98%, white);
    stroke-width: 1.2;
}

.control-bar-dock.control-bar-dock--tabs .cb-toggle.active .cb-icon,
.control-bar-dock.control-bar-dock--tabs .cb-toggle:focus-visible .cb-icon,
.control-bar-dock.control-bar-dock--tabs .cb-toggle:hover .cb-icon {
    color: var(--cb-accent);
    opacity: 1;
    filter: saturate(1.35) drop-shadow(0 0 4px color-mix(in oklab, var(--cb-accent) 46%, transparent));
    transform: none;
}

.control-bar-dock.control-bar-dock--tabs .cb-toggle:focus-visible {
    outline: 2px solid color-mix(in oklab, var(--palette-accent-cyan, #22dce8) 72%, white);
    outline-offset: -5px;
}

/* Expanded Ctrl Bar ------------------------------------------------------
   It echoes the icon language of the reference strip: briizy has the fixed
   far-left control, then the editable header-dock icons appear as tall, quiet
   glyphs. A chevron says an icon is in the header dock; Option-hover changes
   that marker to the red remove control. Icons outside the header dock stay in
   the same strip with their own + pin affordance. */

.control-bar-rail {
    justify-content: flex-start;
}

.cb-briizy-presence {
    display: flex;
    flex-direction: column;
    align-content: center;
    justify-items: center;
    gap: 2px;
    min-width: 0;
    padding: 8px 4px;
    color: rgba(247, 249, 244, 0.94);
}

.cb-briizy-vis-toggles {
    padding-right: 16px;
}

.cb-observation-toggle {
    appearance: none;
    display: grid;
    place-items: center;
    width: 100%;
    ;
    height: 68px;
    padding: 0;
    border: 0;
    background: transparent;
    cursor: pointer;
    transition: filter 160ms ease, transform 160ms ease-out;
}

.cb-observation-toggle:hover:not(:disabled),
.cb-observation-toggle:focus-visible {
    filter: brightness(1.08) drop-shadow(0 0 12px rgba(126, 227, 181, 0.32));
    outline: none;
}

.cb-observation-toggle:active:not(:disabled) {
    transform: scale(0.94);
}

.cb-observation-toggle:disabled {
    cursor: not-allowed;
    opacity: 0.42;
}

.cb-briizy-avatar {
    display: block;
    width: 80px;
    height: 68px;
    object-fit: contain;
    filter: drop-shadow(0 5px 7px rgba(0, 0, 0, 0.36));
    transition: filter 160ms ease-out, opacity 160ms ease-out;
}

.cb-observation-toggle.is-active .cb-briizy-avatar {
    filter: brightness(1.08) drop-shadow(0 5px 7px rgba(0, 0, 0, 0.42)) drop-shadow(0 0 8px rgba(93, 236, 147, 0.68));
}

.cb-briizy-presence.is-invisible .cb-briizy-avatar {
    opacity: 0.48;
    filter: grayscale(0.72) brightness(0.9) drop-shadow(0 5px 7px rgba(0, 0, 0, 0.3));
}

.cb-briizy-size {
    display: flex;
    flex-direction: column;
    gap: 5px;
    margin-top: -14px;
}

.cb-briizy-size__label,
.cb-sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.cb-briizy-size__value {
    align-self: center;
    justify-self: center;
    color: rgba(244, 242, 232, 0.86);
    font-family: var(--ui-font);
    font-size: 12px;
    font-weight: 600;
    line-height: 1;
    text-shadow: 0 1px 4px rgba(0, 0, 0, 0.42);
}

.cb-briizy-size__range {
    -webkit-appearance: none;
    appearance: none;
    width: 90%;
    height: 16px;
    margin: 0;
    padding: 0;
    padding-left: 10%;
    background: transparent;
    cursor: pointer;
}

.cb-briizy-size__range::-webkit-slider-runnable-track {
    height: 5px;
    border-radius: 999px;
    background: linear-gradient(to bottom, var(--palette-accent-primary), black);
    box-shadow: inset 0 1px 2px rgba(32, 19, 18, 0.52), 0 1px rgba(255, 255, 255, 0.18);
}

.cb-briizy-size__range::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 20px;
    margin-top: -8px;
    border: 2px solid rgba(245, 171, 149, 0.9);
    border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, rgba(82, 80, 82, 0.95), rgba(17, 18, 21, 0.98) 68%);
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.52), inset 0 1px rgba(255, 255, 255, 0.36);
}

.cb-briizy-size__range::-moz-range-track {
    height: 5px;
    border-radius: 999px;
    background: rgba(245, 171, 149, 0.34);
    box-shadow: inset 0 1px 2px rgba(32, 19, 18, 0.52), 0 1px rgba(255, 255, 255, 0.18);
}

.cb-briizy-size__range::-moz-range-progress {
    height: 5px;
    border-radius: 999px;
    background: rgba(245, 171, 149, 0.98);
}

.cb-briizy-size__range::-moz-range-thumb {
    width: 16px;
    height: 16px;
    border: 2px solid rgba(245, 171, 149, 0.9);
    border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, rgba(82, 80, 82, 0.95), rgba(17, 18, 21, 0.98) 68%);
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.52), inset 0 1px rgba(255, 255, 255, 0.36);
}

.cb-briizy-size__range:focus-visible {
    outline: 2px solid rgba(246, 251, 248, 0.94);
    outline-offset: 4px;
    border-radius: 999px;
}

.cb-briizy-size__range:disabled {
    cursor: not-allowed;
    opacity: 0.42;
}

.cb-briizy-visibility {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 7px;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
}

.cb-briizy-visibility__option {
    position: relative;
    display: block;
    cursor: pointer;
}

.cb-briizy-visibility__option input {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    opacity: 0;
}

.cb-briizy-visibility__option span {
    display: grid;
    place-items: center;
    min-width: 72px;
    min-height: 26px;
    padding: 0 8px;
    border: 1px solid transparent;
    color: rgba(245, 246, 239, 0.68);
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 9px;
    font-weight: 600;
    letter-spacing: 0.025em;
    line-height: 1;
    text-transform: uppercase;
    transition: color 140ms ease-out, border-color 140ms ease-out, background 140ms ease-out, box-shadow 140ms ease-out;
}

.cb-briizy-visibility__option:hover span {
    color: rgba(255, 255, 250, 0.98);
}

.cb-briizy-visibility__option input:checked+span {
    border-color: rgba(247, 250, 244, 0.9);
    background: rgba(229, 248, 237, 0.08);
    color: rgba(255, 255, 250, 0.98);
    border-radius: var(--ui-border-radius);
    box-shadow: inset 0 0 0 1px rgba(172, 242, 210, 0.16), 0 2px 8px rgba(0, 0, 0, 0.2);
}

.cb-briizy-visibility__option input:focus-visible+span {
    outline: 2px solid rgba(246, 251, 248, 0.94);
    outline-offset: 2px;
}

.cb-briizy-visibility:disabled {
    opacity: 0.42;
}

.cb-briizy-visibility:disabled .cb-briizy-visibility__option {
    cursor: not-allowed;
}

.cb-editor__label,
.cb-editor__item-label {
    display: none;
}

.cb-editor__rule {
    width: 1px;
    height: 98px;
    flex: 0 0 auto;
    background: linear-gradient(transparent, rgba(255, 255, 255, 0.25), transparent);
}

.cb-editor__dock {
    display: flex;
    align-items: center;
    min-width: 0;
}

.cb-editor__dock {
    flex: 1 1 auto;
}

.cb-editor__items {
    display: flex;
    align-items: center;
    gap: 3px;
    min-width: 0;
}

.cb-editor__items {
    flex: 1 1 auto;
    overflow-x: auto;
    overflow-y: hidden;
    padding: 4px 2px;
    padding-left: 6px;
    scrollbar-width: none;
}

.cb-editor__items::-webkit-scrollbar {
    display: none;
}

.cb-editor__item {
    position: relative;
    flex: 0 0 60px;
    width: 60px;
    height: 70px;
    box-sizing: border-box;
    color: rgba(247, 247, 246, 0.72);
    padding-top: 10px;
}

.cb-editor__item {
    display: flex;
    border: 1px solid transparent;
    border-radius: 30px 30px 17px 17px;
    background: transparent;
    user-select: none;
    transition: background 150ms ease, border-color 150ms ease, box-shadow 150ms ease;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    justify-self: center;
    padding: 0;
}

.cb-editor__item.is-pinned {
    cursor: grab;
}

.cb-editor__item.is-unpinned {}

.cb-editor__item.is-remove-mode {
    border-color: rgba(255, 195, 195, 0.94);
    background: linear-gradient(180deg, rgba(112, 30, 28, 0.8), rgba(189, 45, 42, 0.9));
}

.cb-editor__item.is-pinned:active {
    cursor: grabbing;
}

.cb-editor__marker {
    grid-row: 1;
    z-index: 2;
    display: flex !important;
    place-items: center;
    width: 22px;
    height: 22px;
    padding: 0;
    border: 0;
    background: transparent;
    color: rgba(252, 252, 250, 0.94);
    font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', sans-serif;
    text-align: center;
    justify-content: center;
    align-items: center;
    padding-bottom: 3px;
}

.cb-editor__marker--pinned {
    pointer-events: none;
    font-size: 15px;
    font-weight: 200;
    transform: translateY(5px);
}

.cb-editor__marker--add {
    opacity: 0;
    border-radius: 50px;
    color: rgba(246, 250, 251, 0.82);
    cursor: pointer;
    font-size: 15px;
    font-weight: 300;
    transition: all 150ms ease;
}

.cb-editor__item:hover>.cb-editor__marker--add {
    opacity: 1;
}

.cb-editor__marker--add:hover,
.cb-editor__marker--add:focus-visible {
    border-color: rgba(153, 224, 247, 0.96);
    background: rgba(109, 193, 227, 0.18);
    color: #fff;
    outline: none;
    transform: scale(1.08);
}

.cb-editor__marker--remove {
    border-radius: 50%;
    background: rgba(235, 0, 0, 0.96);
    color: #fff;
    cursor: pointer;
    font-size: 34px;
    font-weight: 600;
    line-height: 24px;
    text-shadow: 0 1px 1px rgba(0, 0, 0, 0.72);
    transition: background 150ms ease, transform 150ms ease;
}

.cb-editor__marker--remove:hover,
.cb-editor__marker--remove:focus-visible {
    background: #ff2727;
    outline: none;
    transform: scale(1.08);
}

.cb-editor__launch {
    appearance: none;
    grid-row: 2;
    display: grid;
    place-items: center;
    width: 100%;
    height: 100%;
    min-height: 0;
    padding: 0;
    border: 0;
    border-radius: 0 0 16px 16px;
    background: transparent;
    cursor: pointer;
}

.cb-editor__launch:focus-visible {
    outline: 2px solid rgba(184, 236, 251, 0.96);
    outline-offset: -6px;
}

.cb-editor__glyph {
    display: inline-grid;
    place-items: center;
    width: 35px;
    height: 40px;
    font-family: SF Pro, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    font-size: 22px;
    line-height: 1;
    filter: grayscale(0.55) brightness(1.3) drop-shadow(0 2px 1px rgba(0, 0, 0, 0.46));
    transition: filter 150ms ease, transform 150ms ease;
}

.cb-vector-icon {
    fill: none;
    stroke: currentColor;
}

.cb-editor__glyph.cb-vector-icon {
    display: block;
    width: 49px;
    height: 49px;
}

.cb-editor__item:hover .cb-editor__glyph,
.cb-editor__item:focus-within .cb-editor__glyph {
    filter: saturate(1.28) brightness(1.12) drop-shadow(0 2px 2px rgba(0, 0, 0, 0.48));
    transform: translateY(-2px);
}

/* The icon can request briizy's existing first-run consent flow. Keeping that
   consent above the workspace lets this shortcut remain a true on/off control
   without silently enabling screen observation on a new install. */

.cb-onboarding-backdrop {
    position: fixed;
    z-index: 2401;
    inset: 0;
    display: grid;
    place-items: center;
    padding: 28px;
    background: rgba(2, 7, 10, 0.66);
    backdrop-filter: blur(10px);
}

.cb-onboarding-dialog {
    width: min(640px, 100%);
    max-height: min(760px, calc(100vh - 56px));
    overflow-y: auto;
    box-sizing: border-box;
    padding: 24px 26px;
    border: 1px solid rgba(153, 224, 247, 0.34);
    border-radius: 18px;
    background: linear-gradient(165deg, rgba(13, 28, 34, 0.98), rgba(6, 10, 14, 0.98));
    box-shadow: 0 28px 90px rgba(0, 0, 0, 0.7), 0 0 32px rgba(109, 193, 227, 0.16);
}

@media (max-width: 680px) {
    .cb-briizy-presence {
        flex-basis: 236px;
    }

    .control-bar-dock.control-bar-dock--tabs {
        --cb-tab-width: 64px;
        --cb-tab-active-width: 83.2px;
    }

    .control-bar-dock.control-bar-dock--tabs .cb-toggle {
        margin-inline: -4px;
    }
}

@media (prefers-reduced-motion: reduce) {

    .control-bar-dock .cb-toggle,
    .control-bar-dock .cb-icon,
    .control-bar-dock .cb-label,
    .control-bar-dock .cb-tab-shape path,
    .cb-observation-toggle,
    .cb-briizy-avatar,
    .cb-briizy-visibility__option span {
        transition-duration: 0.01ms !important;
    }

    .control-bar-dock.control-bar-dock--macos .cb-toggle:hover,
    .control-bar-dock.control-bar-dock--tabs .cb-toggle:hover,
    .control-bar-dock.control-bar-dock--tabs .cb-toggle.active {
        transform: none;
    }
}

.control-bar-dock.control-bar-dock--current .cb-toggle--control-bar {
    margin-right: 20px;
}

.cb-toggle--control-bar.active #controlBar-icon {
    transform: rotate(180deg)scale(1.3);
}

@media (max-width: 980px) {
    .app:not(.app--vertical-header) .header-dock-slot>.control-bar-dock {
        width: 100%;
        min-width: 0;
        max-width: none;
        justify-content: flex-start;
        flex-wrap: nowrap;
        gap: 0;
        margin: 0;
        padding-inline: 0;
        overflow: visible;
    }

    .app:not(.app--vertical-header) .header-dock-slot>.control-bar-dock>.cb-toggle--control-bar {
        flex: 0 0 auto;
        margin: 0;
        z-index: 2;
    }

    .app:not(.app--vertical-header) .header-dock-slot .control-bar-dock__scroll {
        display: flex;
        flex: 1 1 auto;
        align-self: stretch;
        align-items: center;
        min-width: 0;
        min-height: 0;
        gap: 0;
        overflow-x: auto;
        overflow-y: hidden;
        overscroll-behavior-x: contain;
        scroll-padding-inline: 8px;
        scrollbar-width: thin;
        scrollbar-color: color-mix(in oklab, var(--palette-accent-primary, #22dce8) 62%, transparent) transparent;
    }

    .app:not(.app--vertical-header) .header-dock-slot .control-bar-dock__scroll::-webkit-scrollbar {
        height: 4px;
    }

    .app:not(.app--vertical-header) .header-dock-slot .control-bar-dock__scroll::-webkit-scrollbar-thumb {
        background: color-mix(in oklab, var(--palette-accent-primary, #22dce8) 62%, transparent);
        border-radius: 999px;
    }

    .app:not(.app--vertical-header) .header-dock-slot .control-bar-dock__scroll>.cb-toggle,
    .app:not(.app--vertical-header) .header-dock-slot .control-bar-dock__scroll>.cb-canvases-wrap {
        flex: 0 0 auto;
    }

    .app:not(.app--vertical-header) .header-dock-slot .control-bar-dock__scroll .cb-toggle {
        scroll-margin-inline: 8px;
    }

    .app:not(.app--vertical-header) .header-dock-slot .control-bar-dock--macos .control-bar-dock__scroll {
        gap: 16px;
    }

    .app:not(.app--vertical-header) .header-dock-slot .control-bar-dock--tabs .control-bar-dock__scroll {
        align-items: flex-end;
    }
}

/* ===== START OF DashboardOverlay.css ===== */

/* =====================
   DashboardOverlay
   Extends the existing modal-* / settings-* classes from App.css
   ===================== */

/* Dashboard occupies the overlay workspace edge to edge. */

.dashboard-modal-container {
    width: 100vw;
    max-width: 100vw;
    height: 100vh;
    max-height: 100vh;
}

.appearance-interface-block {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.appearance-visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.dock-style-options {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
    min-width: 0;
    padding: 0;
    margin: 2px 0 0;
    border: 0;
}

.dock-style-option {
    position: relative;
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 10px;
    padding: 10px;
    overflow: hidden;
    border: 1px solid var(--ui-settings-radio-border, rgba(99, 208, 214, 0.2));
    border-radius: 10px;
    background: var(--ui-settings-radio-bg, rgba(12, 30, 39, 0.72));
    cursor: pointer;
    transition: border-color 140ms ease-out, background 140ms ease-out, box-shadow 180ms ease-out, transform 140ms ease-out;
    corner-shape: var(--ui-corner-shape);
}

.dock-style-option:hover {
    border-color: var(--ui-settings-radio-border-hover, rgba(78, 225, 232, 0.5));
    background: var(--ui-settings-radio-bg-hover, rgba(16, 47, 58, 0.82));
    transform: translateY(-1px);
}

.dock-style-option:has(input:checked) {
    border-color: var(--ui-settings-radio-border-active, rgba(69, 232, 238, 0.8));
    background: var(--ui-settings-radio-bg-active, rgba(24, 77, 84, 0.72));
    box-shadow: var(--ui-settings-radio-shadow-active, 0 0 0 1px rgba(69, 232, 238, 0.22));
}

.dock-style-option:has(input:focus-visible) {
    outline: 2px solid var(--palette-accent-cyan, #33e4ea);
    outline-offset: 3px;
}

.dock-style-option input {
    position: absolute;
    width: 1px;
    height: 1px;
    opacity: 0;
    pointer-events: none;
}

.dock-style-option-check {
    position: absolute;
    top: 7px;
    right: 8px;
    display: grid;
    width: 18px;
    height: 18px;
    place-items: center;
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 50%;
    background: rgba(6, 13, 18, 0.72);
    color: rgba(238, 246, 247, 0.42);
    font-size: 10px;
    opacity: 0;
    transform: scale(0.7);
    transition: opacity 120ms ease-out, transform 180ms cubic-bezier(0.22, 1, 0.36, 1);
}

.dock-style-option:has(input:checked) .dock-style-option-check {
    color: var(--palette-accent-cyan, #33e4ea);
    opacity: 1;
    transform: scale(1);
}

.dock-style-preview {
    position: relative;
    display: grid;
    height: 76px;
    min-width: 0;
    place-items: center;
    overflow: hidden;
    border-radius: 7px;
    background: radial-gradient(circle at 50% 115%, rgba(25, 172, 181, 0.15), transparent 54%), linear-gradient(155deg, rgba(8, 16, 21, 0.94), rgba(3, 8, 11, 0.98));
    box-shadow: inset 0 0 0 1px rgba(185, 229, 232, 0.08);
}

.dock-style-preview::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(112deg, transparent 22%, rgba(255, 255, 255, 0.045) 50%, transparent 76%);
    pointer-events: none;
}

.dock-style-preview-track {
    position: relative;
    z-index: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.dock-style-preview-item {
    --dock-preview-accent: #33e4ea;
    position: relative;
    display: grid;
    place-items: center;
    color: var(--dock-preview-accent);
}

.dock-style-preview-glyph {
    position: relative;
    z-index: 2;
    font-family: 'SF Pro', -apple-system, BlinkMacSystemFont, sans-serif;
    line-height: 1;
}

.dock-style-preview--current .dock-style-preview-track {
    gap: clamp(12px, 1.8vw, 23px);
}

.dock-style-preview--current .dock-style-preview-item {
    width: 24px;
    height: 36px;
    opacity: 0.42;
    filter: blur(2px) saturate(0.75);
}

.dock-style-preview--current .dock-style-preview-item.is-active {
    opacity: 1;
    filter: none;
}

.dock-style-preview--current .dock-style-preview-item.is-active::after {
    content: '';
    position: absolute;
    right: -6px;
    bottom: 1px;
    left: -6px;
    height: 3px;
    border-radius: 999px;
    background: linear-gradient(90deg, transparent, rgba(244, 250, 250, 0.88), transparent);
    box-shadow: 0 0 6px var(--dock-preview-accent);
}

.dock-style-preview--current .dock-style-preview-glyph {
    font-size: 21px;
}

.dock-style-preview--macos .dock-style-preview-track {
    gap: 4px;
    padding: 5px 7px 6px;
    border: 1px solid rgba(233, 239, 244, 0.32);
    border-radius: 12px;
    background: linear-gradient(180deg, rgba(231, 238, 242, 0.38), rgba(92, 103, 111, 0.56));
    box-shadow: inset 0 1px rgba(255, 255, 255, 0.32), 0 7px 15px rgba(0, 0, 0, 0.3);
}

.dock-style-preview--macos .dock-style-preview-item {
    width: 31px;
    height: 31px;
    border: 1px solid color-mix(in oklab, var(--dock-preview-accent) 62%, white);
    border-radius: 8px;
    background: linear-gradient(155deg, rgba(255, 255, 255, 0.36), transparent 44%), color-mix(in oklab, var(--dock-preview-accent) 66%, #273341);
    box-shadow: inset 0 -1px rgba(0, 0, 0, 0.24), 0 2px 4px rgba(0, 0, 0, 0.3);
}

.dock-style-preview--macos .dock-style-preview-item.is-active {
    transform: translateY(-5px) scale(1.14);
}

.dock-style-preview--macos .dock-style-preview-item.is-active::after {
    content: '';
    position: absolute;
    bottom: -7px;
    left: 50%;
    width: 3px;
    height: 3px;
    border-radius: 50%;
    background: rgba(245, 249, 250, 0.88);
    transform: translateX(-50%);
}

.dock-style-preview--macos .dock-style-preview-glyph {
    color: rgba(248, 251, 252, 0.95);
    font-size: 17px;
    filter: drop-shadow(0 1px rgba(0, 0, 0, 0.4));
}

.dock-style-preview--tabs {
    align-items: end;
    padding-bottom: 12px;
}

.dock-style-preview--tabs::after {
    content: '';
    position: absolute;
    right: 10px;
    bottom: 12px;
    left: 10px;
    height: 1px;
    background: rgba(49, 222, 231, 0.68);
    box-shadow: 0 0 7px rgba(49, 222, 231, 0.38);
}

.dock-style-preview--tabs .dock-style-preview-item {
    z-index: 1;
    width: 50px;
    height: 32px;
    margin: 0 -3px;
    opacity: 0.62;
}

.dock-style-preview--tabs .dock-style-preview-item.is-active {
    z-index: 3;
    width: 65px;
    opacity: 1;
    transform: translateY(-2px);
}

.dock-style-preview-tab {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    overflow: visible;
}

.dock-style-preview-tab path {
    fill: rgba(123, 133, 138, 0.8);
    stroke: rgba(222, 229, 232, 0.64);
    stroke-width: 0.8;
    vector-effect: non-scaling-stroke;
}

.dock-style-preview--tabs .is-active .dock-style-preview-tab path {
    fill: rgba(4, 10, 13, 0.98);
    stroke: rgba(45, 226, 235, 0.92);
    stroke-width: 1.2;
}

.dock-style-preview--tabs .dock-style-preview-glyph {
    font-size: 18px;
    filter: saturate(0.72);
}

.dock-style-preview--tabs .is-active .dock-style-preview-glyph {
    filter: saturate(1.25) drop-shadow(0 0 3px var(--dock-preview-accent));
}

.dock-style-option-copy {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 3px;
}

.dock-style-option-label {
    color: var(--ui-settings-radio-label, rgba(232, 242, 244, 0.92));
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.02em;
}

.dock-style-option:has(input:checked) .dock-style-option-label {
    color: var(--ui-settings-radio-label-active, var(--palette-accent-cyan, #33e4ea));
}

.dock-style-option-description {
    color: var(--ui-settings-section-desc, rgba(185, 202, 205, 0.68));
    font-size: 10px;
    line-height: 1.4;
}

.dock-orientation-setting {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    gap: 3px;
    width: 32%;
    padding-top: 4px;
}

.dock-orientation-copy {
    display: flex;
    min-width: 0;
    flex-direction: column;
    gap: 3px;
}

.dock-orientation-label {
    color: var(--ui-settings-radio-label, rgba(232, 242, 244, 0.92));
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.dock-orientation-hint {
    color: var(--ui-settings-section-desc, rgba(185, 202, 205, 0.68));
    font-size: 10px;
}

.dock-orientation-options {
    display: grid;
    grid-template-columns: repeat(2, minmax(112px, 1fr));
    flex: 0 0 auto;
    gap: 3px;
    min-width: 0;
    margin: 0;
    border: 1px solid var(--ui-settings-radio-border, rgba(99, 208, 214, 0.2));
    border-radius: 9px;
    background: color-mix(in oklab, var(--ui-settings-radio-bg, rgba(12, 30, 39, 0.72)) 78%, transparent);
}

.dock-orientation-option {
    position: relative;
    display: flex;
    min-height: 38px;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 0 4px;
    border: 1px solid transparent;
    border-radius: 6px;
    color: var(--ui-settings-section-desc, rgba(185, 202, 205, 0.68));
    font-size: 10px;
    letter-spacing: 0.035em;
    cursor: pointer;
    transition: color 120ms ease-out, border-color 120ms ease-out, background 120ms ease-out;
}

.dock-orientation-option:hover {
    color: var(--ui-settings-radio-label, rgba(232, 242, 244, 0.92));
    background: var(--ui-settings-radio-bg-hover, rgba(16, 47, 58, 0.82));
}

.dock-orientation-option:has(input:checked) {
    border-color: var(--ui-settings-radio-border-active, rgba(69, 232, 238, 0.8));
    color: var(--ui-settings-radio-label-active, var(--palette-accent-cyan, #33e4ea));
    background: var(--ui-settings-radio-bg-active, rgba(24, 77, 84, 0.72));
    box-shadow: inset 0 0 0 1px color-mix(in oklab, currentColor 18%, transparent);
}

.dock-orientation-option:has(input:focus-visible) {
    outline: 2px solid var(--palette-accent-cyan, #33e4ea);
    outline-offset: 3px;
}

.dock-orientation-option.is-disabled {
    opacity: 0.34;
    cursor: not-allowed;
}

.dock-orientation-option input {
    position: absolute;
    width: 1px;
    height: 1px;
    opacity: 0;
    pointer-events: none;
}

.dock-orientation-mark {
    position: relative;
    width: 23px;
    height: 15px;
    flex: 0 0 auto;
    border: 1px solid currentColor;
    border-radius: 3px;
    opacity: 0.78;
}

.dock-orientation-mark::before {
    content: '';
    position: absolute;
    border-radius: 2px;
    background: currentColor;
    box-shadow: 0 0 5px color-mix(in oklab, currentColor 44%, transparent);
}

.dock-orientation-mark--horizontal::before {
    top: 2px;
    right: 2px;
    left: 2px;
    height: 3px;
}

.dock-orientation-mark--vertical::before {
    top: 2px;
    bottom: 2px;
    left: 2px;
    width: 3px;
}

.appearance-section-rule {
    height: 1px;
    margin: 2px 0;
    background: linear-gradient(90deg, transparent, var(--ui-settings-radio-border-hover, rgba(64, 213, 220, 0.34)), transparent);
}

.appearance-theme-studio-btn {
    width: 50%;
    background: none;
    corner-shape: var(--ui-corner-shape);
    border-radius: var(--ui-border-radius)
}

@media (max-width: 900px) {
    .dashboard-modal-container {
        max-width: 100vw;
    }

    .dashboard-modal-container .modal-tabs {
        width: 156px;
        flex-basis: 156px !important;
    }
}

@media (max-width: 620px) {
    .dock-style-option {
        display: flex;
    }

    .dock-orientation-setting {
        align-items: stretch;
        flex-direction: column;
    }

    .dock-orientation-options {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (prefers-reduced-motion: reduce) {

    .dock-style-option,
    .dock-style-option-check,
    .dock-orientation-option {
        transition-duration: 0.01ms !important;
    }

    .dock-style-option:hover,
    .dock-style-preview--macos .dock-style-preview-item.is-active,
    .dock-style-preview--tabs .dock-style-preview-item.is-active {
        transform: none;
    }
}

/* ── Memory Tab ── */

.dashboard-agent-context {
    min-height: 200px;
    resize: vertical;
    font-family: 'SF Mono', Monaco, 'Fira Code', monospace;
    font-size: 12px;
    line-height: 1.5;
    white-space: pre-wrap;
}

.dashboard-chunks-input {
    max-width: 100px;
    text-align: center;
    -moz-appearance: textfield;
}

.dashboard-chunks-input::-webkit-inner-spin-button,
.dashboard-chunks-input::-webkit-outer-spin-button {
    opacity: 1;
}

/* Chunk list */

.dashboard-chunk-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
    max-height: 200px;
    overflow-y: auto;
    border: 1px solid var(--theme-components-overlays-dashboardoverlay-dashboard-chunk-list-border-19ivk, rgba(0, 200, 200, 0.12));
    border-radius: 6px;
    background: var(--theme-components-overlays-dashboardoverlay-dashboard-chunk-list-background-1sfna, rgba(10, 20, 30, 0.5));
}

.dashboard-chunk-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 8px 12px;
    background: transparent;
    border: none;
    color: var(--palette-text-soft);
    font-size: 12px;
    font-family: 'SF Mono', Monaco, monospace;
    cursor: pointer;
    transition: background 0.15s ease;
    text-align: left;
    width: 100%;
}

.dashboard-chunk-item:hover {
    background: var(--theme-components-overlays-dashboardoverlay-dashboard-chunk-item-hover-background-1v3j3, rgba(0, 200, 200, 0.06));
}

.dashboard-chunk-item.active {
    background: var(--theme-components-overlays-dashboardoverlay-dashboard-chunk-list-border-19ivk, rgba(0, 200, 200, 0.12));
    color: var(--palette-accent-cyan);
}

.dashboard-chunk-name {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dashboard-chunk-size {
    flex-shrink: 0;
    color: var(--palette-text-muted);
    font-size: 10px;
    margin-left: 12px;
}

/* Chunk content preview */

.dashboard-chunk-preview {
    margin: 0;
    padding: 12px;
    background: var(--theme-components-overlays-dashboardoverlay-dashboard-chunk-preview-background-1hc01, rgba(10, 20, 30, 0.6));
    border: 1px solid var(--theme-components-overlays-dashboardoverlay-dashboard-chunk-list-border-19ivk, rgba(0, 200, 200, 0.12));
    border-radius: 6px;
    color: var(--palette-text-soft);
    font-size: 11px;
    font-family: 'SF Mono', Monaco, monospace;
    line-height: 1.5;
    white-space: pre-wrap;
    word-break: break-word;
    max-height: 300px;
    overflow-y: auto;
}

/* ── Permissions Tab ── */

/* Blacklist table */

.dashboard-blacklist-table {
    display: flex;
    flex-direction: column;
    gap: 2px;
    margin-bottom: 10px;
}

.dashboard-blacklist-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 10px;
    background: var(--theme-components-overlays-dashboardoverlay-dashboard-chunk-list-background-1sfna, rgba(10, 20, 30, 0.5));
    border: 1px solid var(--theme-components-overlays-dashboardoverlay-dashboard-blacklist-row-border-kz1a9, rgba(0, 200, 200, 0.1));
    border-radius: 4px;
}

.dashboard-blacklist-value {
    flex: 1;
    font-size: 12px;
    font-family: 'SF Mono', Monaco, monospace;
    color: var(--palette-text-faint);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.dashboard-blacklist-remove {
    flex-shrink: 0;
    background: none;
    border: none;
    color: var(--palette-text-muted);
    font-size: 16px;
    cursor: pointer;
    padding: 0 4px;
    line-height: 1;
    transition: color 0.15s ease;
}

.dashboard-blacklist-remove:hover {
    color: var(--palette-danger);
}

.appearance-theme-studio-btn {
    margin: 2px 0 14px;
}

/* ===== START OF DayTimeline.css ===== */

.day-timeline {
    --timeline-event: #57c7d4;
    --timeline-task: #9ed765;
    position: relative;
    min-height: 0;
    flex: 1;
}

.day-timeline-legend {
    display: flex;
    align-items: center;
    gap: 12px;
    min-height: 26px;
    padding: 0 4px 7px;
    color: rgba(232, 244, 244, 0.52);
    font-size: 9px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.day-timeline-legend span {
    display: inline-flex;
    align-items: center;
    gap: 5px;
}

.day-timeline-legend i {
    width: 7px;
    height: 7px;
    border-radius: 2px;
    background: var(--timeline-event);
}

.day-timeline-legend i.task {
    background: var(--timeline-task);
}

.day-timeline-legend i.proposal {
    background: transparent;
    border: 1px dashed #c897ff;
}

.day-timeline-viewport {
    position: relative;
    overflow: auto;
    scrollbar-width: thin;
    scrollbar-color: rgba(92, 220, 218, 0.25) transparent;
    border: 1px solid rgba(111, 223, 222, 0.1);
    border-radius: 10px;
    background: rgba(2, 13, 20, 0.34);
}

.day-timeline-canvas {
    position: relative;
    min-width: 280px;
}

.day-timeline-hour {
    position: absolute;
    left: 0;
    right: 0;
    border-top: 1px solid rgba(164, 224, 222, 0.075);
    pointer-events: none;
}

.day-timeline-hour span {
    display: inline-block;
    width: 46px;
    padding: 4px 7px 0 0;
    color: rgba(225, 240, 239, 0.34);
    font-size: 9px;
    text-align: right;
}

.day-timeline-block {
    position: absolute;
    z-index: 2;
    display: flex;
    align-items: flex-start;
    gap: 7px;
    min-width: 0;
    overflow: hidden;
    padding: 6px 7px;
    border: 1px solid color-mix(in srgb, var(--timeline-event) 38%, transparent);
    border-left: 3px solid var(--timeline-event);
    border-radius: 6px;
    background: color-mix(in srgb, var(--timeline-event) 13%, rgba(8, 22, 30, 0.92));
    color: rgba(244, 251, 250, 0.9);
    cursor: pointer;
    transition: border-color 120ms ease, filter 120ms ease, transform 120ms ease;
}

.day-timeline-block:hover {
    z-index: 4;
    border-color: color-mix(in srgb, var(--timeline-event) 68%, transparent);
    filter: brightness(1.12);
}

.day-timeline-block.task,
.day-timeline-block.timer {
    --timeline-event: var(--timeline-task);
}

.day-timeline-block.note {
    --timeline-event: #f2bd67;
}

.day-timeline-block.proposal {
    --timeline-event: #c897ff;
    border-style: dashed;
    background: rgba(113, 61, 146, 0.14);
    cursor: default;
}

.day-timeline-block.session-complete {
    opacity: 0.52;
}

.day-timeline-block.task-complete strong {
    text-decoration: line-through;
}

.day-timeline-check {
    width: 15px;
    height: 15px;
    flex: 0 0 auto;
    display: grid;
    place-items: center;
    margin: 0;
    padding: 0;
    border: 1px solid color-mix(in srgb, var(--timeline-event) 70%, transparent);
    border-radius: 50%;
    background: transparent;
    color: var(--timeline-event);
    font-size: 10px;
    cursor: pointer;
}

.session-complete .day-timeline-check {
    background: color-mix(in srgb, var(--timeline-event) 20%, transparent);
}

.day-timeline-block-copy {
    min-width: 0;
    line-height: 1.2;
}

.day-timeline-block-copy strong,
.day-timeline-block-copy span {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.day-timeline-block-copy strong {
    font-size: 11px;
    font-weight: 600;
}

.day-timeline-block-copy span {
    margin-top: 2px;
    color: rgba(235, 244, 243, 0.52);
