}

.day-timeline-popover-actions button,
.day-timeline-task-done {
    padding: 6px 8px;
    border: 1px solid rgba(124, 214, 210, 0.2);
    border-radius: 5px;
    background: rgba(255, 255, 255, 0.04);
    color: rgba(239, 248, 247, 0.7);
