}

.new-canvas-option-icon {
    font-size: 18px;
    color: #0ff;
    margin-bottom: 2px;
}

.new-canvas-option-label {
    font-size: 12px;
    font-weight: 600;
    color: #eafcff;
}

.new-canvas-option-desc {
    font-size: 10px;
    color: rgba(207, 239, 255, 0.55);
}

/* ===== File picker ===== */

.new-canvas-file-flow {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 12px;
    height: 100%;
    overflow-y: auto;
