/* =====================
   Notes Widget Styles
   ===================== */

/* Drawer */

.notes-drawer {
    transform-style: preserve-3d;
    perspective: 400px;
    position: absolute;
    right: 22%;
    height: 520px;
    top: 28%;
    background: var(--theme-components-notes-noteswidget-notes-drawer-background-gradient);
    width: 300px;
    overflow: hidden;
    backdrop-filter: blur(5px);
    z-index: 18;
    display: flex;
    visibility: hidden;
    flex-direction: column;
    transition: visibility 2s, transform 1s;
}

.notes-drawer.open {
    visibility: visible;
}

.notes-drawer.drawer-dragging {
    transition: none;
    opacity: 0.9;
}

.notes-drawer.drawer-resizing {
    transition: none;
}

