.notes-drawer-header {
    display: flex;
    border-radius: 100px 100px 0 0;
    justify-content: space-between;
    align-items: center;
    padding: 12px px;
    flex-shrink: 0;
    padding-top: 0px;
    margin-top: 0px;
    padding: 20px;
    padding-right: 30px;
    padding-bottom: 3px;
