    height: 26px;
    border-radius: 64px;
    border: 1px solid var(--theme-components-notes-noteswidget-notes-add-btn-border-1plkp, white);
    background: transparent;
    color: var(--theme-components-notes-noteswidget-notes-add-btn-border-1plkp, white);
    font-size: 20px;
    cursor: pointer;
    transition: all 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.notes-close-btn {
    color: var(--theme-components-notes-noteswidget-notes-add-btn-border-1plkp, white);
    background: var(--theme-components-notes-noteswidget-notes-close-btn-background-i0tgi, red);
    box-shadow: inset 0 0 4px var(--theme-components-notes-noteswidget-notes-close-btn-box-shadow-9ja92, pink);
