/* =====================
   Floating Notes
   ===================== */

.floating-note {
    background: var(--theme-components-notes-noteswidget-floating-note-background-gradient, linear-gradient(to bottom, transparent, black, transparent));
    position: fixed;
    z-index: 21;
    min-width: 220px;
    min-height: 60px;
    cursor: grab;
    transition: opacity .2s;
    animation: popIn 0.2s ease;
    border: 1px solid rgba(255, 255, 255, .2);
    border-top: 3px solid var(--theme-components-notes-noteswidget-floating-note-border-top-1x3oe, rgba(0, 200, 200, 0.5));
    box-shadow: 0 8px 30px var(--theme-components-notes-noteswidget-floating-note-box-shadow-op6ip, rgba(0, 0, 0, 0.5));
    border-radius: 8px;
    overflow: hidden;
}

.floating-note .note-textarea {
    backdrop-filter: brightness(1.4);
    background: var(--theme-components-notes-noteswidget-floating-note-note-textarea-background-1p7wk, rgba(0, 0, 0, .8));
}

.floating-note:active,
.floating-note.dragging {
    cursor: grabbing;
    z-index: 22;
    box-shadow: 0 12px 40px var(--theme-components-notes-noteswidget-floating-note-active-box-shadow-1x3oe, rgba(0, 0, 0, 0.6));
    transform: scale(.99);
}

.floating-note.dragging {
    opacity: .8;
}

@keyframes popIn {
    from {
        opacity: 0;
        transform: scale(0.9);
    }

    to {
        opacity: 1;
        transform: scale(1);
    }
}

.floating-note .note-card {
    user-select: auto;
    background: var(--theme-components-notes-noteswidget-floating-note-note-card-background-gradient, linear-gradient(to bottom, rgba(0, 0, 0, 0.5), transparent));
    border: 1px solid var(--theme-components-notes-noteswidget-notes-close-btn-box-shadow-9ja92, pink);
    backdrop-filter: blur(8px)brightness(.4);
    height: 100%;
}

.floating-note .note-header {
    cursor: grab;
}

.floating-note.dragging .note-header {
    cursor: grabbing;
}

.floating-note.resizing {
    cursor: nwse-resize;
}

.note-resize-handle {
    position: absolute;
    right: 2px;
    bottom: 2px;
    width: 14px;
    height: 14px;
    cursor: nwse-resize;
    border-radius: 3px;
    opacity: 0.55;
    background-image: var(--theme-components-notes-noteswidget-note-resize-handle-background-image-gradient, linear-gradient(135deg, transparent 45%, rgba(180, 220, 235, 0.8) 45%, rgba(180, 220, 235, 0.8) 55%, transparent 55%));
}

.note-resize-handle:hover {
    opacity: 0.9;
}

/* Drawer Resize Handle - invisible until hovered */

.drawer-resize-handle {
    position: absolute;
    right: 0;
    bottom: 0;
    width: 120px;
    height: 20px;
    cursor: nwse-resize;
    opacity: 0;
    transition: opacity 0.2s ease;
    z-index: 6;
}

.drawer-resize-handle::after {
    content: '';
    position: absolute;
    right: 4px;
    bottom: 4px;
    width: 10px;
    height: 10px;
    background-image: var(--theme-components-notes-noteswidget-drawer-resize-handle-after-background-image-gradient, linear-gradient(135deg, transparent 40%, rgba(255, 255, 255, 0.5) 40%, rgba(255, 255, 255, 0.5) 50%, transparent 50%), linear-gradient(135deg, transparent 60%, rgba(255, 255, 255, 0.5) 60%, rgba(255, 255, 255, 0.5) 70%, transparent 70%), linear-gradient(135deg, transparent 80%, rgba(255, 255, 255, 0.5) 80%, rgba(255, 255, 255, 0.5) 90%, transparent 90%));
    border-radius: 0 0 12px 0;
}

.notes-drawer:hover .drawer-resize-handle {
    opacity: 1;
}

.drawer-resize-handle:hover {
    opacity: 1 !important;
}

.notes-drawer.drawer-resizing .drawer-resize-handle {
    opacity: 1;
}

