/* =====================
   Organizer Modal Styles
   ===================== */

.organizer-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    backdrop-filter: blur(18px);
    background: var(--theme-components-overlays-organizermodal-organizer-overlay-background-gowbr, rgba(0, 255, 255, .1));
    display: flex;
    align-items: stretch;
    justify-content: stretch;
    z-index: 1200;
    perspective: 500px;
    animation: fadeIn .4s ease;
}

@keyframes fadeIn {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

.organizer-modal {
    transform-style: preserve-3d;
    transform: rotateY(0deg);
    ;
    width: 100vw;
    max-width: 100vw;
    height: 100vh;
    max-height: 100vh;
    background: var(--theme-components-overlays-organizermodal-organizer-modal-background-gradient, linear-gradient(135deg, #80d2972d 0%, #0115343a 100%));
    filter: brightness(2);
    border-radius: 0;
    display: flex;
    border: 0;
    flex-direction: column;
    animation: flipUp .751s cubic-bezier(0.65, 0.35, 0.65, 1.2) forwards;
}

@keyframes flipUp {
    from {
        opacity: 0;
        filter: blur(30px);
        box-shadow: 0 0 40px yellow;
        transform: translateY(-120px) scale(0.0098)rotate(0deg)rotateX(50deg);
    }

    to {
        opacity: 1;
        filter: blur(0px);
        background-color: transparent;
        box-shadow: 0 0 40px var(--theme-components-overlays-organizermodal-to-box-shadow-n09w3, rgba(0, 0, 0, 0.2));
        transform: translateY(0) scale(1)rotate(0deg)rotateX(0deg);
    }
}

