    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
    background: var(--theme-components-overlays-organizermodal-org-item-row-background-1d738, rgba(30, 50, 70, 0.3));
    border: 1px solid var(--theme-components-overlays-organizermodal-organizer-tab-active-background-1w8u1, rgba(0, 200, 200, 0.08));
    border-radius: 6px;
    margin-bottom: 4px;
    transition: all 0.15s ease;
}

.org-item-row:hover {
    background: var(--theme-components-overlays-organizermodal-org-item-row-hover-background-10wdq, rgba(0, 100, 120, 0.2));
    border-color: var(--theme-components-overlays-organizermodal-tab-count-background-1bm8l, rgba(0, 200, 200, 0.2));
}

.org-item-row.done {
    opacity: 0.55;
}

.org-item-check {
    width: 22px;
    height: 22px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: transparent;
    border: 1.5px solid var(--theme-components-overlays-organizermodal-org-item-check-border-1i94y, rgba(255, 255, 255, 0.2));
    border-radius: 50%;
    color: var(--palette-text-subtle);
    font-size: 12px;
    cursor: pointer;
    transition: all 0.15s ease;
}

.org-item-check:hover {
    border-color: var(--palette-accent-cyan);
    color: var(--palette-accent-cyan);
}

.org-item-check.checked {
    border-color: var(--palette-success);
    color: var(--palette-success);
    background: var(--theme-components-overlays-organizermodal-org-item-check-checked-background-5xil6, rgba(76, 175, 80, 0.1));
}

.org-item-type {
    font-size: 14px;
    flex-shrink: 0;
    width: 20px;
    text-align: center;
}

.org-item-info {
    flex: 1;
    min-width: 0;
}

.org-item-name {
    font-size: 13px;
    font-weight: 500;
    color: var(--palette-text-main);
    display: block;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.org-item-name.strike {
    text-decoration: line-through;
}

.org-item-meta {
    display: flex;
    gap: 8px;
    margin-top: 2px;
}

.org-item-date,
.org-item-time {
    font-size: 10px;
    color: var(--palette-text-subtle);
}

.org-item-tag {
    font-size: 9px;
    color: var(--palette-accent-cyan);
    background: var(--theme-components-overlays-organizermodal-organizer-tabs-border-bottom-kz1a9, rgba(0, 200, 200, 0.1));
    padding: 1px 5px;
    border-radius: 3px;
    text-transform: uppercase;
}

.org-item-rec {
    font-size: 11px;
    color: var(--theme-components-overlays-organizermodal-org-item-rec-color-lx85k, #a855f7);
}

.org-item-delete {
    background: none;
    border: none;
    color: var(--palette-text-dim);
    font-size: 18px;
    cursor: pointer;
    padding: 0 4px;
    line-height: 1;
    transition: color 0.15s ease;
    flex-shrink: 0;
    opacity: 0;
    transition: opacity 0.15s ease, color 0.15s ease;
}

.org-item-row:hover .org-item-delete {
    opacity: 1;
}

.org-item-delete:hover {
    color: var(--palette-danger);
}

/* =====================
   Loading & Empty States
   ===================== */

.loading-state,
.empty-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 40px;
    color: var(--palette-text-muted);
    font-size: 14px;
    text-align: center;
    gap: 16px;
}

/* =====================
   Footer
   ===================== */

.organizer-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 12px 20px;
    border-top: 1px solid var(--theme-components-overlays-organizermodal-organizer-tabs-border-bottom-kz1a9, rgba(0, 200, 200, 0.1));
}

.organizer-btn {
    padding: 8px 16px;
    border-radius: 6px;
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
}

.organizer-btn.secondary {
    background: transparent;
    border: 1px solid var(--theme-components-overlays-organizermodal-organizer-btn-secondary-border-1gvsk, rgba(255, 255, 255, 0.15));
    color: var(--palette-text-subtle);
}

.organizer-btn.secondary:hover {
    background: var(--theme-components-overlays-organizermodal-org-section-title-border-bottom-vmrwx, rgba(255, 255, 255, 0.05));
    color: var(--palette-text-soft);
}

.projects-count {
    font-size: 12px;
    color: var(--palette-text-muted);
    margin-right: auto;
    display: flex;
    align-items: center;
}

/* ===== START OF PhantomSection.css ===== */

/* ── PhantomSection ────────────────────────────────────────────────
   Phantom control drawer embedded at the bottom of TasksPanel.
   Aesthetic mirrors the Phantom macOS app: dark/var(--theme-components-phantomsection-root-app-o0md2, black) background,
   monospace font, var(--theme-components-phantomsection-root-app-b5mm4, green) (var(--palette-neon-green)) record accent, cyan (var(--theme-components-phantomsection-root-app-1jpsf, #00e5ff))
   for running/playback states.
   ─────────────────────────────────────────────────────────────── */

/* ── Container ───────────────────────────────────────────────────── */

.phantom-section {
    flex-shrink: 0;
}

/* ── Toggle button (replaces old Record button) ───────────────────── */

.phantom-toggle {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    background: var(--theme-components-phantomsection-phantom-toggle-background-afq8i, #0a0a0a);
    border: none;
    border-top: 1px solid var(--theme-components-phantomsection-phantom-toggle-border-top-2mdx5, #1a1a1a);
    color: var(--palette-text-dim);
    font-family: 'Menlo', 'SF Mono', 'Courier New', monospace;
    font-size: 11px;
    cursor: pointer;
    text-align: left;
    transition: color 0.15s, border-top-color 0.15s;
}

.phantom-toggle:hover {
    color: var(--palette-text-soft);
}

.phantom-toggle.open {
    color: var(--palette-neon-green);
    border-top-color: var(--theme-components-phantomsection-phantom-toggle-open-border-top-color-1glmw, rgba(0, 255, 136, 0.4));
}

.phantom-toggle-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--theme-components-phantomsection-phantom-toggle-dot-background-1p0ut, #2a2a2a);
    flex-shrink: 0;
    transition: background 0.2s, box-shadow 0.2s;
}

.phantom-toggle.open .phantom-toggle-dot {
    background: var(--palette-neon-green);
}

.phantom-toggle.running .phantom-toggle-dot {
    background: var(--palette-neon-green);
    box-shadow: 0 0 6px var(--palette-neon-green);
    animation: ph-pulse 1s infinite;
}

.phantom-toggle-label {
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
}

.phantom-toggle-status {
    margin-left: auto;
    font-size: 10px;
    color: var(--palette-neon-green);
    max-width: 160px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* ── Drawer ───────────────────────────────────────────────────────── */

.phantom-drawer {
    background: var(--theme-components-phantomsection-phantom-drawer-background-1q77m, #000);
    border-top: 1px solid var(--theme-components-phantomsection-phantom-toggle-border-top-2mdx5, #1a1a1a);
    font-family: 'Menlo', 'SF Mono', 'Courier New', monospace;
    font-size: 12px;
    color: var(--palette-text-main);
    display: flex;
    flex-direction: column;
    max-height: 380px;
    overflow: hidden;
}

/* ── Mode tabs ────────────────────────────────────────────────────── */

.phantom-tabs {
    display: flex;
    border-bottom: 1px solid var(--theme-components-phantomsection-phantom-toggle-border-top-2mdx5, #1a1a1a);
    background: var(--theme-components-phantomsection-phantom-tabs-background-yq5ln, #050505);
    flex-shrink: 0;
}

.phantom-tab {
    flex: 1;
    padding: 8px 0;
    background: none;
    border: none;
    border-bottom: 2px solid transparent;
    color: var(--theme-components-phantomsection-phantom-tab-color-161cz, #444);
    font-family: inherit;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    cursor: pointer;
    transition: color 0.15s, border-color 0.15s;
}

.phantom-tab:hover {
    color: var(--palette-text-subtle);
}

.phantom-tab.active {
    color: var(--palette-neon-green);
    border-bottom-color: var(--palette-neon-green);
}

/* ── Status bar ────────────────────────────────────────────────────── */

.phantom-status {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 5px 12px;
    font-size: 10px;
    background: var(--theme-components-phantomsection-phantom-status-background-16ah5, rgba(0, 255, 136, 0.03));
    border-bottom: 1px solid var(--theme-components-phantomsection-phantom-status-border-bottom-1of2t, #111);
    flex-shrink: 0;
}

.phantom-status-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    flex-shrink: 0;
    background: var(--theme-components-phantomsection-phantom-status-dot-background-1uyf8, #333);
}

.phantom-status.running .phantom-status-dot {
    background: var(--palette-neon-green);
    box-shadow: 0 0 5px var(--palette-neon-green);
    animation: ph-pulse 1s infinite;
}

.phantom-status.waiting .phantom-status-dot {
    background: var(--theme-components-phantomsection-phantom-status-waiting-phantom-status-dot-background-ujrr8, #facc15);
}

.phantom-status.completed .phantom-status-dot {
    background: var(--theme-components-phantomsection-root-app-1jpsf, #00e5ff);
}

.phantom-status.error .phantom-status-dot {
    background: var(--theme-components-phantomsection-phantom-status-error-phantom-status-dot-background-sabad, #f87171);
}

.phantom-status.stopped .phantom-status-dot {
    background: var(--theme-components-phantomsection-phantom-tab-color-161cz, #444);
}

.phantom-status-text {
    flex: 1;
    color: var(--theme-components-phantomsection-phantom-status-text-color-fs5n5, #777);
}

.phantom-status.running .phantom-status-text {
    color: var(--palette-neon-green);
}

.phantom-status.completed .phantom-status-text {
    color: var(--theme-components-phantomsection-root-app-1jpsf, #00e5ff);
}

.phantom-status.error .phantom-status-text {
    color: var(--theme-components-phantomsection-phantom-status-error-phantom-status-dot-background-sabad, #f87171);
}

.phantom-progress {
    width: 52px;
    height: 2px;
    background: var(--theme-components-phantomsection-phantom-toggle-border-top-2mdx5, #1a1a1a);
    border-radius: 1px;
    overflow: hidden;
    flex-shrink: 0;
}

.phantom-progress-fill {
    height: 100%;
    background: var(--palette-neon-green);
    border-radius: 1px;
    transition: width 0.4s ease;
}

.phantom-elapsed {
    font-size: 10px;
    color: var(--theme-components-phantomsection-phantom-status-dot-background-1uyf8, #333);
    flex-shrink: 0;
}

@keyframes ph-pulse {

    0%,
    100% {
        opacity: 1;
    }

    50% {
        opacity: 0.3;
    }
}

/* ── Workflow list ────────────────────────────────────────────────── */

.phantom-playback {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    min-height: 0;
}

.phantom-wf-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 12px 4px;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--theme-components-phantomsection-phantom-status-dot-background-1uyf8, #333);
    flex-shrink: 0;
}

.phantom-refresh {
    background: none;
    border: none;
    color: var(--theme-components-phantomsection-phantom-status-dot-background-1uyf8, #333);
