    cursor: default;
}

.phantom-wf-list {
    flex: 1;
    overflow-y: auto;
    padding-bottom: 4px;
    min-height: 0;
}

.phantom-empty {
    padding: 14px 12px;
    font-size: 10px;
    color: var(--theme-components-phantomsection-phantom-toggle-dot-background-1p0ut, #2a2a2a);
    text-align: center;
}

.phantom-wf-row {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 6px 12px;
    cursor: pointer;
    transition: background 0.1s;
}

.phantom-wf-row:hover {
    background: var(--theme-components-phantomsection-phantom-wf-row-hover-background-1f6dx, rgba(255, 255, 255, 0.025));
}

.phantom-wf-row.selected {
    background: var(--theme-components-phantomsection-phantom-wf-row-selected-background-1vsvg, rgba(0, 255, 136, 0.05));
}

.phantom-wf-info {
    flex: 1;
    min-width: 0;
}

.phantom-wf-name {
    display: block;
    font-size: 12px;
    color: var(--theme-components-phantomsection-phantom-wf-name-color-rnz45, #bbb);
