    color: var(--theme-components-phantomsection-phantom-status-dot-background-1uyf8, #333);
}

.phantom-wf-row.selected .phantom-wf-name {
    color: var(--palette-neon-green);
}

.phantom-wf-row.selected .phantom-wf-meta {
    color: var(--theme-components-phantomsection-phantom-toggle-open-border-top-color-1glmw, rgba(0, 255, 136, 0.4));
}

/* Row action buttons */

.phantom-wf-inspect,
