    overflow: hidden;
    text-overflow: ellipsis;
}

.phantom-event-row:hover {
    color: var(--palette-text-muted);
    background: var(--theme-components-phantomsection-phantom-event-row-hover-background-i129j, rgba(255, 255, 255, 0.015));
}

/* ── Run options ──────────────────────────────────────────────────── */

.phantom-run-opts {
