}

/* ── Record tab ───────────────────────────────────────────────────── */

.phantom-record {
    padding: 20px 16px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
}

.phantom-record-desc {
    font-size: 10px;
    color: var(--theme-components-phantomsection-phantom-status-dot-background-1uyf8, #333);
    text-align: center;
    line-height: 1.7;
    max-width: 240px;
}

.phantom-btn.record-launch {
    background: var(--theme-components-phantomsection-phantom-wf-run-hover-background-walzz, rgba(0, 255, 136, 0.06));
