    padding: 6px 10px;
    background: var(--theme-components-phantomsection-phantom-wf-del-hover-background-f4575, rgba(248, 113, 113, 0.06));
    border: 1px solid var(--theme-components-phantomsection-phantom-btn-danger-border-color-1d4wr, rgba(248, 113, 113, 0.2));
    border-radius: 4px;
    font-size: 10px;
    color: var(--theme-components-phantomsection-phantom-status-error-phantom-status-dot-background-sabad, #f87171);
