/* ===== START OF bfast.css ===== */

/*
 * bfast.css — styles for the BfastBundle (Toast, Snackbar, Margerin).
 *
 * Visual language: soft, floating pills on a dark background.
 * Positioning: the bundle is a fixed-position stack at the bottom of
 * the screen, centered horizontally, with the margerin at the very
 * bottom (nearest the user's attention) and toasts/snackbars stacked
 * above it.
 *
 * Colors are intentionally muted purples and blues — the bundle is a
 * background/ambient surface, not a hero element.
 */

/* ---------- layout ---------- */

.bfast-bundle {
    position: fixed;
    left: 50%;
    bottom: 24px;
    transform: translateX(-50%);
    z-index: 30;
    pointer-events: none;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    max-width: min(560px, calc(100vw - 32px));
    width: max-content;
}

.bfast-bundle>* {
    pointer-events: auto;
}

.bfast-bundle-snackbars,
.bfast-bundle-toasts,
.bfast-bundle-margerin-slot {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    width: 100%;
}

.bfast-bundle-margerin-slot:empty,
.bfast-bundle-toasts:empty,
.bfast-bundle-snackbars:empty {
    display: none;
}

/* ---------- keyframes ---------- */

@keyframes bfast-fade-in-up {
    from {
        opacity: 0;
        transform: translateY(8px) scale(0.98);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

@keyframes bfast-bead-pulse {

    0%,
    100% {
        transform: scale(1);
        opacity: 1;
        box-shadow: 0 0 0 0 rgba(92, 156, 255, 0.6);
    }

    50% {
        transform: scale(1.15);
        opacity: 0.9;
        box-shadow: 0 0 0 6px rgba(92, 156, 255, 0);
    }
}

/* ---------- Toast ---------- */

.bfast-toast {
    display: inline-flex;
    align-items: center;
    padding: 10px 18px;
    border-radius: 999px;
    font-size: 13px;
    font-weight: 500;
    color: #ebe8ff;
    backdrop-filter: blur(10px);
    cursor: default;
    user-select: none;
    animation: bfast-fade-in-up 180ms ease-out;
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.35);
}

.bfast-toast--success {
    background: linear-gradient(135deg, #7a6bdc 0%, #5b4fb8 100%);
    border: 1px solid rgba(255, 255, 255, 0.08);
}

.bfast-toast--info {
    background: linear-gradient(135deg, #4a4a6b 0%, #343450 100%);
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.bfast-toast--error {
    background: linear-gradient(135deg, #a85c68 0%, #823e4a 100%);
    border: 1px solid rgba(255, 255, 255, 0.08);
}

.bfast-toast-message {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 420px;
}

/* ---------- Snackbar ---------- */

.bfast-snackbar {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    padding: 10px 16px;
    border-radius: 999px;
    background: rgba(20, 20, 32, 0.88);
    border: 1.5px solid #e6c74d;
    /* yellow stroke */
    color: #f3efe4;
    font-size: 13px;
    font-weight: 500;
    backdrop-filter: blur(10px);
    cursor: default;
    user-select: none;
    animation: bfast-fade-in-up 180ms ease-out;
    box-shadow: 0 6px 24px rgba(0, 0, 0, 0.4);
}

.bfast-snackbar-bead {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #5c9cff;
    animation: bfast-bead-pulse 1.6s ease-in-out infinite;
    flex: 0 0 auto;
}

.bfast-snackbar-message {
    text-decoration: underline;
    text-decoration-color: rgba(243, 239, 228, 0.45);
    text-underline-offset: 3px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 360px;
}

.bfast-snackbar-action {
    background: transparent;
    border: 1px solid rgba(230, 199, 77, 0.55);
    color: #e6c74d;
    border-radius: 999px;
    padding: 4px 12px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: background 120ms ease, color 120ms ease;
}

.bfast-snackbar-action:hover {
    background: rgba(230, 199, 77, 0.12);
    color: #f5dc6a;
}

/* ---------- Margerin ---------- */

.bfast-margerin-root {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    animation: bfast-fade-in-up 200ms ease-out;
}

.bfast-margerin-pill {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding: 12px 16px 12px 22px;
    border-radius: 999px;
    background: linear-gradient(135deg, #2b2448 0%, #1c1830 100%);
    border: 1px solid rgba(255, 255, 255, 0.08);
    color: #f0ecff;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
    user-select: none;
    box-shadow: 0 10px 32px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(124, 108, 220, 0.25);
    transition: transform 120ms ease, box-shadow 160ms ease, border-color 160ms ease;
}

.bfast-margerin-pill:hover {
    transform: translateY(-1px);
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(148, 130, 246, 0.45);
    border-color: rgba(148, 130, 246, 0.35);
}

.bfast-margerin-pill:active {
    transform: translateY(0);
}

.bfast-margerin-pill--check {
    box-shadow: 0 10px 32px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(120, 210, 150, 0.35);
}

.bfast-margerin-pill--x {
    box-shadow: 0 10px 32px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(220, 120, 120, 0.35);
}

.bfast-margerin-pill--chat {
    box-shadow: 0 10px 32px rgba(0, 0, 0, 0.55), 0 0 0 1px rgba(120, 170, 230, 0.35);
}

.bfast-margerin-label {
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 380px;
}

.bfast-margerin-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    border-radius: 50%;
    font-size: 14px;
    line-height: 1;
    flex: 0 0 auto;
}

.bfast-margerin-icon--primary {
    background: rgba(255, 255, 255, 0.08);
    color: #ffffff;
    border: 1px solid rgba(255, 255, 255, 0.18);
}

.bfast-margerin-icon--primary.bfast-margerin-icon--check {
    background: rgba(120, 210, 150, 0.18);
    color: #b6f0c9;
    border-color: rgba(120, 210, 150, 0.45);
}

.bfast-margerin-icon--primary.bfast-margerin-icon--x {
    background: rgba(220, 120, 120, 0.18);
    color: #f3bcbc;
    border-color: rgba(220, 120, 120, 0.45);
}

.bfast-margerin-icon--primary.bfast-margerin-icon--chat {
    background: rgba(120, 170, 230, 0.18);
    color: #c9defc;
    border-color: rgba(120, 170, 230, 0.45);
}

.bfast-margerin-secondary-row {
    display: flex;
    align-items: center;
    gap: 10px;
}

.bfast-margerin-icon--secondary {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: rgba(240, 236, 255, 0.55);
    cursor: pointer;
    opacity: 0.65;
    transition: opacity 120ms ease, transform 120ms ease, background 120ms ease, border-color 120ms ease;
}

.bfast-margerin-icon--secondary:hover {
    opacity: 1;
    transform: translateY(-1px);
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.22);
    color: #ffffff;
}

.bfast-margerin-icon--secondary.bfast-margerin-icon--x:hover {
    background: rgba(220, 120, 120, 0.18);
    border-color: rgba(220, 120, 120, 0.55);
    color: #f3bcbc;
}

.bfast-margerin-icon--secondary.bfast-margerin-icon--chat:hover {
    background: rgba(120, 170, 230, 0.18);
    border-color: rgba(120, 170, 230, 0.55);
    color: #c9defc;
}

/* ---------- reduced motion ---------- */

@media (prefers-reduced-motion: reduce) {

    .bfast-toast,
    .bfast-snackbar,
    .bfast-margerin-root {
        animation: none;
    }

    .bfast-snackbar-bead {
        animation: none;
    }

    .bfast-margerin-pill,
    .bfast-margerin-icon--secondary {
        transition: none;
    }
}

/* ===== START OF briizy.css ===== */

/* briizy overlay (PLAN-BRIIZY.md §9).
 *
 * Everything in here floats over the desktop, so two rules hold throughout:
 * no opaque backgrounds outside the avatar and its bubble, and
 * `pointer-events: none` by default — only the avatar and the bubble opt in, and
 * the window is click-through except while the renderer's hit test says
 * otherwise. */

.briizy-stage {
    position: fixed;
    inset: 0;
    pointer-events: none;
    font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', system-ui, sans-serif;
    -webkit-font-smoothing: antialiased;
}

/* The wrapper is now anchored inside the small pet window (like OpenPets'
   PetHostView). Drift moves the window itself via shell.updateBounds, so the
   wrapper stays at a fixed inset and only bobs. Side modifiers keep the bubble
   inside the window. */

.briizy-avatar-wrap {
    position: absolute;
    bottom: 24px;
    width: var(--briizy-w, 116px);
    height: var(--briizy-h, 175px);
    pointer-events: none;
    will-change: transform;
}

.briizy-avatar-wrap--left {
    right: 24px;
    left: auto;
    top: auto;
}

.briizy-avatar-wrap--right {
    left: 24px;
    right: auto;
    top: auto;
}

.briizy-avatar-wrap--left.briizy-avatar-wrap,
.briizy-avatar-wrap--right.briizy-avatar-wrap {
    /* ensure bottom anchoring wins over legacy top:0 */
    top: auto;
}

/* ── Avatar ─────────────────────────────────────────────────────────── */

.briizy-avatar {
    appearance: none;
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    padding: 0;
    border: 0;
    background-color: transparent;
    background-repeat: no-repeat;
    /* 6-cell horizontal sheet: the image is six element-widths wide, so shifting
     background-position-x by -100% per cell lands exactly on each frame. */
    background-size: 600% 100%;
    background-position-y: 0;
    pointer-events: auto;
    cursor: pointer;
    filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.35));
    transition: transform 0.18s ease, filter 0.18s ease;
}

.briizy-avatar.is-hovered {
    transform: scale(1.06);
    filter: drop-shadow(0 12px 22px rgba(0, 0, 0, 0.45)) drop-shadow(0 0 14px rgba(111, 208, 255, 0.35));
}

/* A soft glow keyed to state, so briizy reads at a glance without a bubble. */

.briizy-avatar.is-error {
    filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.35)) drop-shadow(0 0 16px rgba(224, 71, 62, 0.45));
}

.briizy-avatar.is-sleeping {
    opacity: 0.62;
    filter: drop-shadow(0 8px 14px rgba(0, 0, 0, 0.3)) saturate(0.7);
}

.briizy-avatar.is-working,
.briizy-avatar.is-thinking {
    filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.35)) drop-shadow(0 0 14px rgba(75, 217, 127, 0.3));
}

.briizy-avatar.is-speaking {
    filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.35)) drop-shadow(0 0 16px rgba(111, 176, 255, 0.45));
}

/* ── Speech bubble ──────────────────────────────────────────────────── */

.briizy-bubble {
    position: absolute;
    bottom: 62%;
    width: 296px;
    max-width: 296px;
    padding: 14px 16px;
    border-radius: 16px;
    background: rgba(10, 16, 30, 0.92);
    border: 1px solid rgba(111, 176, 255, 0.42);
    box-shadow: 0 14px 40px rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(14px);
    color: rgba(255, 255, 255, 0.92);
    pointer-events: auto;
    animation: briizy-bubble-in 0.22s ease-out;
}

.briizy-bubble--left {
    right: calc(100% - 12px);
}

.briizy-bubble--right {
    left: calc(100% - 12px);
}

/* The tail — a rotated square tucked under the bubble's edge. */

.briizy-bubble::after {
    content: '';
    position: absolute;
    bottom: -6px;
    width: 12px;
    height: 12px;
    background: rgba(10, 16, 30, 0.92);
    border-right: 1px solid rgba(111, 176, 255, 0.42);
    border-bottom: 1px solid rgba(111, 176, 255, 0.42);
    transform: rotate(45deg);
}

.briizy-bubble--left::after {
    right: 24px;
}

.briizy-bubble--right::after {
    left: 24px;
}

.briizy-bubble.is-result {
    border-color: rgba(255, 255, 255, 0.25);
}

@keyframes briizy-bubble-in {
    from {
        opacity: 0;
        transform: translateY(6px) scale(0.97);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

.briizy-bubble__title {
    margin: 0 0 6px;
    font-size: 13px;
    font-weight: 650;
    line-height: 1.3;
    color: #cfe4ff;
}

.briizy-bubble__body {
    margin: 0;
    font-size: 13px;
    line-height: 1.45;
    color: rgba(255, 255, 255, 0.9);
}

/* The "why" line is deliberately quiet: available, not competing. */

.briizy-bubble__why {
    margin: 8px 0 0;
    font-size: 11.5px;
    line-height: 1.4;
    color: rgba(255, 255, 255, 0.45);
}

.briizy-bubble__result {
    margin: 0;
    font-size: 12.5px;
    line-height: 1.4;
    color: rgba(255, 255, 255, 0.8);
}

.briizy-bubble__actions {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 12px;
}

.briizy-btn {
    appearance: none;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.07);
    color: rgba(255, 255, 255, 0.88);
    font-family: inherit;
    font-size: 12px;
    line-height: 1;
    padding: 7px 12px;
    cursor: pointer;
    transition: background 0.12s ease, border-color 0.12s ease, color 0.12s ease;
}

.briizy-btn:hover {
    background: rgba(255, 255, 255, 0.14);
    border-color: rgba(255, 255, 255, 0.4);
}

.briizy-btn--accept {
    border-color: rgba(75, 217, 127, 0.5);
    color: #8ff0b4;
    font-size: 13px;
    padding: 7px 13px;
}

.briizy-btn--accept:hover {
    background: rgba(75, 217, 127, 0.18);
}

.briizy-btn--dismiss {
    border-color: rgba(255, 255, 255, 0.22);
    color: rgba(255, 255, 255, 0.6);
    font-size: 13px;
    padding: 7px 13px;
}

.briizy-btn--open {
    margin-left: auto;
    font-size: 11px;
    color: rgba(111, 176, 255, 0.9);
    border-color: rgba(111, 176, 255, 0.35);
}

.briizy-btn--open:hover {
    background: rgba(75, 139, 255, 0.18);
}

/* ── Hover tip ──────────────────────────────────────────────────────── */

.briizy-tip {
    position: absolute;
    bottom: 58%;
    padding: 5px 10px;
    border-radius: 999px;
    background: rgba(10, 16, 30, 0.88);
    border: 1px solid rgba(255, 255, 255, 0.14);
    color: rgba(255, 255, 255, 0.75);
    font-size: 11px;
    white-space: nowrap;
    pointer-events: none;
    animation: briizy-bubble-in 0.16s ease-out;
}

.briizy-tip--left {
    right: calc(100% - 16px);
}

.briizy-tip--right {
    left: calc(100% - 16px);
}

/* Honour the system setting: no bob, no drift easing, no bubble entrance. */

@media (prefers-reduced-motion: reduce) {

    .briizy-avatar,
    .briizy-bubble,
    .briizy-tip {
        animation: none;
        transition: none;
    }
}

/* ── Focus glow (§11) ────────────────────────────────────────────────
   Ambient edge feedback. Never blocks a click, never asks for a response, and
   fades in slowly enough that it registers as a mood rather than an alert. */

.briizy-glow {
    position: fixed;
    inset: 0;
    pointer-events: none;
    border-radius: 12px;
    animation: briizy-glow-in 1.4s ease-out;
    transition: box-shadow 1.2s ease;
}

/* An inset shadow paints the edge without covering anything underneath. */

.briizy-glow.is-focused {
    box-shadow: inset 0 0 90px -30px rgba(75, 217, 127, 0.5);
}

.briizy-glow.is-adjacent {
    box-shadow: inset 0 0 80px -34px rgba(111, 176, 255, 0.4);
}

.briizy-glow.is-drifting {
    box-shadow: inset 0 0 100px -28px rgba(224, 163, 62, 0.5);
}

@keyframes briizy-glow-in {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

@media (prefers-reduced-motion: reduce) {
    .briizy-glow {
        animation: none;
        transition: none;
    }
}

/* ===== START OF journals.css ===== */

/* ── Journals tab — home view ─────────────────────────────────────────
   Matches the briizes mockup: black field, a centered row of round action
   buttons, and a grid of notebook covers that sit dimmed until hovered or
   selected, when they light up with a cool glow + title plaque. */

.journals-home {
    position: relative;
    width: 100%;
    height: 100%;
    overflow-y: auto;
    padding: 28px 48px 64px;
    box-sizing: border-box;
    background: linear-gradient(45deg, rgba(255, 255, 255, 0.02) 25%, transparent 25%) 0 0 / 20px 20px, linear-gradient(-45deg, rgba(255, 255, 255, 0.02) 25%, transparent 25%) 0 0 / 20px 20px, linear-gradient(45deg, transparent 75%, rgba(255, 255, 255, 0.02) 75%) 0 0 / 20px 20px, linear-gradient(-45deg, transparent 75%, rgba(255, 255, 255, 0.02) 75%) 0 0 / 20px 20px;
    background-size: 12.80% 12.80%;
    background-color: var(--ui-modal-header-bg);
    background-position: 100% 100%;
    scrollbar-width: 12px;
    transition: background-color 0.35s ease-in, background-position .95s cubic-bezier(0.75, 0.1, 0.165, 1), background-size .95s cubic-bezier(0.75, 0.1, 0.165, 1);
}

.journals-home::-webkit-scrollbar {
    display: none;
}

.journals-home:has(.jr-card.is-selected) {
    background-color: rgb(0, 0, 0, .8);
    background-size: 95% 75%;
}

.journals-home:has(.jr-card.is-selected) .jr-card:not(.is-selected) {
    opacity: 0.5;
}

.journals-home:has(.jr-card.is-selected) .jr-card:not(.is-selected) .jr-card__cover {
    transform: rotateX(20deg)rotateY(10deg)translateZ(0px)skewX(-10deg)scale(.56);
}

/* ── Action row ─────────────────────────────────────────────────────── */

.jr-actions {
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 18px;
    padding: 0px 0 8px;
}

.jr-action {
    appearance: none;
    width: 42px;
    height: 42px;
    border-radius: 50px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.10), rgba(255, 255, 255, 0.03) 70%);
    color: rgba(255, 255, 255, 0.88);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.jr-action svg {
    width: 22px;
    height: 22px;
}

.jr-action:hover:not(:disabled),
.jr-action.is-active {
    border-color: rgba(255, 255, 255, 0.45);
    color: #fff;
    box-shadow: 0 0 14px rgba(255, 255, 255, 0.18);
}

.jr-action.is-stub {
    opacity: 0.55;
    cursor: default;
}

.jr-action:disabled:not(.jr-action--current) {
    opacity: 0.35;
    cursor: default;
}

.jr-action--danger:not(:disabled) {
    color: #ff9a9a;
    border-color: rgba(255, 110, 110, 0.35);
}

.jr-action--danger:hover:not(:disabled),
.jr-action--danger:focus-visible {
    color: #fff;
    background: rgba(160, 30, 30, 0.72);
    border-color: rgba(255, 150, 150, 0.8);
    box-shadow: 0 0 14px rgba(255, 70, 70, 0.28);
}

/* The "you are here" home button — solid white like the mockup */

.jr-action--current {
    background: #fff;
    border-color: #fff;
    color: #000;
    cursor: default;
}

.jr-action--current:not(:disabled) {
    cursor: pointer;
}

/* Expanding search bar */

.jr-searchbar {
    overflow: hidden;
    max-width: 0;
    opacity: 0;
    transition: max-width 0.22s ease, opacity 0.18s ease;
}

.jr-searchbar.is-open {
    max-width: 280px;
    opacity: 1;
}

.jr-searchbar__input {
    width: 250px;
}

/* ── Cover grid ─────────────────────────────────────────────────────── */

.jr-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 26px 24px;
    max-width: 1480px;
    margin: 0 auto;
    justify-items: center;
    perspective: 1000px;
}

.jr-empty {
    grid-column: 1 / -1;
    margin-top: 80px;
    color: rgba(255, 255, 255, 0.4);
    font-size: 15px;
    text-align: center;
    user-select: none;
}

.jr-card {
    appearance: none;
    position: relative;
    border: 0;
    padding: 0;
    background: none;
    cursor: pointer;
    width: 100%;
    max-width: 200px;
    aspect-ratio: 3 / 4;
    border-radius: 10px;
    outline: none;
}

.jr-card__cover {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 20px;
    display: block;
    /* resting state: heavily dimmed, like the mockup */
    filter: brightness(0.62) saturate(.8);
    transition: all .2s ease, transform .8s cubic-bezier(.4, .8, .2, 1);
    transform-style: preserve-3d;
    transform: rotateX(20deg)rotateY(10deg)translateZ(0px)skewX(-10deg)scale(.86);
    box-shadow: 3px 2px .1px rgba(255, 255, 250, 0.69), 3px 3px 1px rgba(255, 255, 255, 0.579), 5px 6px 4px rgba(0, 0, 0, .73), 0 0 10px rgba(255, 255, 255, 0), 0 0 1px rgba(0, 0, 0, 0);
}

.jr-card__plaque,
.jr-card__name,
.jr-card__count {
    transition: all .5s ease;
}

.jr-card__cover--missing {
    display: block;
    width: 100%;
    height: 100%;
    border-radius: 10px;
    background: linear-gradient(160deg, #15151a, #060608);
    border: 1px solid rgba(255, 255, 255, 0.08);
}

.jr-card:hover .jr-card__cover {
    filter: brightness(.81) saturate(.8);
}

.jr-card.is-selected .jr-card__cover {
    box-shadow: 0 0 2px white, 0 0 80px rgb(102, 100, 62), inset 0 0 30px black;
    filter: brightness(1)saturate(1);
    transform: rotateX(0deg)rotateY(0deg)translateZ(0px)scale(1.2);
    ;
}

/* Title plaque — appears with hover/selection */

.jr-card__plaque {
    position: absolute;
    top: 98%;
    left: 50%;
    transform: translateX(-50%);
    width: 86%;
    display: flex;
    flex-direction: column;
    gap: 8px;
    align-items: stretch;
    pointer-events: none;
}

.jr-card.is-selected .jr-card__plaque {
    opacity: 1;
    top: 58%;
}

.jr-card.is-selected .jr-card__plaque {
    opacity: 1;
}

.jr-card.is-selected .jr-card__count,
.jr-card.is-selected .jr-card__name {
    opacity: 1;
    background: black;
}

.jr-card__name,
.jr-card__count {
    display: block;
    background: transparent;
    border: 2px solid rgba(70, 130, 255, 0);
    box-shadow: inset 0 0 6px transparent;
    border-radius: 6px;
    color: #fff;
    text-align: center;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.jr-card__name {
    font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
    font-size: clamp(18px, 2vw, 28px);
    font-weight: 400;
    padding: 8px 10px;
    opacity: .4;
    box-shadow: inset 0 0 6px transparent;
}

.jr-card:hover .jr-card__name {
    opacity: 1;
}

.jr-card__count {
    font-family: Georgia, 'Times New Roman', serif;
    font-size: clamp(13px, 1.2vw, 18px);
    padding: 4px 10px;
    margin: 0 8%;
    opacity: 0;
}

/* ── Shared inputs ──────────────────────────────────────────────────── */

.jr-input {
    appearance: none;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 8px;
    color: #fff;
    font-size: 14px;
    padding: 9px 12px;
    outline: none;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
    box-sizing: border-box;
}

.jr-input:focus {
    border-color: rgba(120, 180, 255, 0.8);
    box-shadow: 0 0 10px rgba(120, 180, 255, 0.25);
}

.jr-input::placeholder {
    color: rgba(255, 255, 255, 0.32);
}

/* ── Create modal ───────────────────────────────────────────────────── */

.jr-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 24;
    background: rgba(0, 0, 0, 0.72);
    backdrop-filter: blur(6px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 32px;
}

.jr-modal {
    width: min(640px, 100%);
    max-height: 86vh;
    overflow-y: auto;
    background: #0b0b0e;
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 14px;
    box-shadow: 0 24px 80px rgba(0, 0, 0, 0.8), 0 0 36px rgba(120, 180, 255, 0.10);
    padding: 26px 28px 22px;
    box-sizing: border-box;
}

.jr-modal__title {
    margin: 0 0 18px;
    font-family: 'SF Pro', system-ui, sans-serif;
    font-size: 20px;
    font-weight: 600;
    letter-spacing: 0.01em;
    text-transform: lowercase;
    color: #fff;
}

.jr-field {
    display: block;
    margin-bottom: 16px;
}

.jr-field__label {
    display: block;
    margin-bottom: 7px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.45);
}

.jr-field .jr-input {
    width: 100%;
}

/* globaltags chip box */

.jr-tagbox {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    align-items: center;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 8px;
    padding: 6px 8px;
    cursor: text;
    min-height: 40px;
    box-sizing: border-box;
}

.jr-tagbox:focus-within {
    border-color: rgba(120, 180, 255, 0.8);
    box-shadow: 0 0 10px rgba(120, 180, 255, 0.25);
}

.jr-tag {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    background: rgba(120, 180, 255, 0.16);
    border: 1px solid rgba(120, 180, 255, 0.45);
    border-radius: 999px;
    color: #cfe3ff;
    font-size: 12.5px;
    padding: 3px 6px 3px 10px;
    white-space: nowrap;
}

.jr-tag__x {
    appearance: none;
    border: 0;
    background: none;
    color: rgba(207, 227, 255, 0.7);
    font-size: 14px;
    line-height: 1;
    cursor: pointer;
    padding: 0 3px;
}

.jr-tag__x:hover {
    color: #fff;
}

.jr-tagbox__input {
    appearance: none;
    flex: 1;
    min-width: 120px;
    background: none;
    border: 0;
    outline: none;
    color: #fff;
    font-size: 14px;
    padding: 4px 2px;
}

.jr-tagbox__input::placeholder {
    color: rgba(255, 255, 255, 0.32);
}

/* cover / page pickers */

.jr-picker {
    display: flex;
    gap: 10px;
    overflow-x: auto;
    padding: 4px 2px 8px;
    scrollbar-width: thin;
}

.jr-swatch {
    appearance: none;
    flex: 0 0 auto;
    padding: 0;
    border: 2px solid transparent;
    border-radius: 8px;
    background: none;
    cursor: pointer;
    transition: border-color 0.12s ease, box-shadow 0.12s ease, transform 0.12s ease;
}

.jr-swatch img {
    display: block;
    border-radius: 6px;
    object-fit: cover;
    width: 74px;
    height: 98px;
}

.jr-picker--pages .jr-swatch img {
    width: 74px;
    height: 98px;
}

.jr-swatch:hover {
    transform: translateY(-2px);
}

.jr-swatch.is-selected {
    border-color: rgba(120, 180, 255, 0.95);
    box-shadow: 0 0 12px rgba(120, 180, 255, 0.5);
}

/* modal actions */

.jr-modal__actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 6px;
}

.jr-btn {
    appearance: none;
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.05);
    color: rgba(255, 255, 255, 0.85);
    border-radius: var(--ui-border-radius);
    font-size: 13.5px;
    opacity: .6;
    text-transform: lowercase;
    padding: 1px 1px;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
}

.jr-btn:hover:not(:disabled) {
    opacity: 1;
    border-color: rgba(255, 255, 255, 0.45);
    background: rgba(255, 255, 255, 0.1);
}

.jr-btn--primary {
    background: rgba(70, 130, 255, 0.22);
    border-color: rgba(120, 180, 255, 0.7);
    color: #eaf3ff;
}

.jr-btn--primary:hover:not(:disabled) {
    background: rgba(70, 130, 255, 0.36);
    box-shadow: 0 0 14px rgba(120, 180, 255, 0.35);
}

.jr-btn:disabled {
    opacity: 0.45;
    cursor: default;
}

/* ── Template picker (create modal) ─────────────────────────────────── */

.jr-templates {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(168px, 1fr));
    gap: 10px;
}

.jr-template {
    appearance: none;
    display: flex;
    flex-direction: column;
    gap: 4px;
    text-align: left;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 10px;
    padding: 12px 14px;
    cursor: pointer;
    transition: border-color 0.13s ease, box-shadow 0.13s ease, background 0.13s ease;
}

.jr-template:hover {
    border-color: rgba(255, 255, 255, 0.35);
}

.jr-template.is-selected {
    border-color: rgba(120, 180, 255, 0.95);
    background: rgba(70, 130, 255, 0.12);
    box-shadow: 0 0 12px rgba(120, 180, 255, 0.35);
}

.jr-template__name {
    font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
    font-size: 15px;
    color: #fff;
}

.jr-template__tagline {
    font-size: 11.5px;
    line-height: 1.35;
    color: rgba(255, 255, 255, 0.55);
}

.jr-template__count {
    margin-top: 2px;
    font-size: 10.5px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(120, 180, 255, 0.75);
}

/* ── Import section (create modal) ──────────────────────────────────── */

.jr-import {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

/* The real input stays in the layout for a11y but is never seen; the
   styled button drives it. */

.jr-import__file {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
    border: 0;
}

.jr-import__head {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.jr-import__hint {
    font-size: 11.5px;
    line-height: 1.35;
    color: rgba(255, 255, 255, 0.45);
}

.jr-import__list {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.jr-import__row {
    display: flex;
    align-items: center;
    gap: 10px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 10px;
    padding: 8px 10px;
}

.jr-import__meta {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
    flex: 1;
}

.jr-import__name {
    font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
    font-size: 13px;
    color: #fff;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.jr-import__preview {
    font-size: 10.5px;
    letter-spacing: 0.04em;
    color: rgba(120, 180, 255, 0.75);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* Segmented per-file destination control. */

.jr-import__targets {
    display: flex;
    flex-shrink: 0;
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 8px;
    overflow: hidden;
}

.jr-import__target {
    appearance: none;
    background: transparent;
    border: 0;
    border-right: 1px solid rgba(255, 255, 255, 0.12);
    color: rgba(255, 255, 255, 0.6);
    font-size: 11px;
    letter-spacing: 0.04em;
    padding: 6px 10px;
    cursor: pointer;
    transition: background 0.13s ease, color 0.13s ease;
}

.jr-import__target:last-child {
    border-right: 0;
}

.jr-import__target:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #fff;
}

.jr-import__target.is-selected {
    background: rgba(70, 130, 255, 0.22);
    color: #fff;
    box-shadow: inset 0 0 10px rgba(120, 180, 255, 0.25);
}

.jr-import__drop {
    appearance: none;
    flex-shrink: 0;
    background: transparent;
    border: 0;
    color: rgba(255, 255, 255, 0.4);
    font-size: 16px;
    line-height: 1;
    padding: 2px 4px;
    cursor: pointer;
    transition: color 0.13s ease;
}

.jr-import__drop:hover {
    color: #ff8a8a;
}

.jr-import__skipped {
    margin: 0;
    font-size: 11px;
    line-height: 1.4;
    color: rgba(255, 190, 120, 0.8);
}

/* ── Journal viewer — open book ─────────────────────────────────────── */

.jv-root {
    position: relative;
    width: 100%;
    height: 100%;
    /* Contain the backdrop's negative z-index so it can't slip behind
     the app shell. */
    isolation: isolate;
    /* Hidden, not auto: pages must END at the paper edge (overflow rolls
     over to the next page of the group) instead of growing the book. */
    overflow: hidden;
    padding: 10px 16px 12px;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.jv-root::-webkit-scrollbar {
    display: none;
}

/* Full-window backdrop: the journal's own cover, heavily blurred and
   darkened. Oversized by the blur radius so the soft edges never show. */

.jv-backdrop {
    position: absolute;
    inset: 0px;
    z-index: -1;
    background-size: cover;
    background-position: center;
    filter: blur(10px) brightness(0.7) saturate(1);
    pointer-events: none;
}

/* Extra darkening + vignette so page content keeps contrast. */

.jv-backdrop::after {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at center, rgba(0, 0, 0, 0.25) 0%, rgba(0, 0, 0, 0.6) 100%), rgba(0, 0, 0, 0.25);
}

.jv-topbar {
    display: flex;
    align-items: center;
    gap: 12px;
}

/* Compact top-row buttons: the topbar is pure chrome, and every vertical
   px it gives up goes straight to the book's scale factor. */

.jv-topbar .jr-btn {
    padding: 5px 13px;
    font-size: 13px;
}

.jv-title {
    margin: 0;
    flex: 1;
    font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
    font-size: 22px;
    font-weight: 400;
    color: #fff;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.jv-pageno {
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 13px;
    color: rgba(255, 255, 255, 0.45);
}

.jv-book {
    display: flex;
    align-items: stretch;
    gap: 0px;
    flex: 1;
    min-height: 0;
    /* Positioning context for the overlaid nav arrows. The floating
     toolbar is a direct child of .jv-root so it can cross the panel. */
    position: relative;
}

/* Nav arrows float over the port's letterbox instead of reserving a
   column of layout width — the book gets the full row. */

.jv-nav {
    appearance: none;
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
    z-index: 5;
    width: 18px;
    height: 72%;
    border-radius: 10px 0 0 10px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: rgba(255, 255, 255, 0.04);
    color: rgba(255, 255, 255, 0.8);
    font-size: 18px;
    cursor: pointer;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.jv-nav:hover:not(:disabled) {
    border-color: rgba(255, 255, 255, 0.4);
    box-shadow: 0 0 12px rgba(255, 255, 255, 0.15);
}

.jv-nav:disabled {
    opacity: 0.25;
    cursor: default;
}

.jv-nav.right {
    border-radius: 0 10px 10px 0;
    left: auto;
    right: 0;
}

/* Fixed-geometry book: pages keep one logical size (set inline from
   PAGE_W/PAGE_H) and the whole book scales to fit the port. Because the
   scale is a transform, it never changes layout — so line breaks are
   identical at every window size and resolution. */

.jv-bookport {
    flex: 1;
    min-width: 0;
    min-height: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}

.jv-bookscale {
    flex: none;
    position: relative;
    transform-origin: center center;
}

.jv-spread {
    width: 100%;
    height: 100%;
    display: grid;
    grid-template-columns: 1fr 3px 1fr;
    background: #0b0b0e;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    box-shadow: 0 22px 70px rgba(0, 0, 0, 0.7);
    overflow: hidden;
    box-sizing: border-box;
}

/* Narrow (<800px panel) or a lone slot: one page at a time, no spine. */

.jv-spread--single {
    grid-template-columns: 1fr;
}

/* ── Seamed scroll stack ────────────────────────────────────────────
   A scroll-toggled folio: its pages stacked in one slot, scrolled
   vertically. The scrollbar is hidden so page width matches paginated
   mode exactly — line breaks must not differ between the two views. */

.jv-scrollstack {
    min-width: 0;
    min-height: 0;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
}

.jv-scrollstack::-webkit-scrollbar {
    display: none;
}

.jv-scrollstack__page {
    flex: none;
}

.jv-scrollstack__page>.jv-page {
    height: 100%;
    box-sizing: border-box;
}

/* Unmounted pages in the stack: blank paper keeps the scroll honest. */

.jv-scrollstack__ghost {
    flex: none;
}

/* Bottom-bar toggle between paginated and scrolled reading */

.jvb__scrolltoggle {
    appearance: none;
    padding: 6px 14px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.22);
    background: rgba(0, 0, 0, 0.5);
    color: rgba(255, 255, 255, 0.8);
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 12px;
    cursor: pointer;
    white-space: nowrap;
    transition: border-color 0.15s ease, box-shadow 0.15s ease, color 0.15s ease;
}

.jvb__scrolltoggle:hover {
    border-color: rgba(150, 200, 255, 0.8);
    color: #fff;
}

.jvb__scrolltoggle.is-on {
    border-color: rgba(120, 180, 255, 0.6);
    box-shadow: 0 0 10px rgba(120, 180, 255, 0.25);
    color: #eaf3ff;
}

.jv-root.is-narrow {
    padding: 8px 10px 12px;
}

.jv-root.is-narrow .jvs-toggle {
    display: none;
}

.jv-root.is-narrow .jv-topbar {
    gap: 10px;
}

.jv-root.is-narrow .jv-pageno {
    display: none;
}

.jv-root.is-narrow .jvb__tagswrap {
    width: 90px;
}

.jv-root.is-narrow .jvb__tags.is-expanded {
    width: 260px;
}

.jv-spine {
    background: linear-gradient(to right, rgba(0, 0, 0, 0.55), rgba(255, 255, 255, 0.06), rgba(0, 0, 0, 0.55));
}

.jv-page {
    position: relative;
    background-size: 100% 100%;
    background-position: center;
    /* Slim mat: just enough page art peeks around the paper to keep the
     texture readable without spending ~7% of the page on framing. */
    padding: 11px;
    box-sizing: border-box;
    display: flex;
}

.jv-page--empty {
    background: linear-gradient(160deg, #131318, #08080a);
}

/* Translucent paper panel keeps text readable over any page art */

.jv-page__paper {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    background: rgba(8, 8, 12, 0.78);
    backdrop-filter: blur(5px);
    border: 1px solid rgba(255, 255, 255, 0.20);
    border-radius: 10px;
    padding: 12px 14px;
    overflow-y: auto;
}

.jv-page__paper::-webkit-scrollbar {
    width: 6px;
}

.jv-page__paper::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 3px;
}

/* Notes pages have a hard end: content past the edge rolls to the next
   page in the group rather than scrolling/stretching the texture. */

.jv-page__paper--fixed,
.jv-page__paper--fixed .jv-page__body {
    overflow: hidden;
}

.jv-page {
    min-height: 0;
    min-width: 0;
}

.jv-page__head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.12);
    padding-bottom: 6px;
    margin-bottom: 9px;
}

.jv-page__head h3 {
    margin: 0;
    font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
    font-size: 17px;
    font-weight: 500;
    color: #fff;
}

/* Editable folio title: dressed as the plain h3 until it's touched. */

.jv-page__titleedit {
    flex: 1 1 auto;
    min-width: 0;
    margin: 0;
    padding: 0 2px;
    border: 0;
    border-radius: 3px;
    background: transparent;
    outline: none;
    font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
    font-size: 17px;
    font-weight: 500;
    color: #fff;
}

.jv-page__titleedit::placeholder {
    color: rgba(255, 255, 255, 0.35);
}

.jv-page__titleedit:hover {
    background: rgba(255, 255, 255, 0.06);
}

.jv-page__titleedit:focus {
    background: rgba(255, 255, 255, 0.09);
}

.jv-page__type {
    font-size: 10px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: rgba(120, 180, 255, 0.7);
    white-space: nowrap;
}

.jv-page__body {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;
    color: rgba(255, 255, 255, 0.85);
    font-size: 13.5px;
    line-height: 1.5;
}

/* dashboard */

.jv-dashboard {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
    align-content: start;
}

.jv-widget {
    display: flex;
    flex-direction: column;
    gap: 3px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.10);
    border-radius: 8px;
    padding: 10px 12px;
}

.jv-widget--progress {
    grid-column: 1 / -1;
}

.jv-widget__value {
    font-family: var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif;
    font-size: 22px;
    color: #fff;
}

.jv-widget__label {
    font-size: 11px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.5);
}

.jv-widget__hint {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.35);
}

.jv-bar {
    height: 8px;
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.08);
    overflow: hidden;
}

.jv-bar__fill {
    height: 100%;
    min-width: 2px;
    border-radius: 4px;
    background: linear-gradient(90deg, rgba(120, 180, 255, 0.9), rgba(0, 220, 255, 0.85));
}

.jv-dashboard__note {
    grid-column: 1 / -1;
    margin: 4px 0 0;
    font-family: Georgia, 'Times New Roman', serif;
    font-style: italic;
    font-size: 12.5px;
    color: rgba(255, 255, 255, 0.5);
}

/* tracker */

.jv-tracker table {
    width: 100%;
    border-collapse: collapse;
    font-size: 12.5px;
}

.jv-tracker th {
    text-align: left;
    font-size: 10.5px;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(120, 180, 255, 0.75);
    border-bottom: 1px solid rgba(255, 255, 255, 0.16);
    padding: 4px 8px 6px 2px;
}

.jv-tracker td {
    border-bottom: 1px solid rgba(255, 255, 255, 0.07);
    padding: 6px 8px 6px 2px;
    color: rgba(255, 255, 255, 0.85);
}

.jv-tracker__draft input {
    width: 100%;
    box-sizing: border-box;
    background: none;
    border: 0;
    border-bottom: 1px dashed rgba(255, 255, 255, 0.2);
    outline: none;
    color: #fff;
    font-size: 12.5px;
    padding: 3px 0;
}

.jv-tracker__draft input::placeholder {
    color: rgba(255, 255, 255, 0.25);
}

.jv-minibtn {
    appearance: none;
    margin-top: 10px;
    align-self: flex-start;
    background: none;
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 6px;
    color: rgba(255, 255, 255, 0.6);
    font-size: 11.5px;
    text-transform: lowercase;
    padding: 4px 10px;
    cursor: pointer;
}

.jv-minibtn:hover {
    border-color: rgba(255, 255, 255, 0.4);
    color: #fff;
}

/* todo */

.jv-todo {
    display: flex;
    flex-direction: column;
    gap: 7px;
}

.jv-todo__item {
    display: flex;
    align-items: flex-start;
    gap: 9px;
    cursor: pointer;
}

.jv-todo__item input {
    margin-top: 3px;
    accent-color: rgb(120, 180, 255);
}

.jv-todo__item.is-done span {
    text-decoration: line-through;
    color: rgba(255, 255, 255, 0.35);
}

.jv-todo__add input {
    width: 100%;
    box-sizing: border-box;
    background: none;
    border: 0;
    border-bottom: 1px dashed rgba(255, 255, 255, 0.2);
    outline: none;
    color: #fff;
    font-size: 13px;
    padding: 5px 0;
}

.jv-todo__add input::placeholder {
    color: rgba(255, 255, 255, 0.25);
}

/* prompts */

.jv-prompts__intro {
    margin: 0 0 10px;
    font-family: Georgia, 'Times New Roman', serif;
    font-style: italic;
    color: rgba(255, 255, 255, 0.5);
    font-size: 12.5px;
}

.jv-prompts ol {
    margin: 0;
    padding-left: 20px;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.jv-prompts li {
    padding-bottom: 14px;
    border-bottom: 1px dashed rgba(255, 255, 255, 0.12);
}

/* notes */

.jv-notes {
    flex: 1;
    width: 100%;
    box-sizing: border-box;
    resize: none;
    background: none;
    border: 0;
    outline: none;
    color: rgba(255, 255, 255, 0.88);
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 14px;
    line-height: 1.65;
    min-height: 200px;
}

.jv-notes::placeholder {
    color: rgba(255, 255, 255, 0.25);
}

/* table of contents rail */

.jv-toc {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 8px;
}

.jv-toc__item {
    appearance: none;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 999px;
    color: rgba(255, 255, 255, 0.6);
    font-size: 12px;
    padding: 5px 13px;
    cursor: pointer;
    transition: border-color 0.13s ease, color 0.13s ease, box-shadow 0.13s ease;
}

.jv-toc__item:hover {
    border-color: rgba(255, 255, 255, 0.4);
    color: #fff;
}

.jv-toc__item.is-current {
    border-color: rgba(120, 180, 255, 0.8);
    color: #eaf3ff;
    box-shadow: 0 0 10px rgba(120, 180, 255, 0.3);
}

/* ── Interactive widget bits ────────────────────────────────────────── */

.jv-live {
    display: inline-block;
    margin-left: 7px;
    font-style: normal;
    font-size: 8.5px;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    color: rgba(0, 220, 180, 0.9);
    border: 1px solid rgba(0, 220, 180, 0.4);
    border-radius: 999px;
    padding: 1px 6px;
    vertical-align: middle;
}

.jv-editable {
    appearance: none;
    background: none;
    border: 0;
    padding: 0;
    margin: 0;
    font: inherit;
    color: inherit;
    cursor: pointer;
    border-bottom: 1px dashed rgba(120, 180, 255, 0.55);
    transition: border-color 0.13s ease, color 0.13s ease;
}

.jv-editable:hover {
    color: #eaf3ff;
    border-bottom-color: rgba(120, 180, 255, 1);
}

.jv-editable__input {
    background: rgba(255, 255, 255, 0.07);
    border: 1px solid rgba(120, 180, 255, 0.7);
    border-radius: 5px;
    outline: none;
    color: #fff;
    font: inherit;
    padding: 1px 6px;
    width: 90px;
    box-sizing: border-box;
}

.jv-widget--progress.is-over .jv-bar__fill {
    background: linear-gradient(90deg, rgba(255, 140, 90, 0.95), rgba(255, 80, 80, 0.9));
}

/* shared delete button */

.jv-x {
    appearance: none;
    background: none;
    border: 0;
    color: rgba(255, 255, 255, 0.25);
    font-size: 15px;
    line-height: 1;
    padding: 2px 5px;
    cursor: pointer;
    border-radius: 4px;
    transition: color 0.12s ease;
}

.jv-x:hover {
    color: rgba(255, 110, 110, 0.95);
}

/* tracker editing */

.jv-tracker__rowctl {
    width: 26px;
    border-bottom: 0 !important;
}

.jv-tracker tbody tr .jv-x {
    opacity: 0;
}

.jv-tracker tbody tr:hover .jv-x {
    opacity: 1;
}

.jv-cell {
    cursor: text;
}

.jv-cell:hover {
    background: rgba(120, 180, 255, 0.07);
}

.jv-tracker td input {
    width: 100%;
    box-sizing: border-box;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(120, 180, 255, 0.6);
    border-radius: 4px;
    outline: none;
    color: #fff;
    font-size: 12.5px;
    padding: 3px 5px;
}

.jv-tracker__draft input {
    background: none;
    border: 0;
    border-bottom: 1px dashed rgba(255, 255, 255, 0.2);
    border-radius: 0;
    padding: 3px 0;
}

/* todo editing */

.jv-todo__item {
    align-items: center;
}

.jv-todo__item .jv-x {
    opacity: 0;
    margin-left: auto;
}

.jv-todo__item:hover .jv-x {
    opacity: 1;
}

.jv-todo__text {
    cursor: text;
}

.jv-todo__editinput {
    flex: 1;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(120, 180, 255, 0.6);
    border-radius: 4px;
    outline: none;
    color: #fff;
    font-size: 13px;
    padding: 3px 6px;
}

/* prompt answers */

.jv-prompts__q {
    display: block;
    margin-bottom: 7px;
}

.jv-prompts__answer {
    width: 100%;
    box-sizing: border-box;
    resize: vertical;
    min-height: 44px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 7px;
    outline: none;
    color: rgba(255, 255, 255, 0.88);
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 13px;
    line-height: 1.55;
    padding: 8px 10px;
    transition: border-color 0.13s ease;
}

.jv-prompts__answer:focus {
    border-color: rgba(120, 180, 255, 0.7);
}

.jv-prompts__answer::placeholder {
    color: rgba(255, 255, 255, 0.22);
}

/* ── À la carte page picker ─────────────────────────────────────────── */

.jv-pagepick {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.jv-pagepick__item {
    appearance: none;
    display: flex;
    flex-direction: column;
    gap: 2px;
    text-align: left;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 8px;
    padding: 8px 12px;
    cursor: pointer;
    transition: border-color 0.13s ease, box-shadow 0.13s ease;
}

.jv-pagepick__item:hover {
    border-color: rgba(120, 180, 255, 0.85);
    box-shadow: 0 0 10px rgba(120, 180, 255, 0.3);
}

.jv-pagepick__name {
    font-size: 13px;
    color: #fff;
}

.jv-pagepick__from {
    font-size: 9.5px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(120, 180, 255, 0.7);
}

/* page delete sits in the header type chip */

.jv-page__type .jv-x {
    margin-left: 4px;
    font-size: 13px;
}

/* ── Rich text notes (TipTap) ───────────────────────────────────────── */

.rt-host {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;
    position: relative;
}

/* Editor toolbar — Aida's design. Docked by default as a single-row
   strip at the top of the panel (--docked below); double-clicking the
   handle tears it off into this draggable pill and docks it back. The
   pill is a direct child of .jv-root, so dragging spans the whole
   panel; JS keeps the untouched default centered over the book as the
   sidebar or panel resizes. */

.rt-toolbar {
    position: absolute;
    top: 12px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 10;
    display: flex;
    flex-direction: column;
    background: rgba(38, 38, 44, 0.78);
    backdrop-filter: blur(14px);
    border: 1px solid rgba(255, 255, 255, 0.13);
    border-radius: 18px;
    box-shadow: 0 10px 36px rgba(0, 0, 0, 0.55);
    padding: 4px 8px;
    user-select: none;
}

/* The float docks the same editor controls into a reveal tray beneath
   its header. The tray owns horizontal overflow, so the toolbar keeps
   its natural width and never drops or hides a control. */

.rt-toolbar--tray {
    position: relative;
    inset: auto;
    left: auto;
    top: auto;
    transform: none;
    z-index: 1;
    width: max-content;
    min-width: max-content;
    max-width: none;
    flex: none;
    border-radius: 16px;
    box-shadow: 0 7px 22px rgba(0, 0, 0, 0.38);
}

.rt-toolbar--tray .rt-row {
    min-width: max-content;
}

.rt-toolbar--tray .rt-btn--tray-dismiss {
    cursor: pointer;
}

.rt-toolbar--tray .rt-btn--tray-dismiss:active {
    cursor: pointer;
}

/* Docked strip — the default. Sits in flow at the top of .jv-root with
   every tool in the one row; when the panel is narrower than the row,
   the row scrolls horizontally so no control ever drops or hides. */

.rt-toolbar--docked {
    position: relative;
    inset: auto;
    left: auto;
    top: auto;
    transform: none;
    flex: none;
    width: 100%;
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
    border-radius: 14px;
    box-shadow: 0 7px 22px rgba(0, 0, 0, 0.38);
}

.rt-toolbar--docked .rt-btn--dock-handle {
    cursor: pointer;
}

.rt-toolbar--docked .rt-btn--dock-handle:active {
    cursor: pointer;
}

.rt-dockscroll {
    width: 100%;
    max-width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    scrollbar-width: thin;
    scrollbar-color: rgba(255, 255, 255, 0.28) transparent;
}

.rt-dockscroll::-webkit-scrollbar {
    height: 5px;
}

.rt-dockscroll::-webkit-scrollbar-track {
    background: transparent;
}

.rt-dockscroll::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.24);
    border-radius: 999px;
}

.rt-dockscroll:focus-visible {
    outline: 2px solid rgba(190, 220, 255, 0.78);
    outline-offset: -2px;
    border-radius: 10px;
}

.rt-dockscroll .rt-row {
    width: max-content;
    min-width: max-content;
}

.rt-row {
    display: flex;
    align-items: center;
    gap: 2px;
}

.rt-row--secondary {
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    margin-top: 4px;
    padding-top: 4px;
}

.rt-sep {
    width: 1px;
    height: 20px;
    background: rgba(255, 255, 255, 0.14);
    margin: 0 5px;
}

.rt-btn {
    appearance: none;
    background: none;
    border: 0;
    border-radius: 9px;
    width: 32px;
    height: 32px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: rgba(255, 255, 255, 0.82);
    cursor: pointer;
    transition: background 0.12s ease, color 0.12s ease, box-shadow 0.12s ease;
}

.rt-btn svg {
    width: 17px;
    height: 17px;
}

.rt-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

/* active = soft white gradient block, dark glyph (per Aida's mockup) */

.rt-btn.is-active {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(255, 255, 255, 0.62));
    color: #16161a;
    box-shadow: 0 1px 6px rgba(0, 0, 0, 0.35);
}

.rt-btn.is-active:hover {
    background: linear-gradient(180deg, #fff, rgba(255, 255, 255, 0.75));
    color: #000;
}

.rt-btn--drag {
    cursor: grab;
    color: rgba(255, 255, 255, 0.45);
}

.rt-btn--drag:active {
    cursor: grabbing;
}

.rt-glyph {
    font-size: 15px;
    line-height: 1;
}

.rt-glyph--h {
    font-size: 13px;
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
}

.rt-glyph--h sub {
    font-size: 9px;
}

.rt-chevron {
    display: inline-flex;
    transition: transform 0.18s ease;
}

.rt-chevron.is-open {
    transform: rotate(180deg);
}

.rt-family {
    appearance: none;
    background: rgba(255, 255, 255, 0.07);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 8px;
    color: rgba(255, 255, 255, 0.85);
    font-size: 12.5px;
    padding: 4px 8px;
    max-width: 110px;
    outline: none;
    cursor: pointer;
}

.rt-family option {
    background: #1a1a20;
}

.rt-size {
    appearance: none;
    width: 44px;
    background: rgba(255, 255, 255, 0.07);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 8px;
    color: rgba(255, 255, 255, 0.85);
    font-size: 12.5px;
    padding: 4px 6px;
    margin-left: 4px;
    outline: none;
    box-sizing: border-box;
}

.rt-size::-webkit-inner-spin-button {
    display: none;
}

.rt-family:focus,
.rt-size:focus {
    border-color: rgba(120, 180, 255, 0.7);
}

.rt-lineheight {
    max-width: 96px;
}

/* link panel — Text/URL rows between the toolbar rows */

.rt-linkpanel {
    display: flex;
    flex-direction: column;
    gap: 6px;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    margin-top: 4px;
    padding: 8px 2px 4px;
    min-width: 340px;
}

.rt-linkrow {
    display: flex;
    align-items: center;
    gap: 10px;
}

.rt-linklabel {
    width: 34px;
    flex: 0 0 auto;
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 13px;
    color: rgba(255, 255, 255, 0.45);
}

.rt-linkinput {
    flex: 1;
    appearance: none;
    background: rgba(255, 255, 255, 0.07);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 7px;
    color: #fff;
    font-size: 12.5px;
    padding: 6px 9px;
    outline: none;
}

.rt-linkinput:focus {
    border-color: rgba(255, 255, 255, 0.4);
}

.rt-linkinput::placeholder {
    color: rgba(255, 255, 255, 0.28);
    font-style: italic;
}

/* prose area */

.rt-prose {
    flex: 1;
    min-height: 200px;
    display: flex;
    flex-direction: column;
}

.rt-prose .ProseMirror {
    flex: 1;
    outline: none;
    color: rgba(255, 255, 255, 0.88);
    /* Journal-tunable type (typography panel writes these vars on .jv-root) */
    font-family: var(--jv-body-font, Georgia, 'Times New Roman', serif);
    font-size: var(--jv-body-size, 14px);
    line-height: var(--jv-lh, 1.65);
    white-space: pre-wrap;
}

.rt-prose .ProseMirror p {
    margin: 0 0 0.6em;
}

.rt-prose .ProseMirror img[data-journal-image] {
    display: block;
    width: auto;
    max-width: 100%;
    max-height: 246px;
    margin: 0.75em auto;
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 7px;
    object-fit: contain;
    background: rgba(0, 0, 0, 0.16);
    box-shadow: 0 5px 18px rgba(0, 0, 0, 0.25);
}

.jv-attachment-modal {
    width: min(490px, 100%);
}

.jv-attachment-modal__copy {
    margin: -4px 0 18px;
    color: rgba(255, 255, 255, 0.66);
    font-size: 13px;
    line-height: 1.55;
}

.jv-attachment-modal__copy code {
    padding: 1px 4px;
    border-radius: 4px;
    background: rgba(120, 180, 255, 0.15);
    color: rgba(205, 226, 255, 0.96);
}

.rt-prose .ProseMirror h1,
.rt-prose .ProseMirror h2,
.rt-prose .ProseMirror h3 {
    font-weight: 500;
    color: #fff;
    margin: 0.8em 0 0.35em;
    line-height: 1.25;
}

.rt-prose .ProseMirror h1 {
    font-family: var(--jv-h1-font, var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif);
    font-size: 22px;
}

.rt-prose .ProseMirror h2 {
    font-family: var(--jv-h2-font, var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif);
    font-size: 18px;
}

.rt-prose .ProseMirror h3 {
    font-family: var(--jv-h3-font, var(--ui-font-main), Jost, 'SF Pro', system-ui, sans-serif);
    font-size: 15.5px;
}

.rt-prose .ProseMirror blockquote {
    margin: 0.6em 0;
    padding: 2px 0 2px 14px;
    border-left: 2px solid rgba(120, 180, 255, 0.55);
    color: rgba(255, 255, 255, 0.62);
    font-style: italic;
}

.rt-prose .ProseMirror ul,
.rt-prose .ProseMirror ol {
    margin: 0.4em 0;
    padding-left: 22px;
}

.rt-prose .ProseMirror code {
    background: rgba(255, 255, 255, 0.09);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 4px;
    font-family: 'SF Mono', Menlo, monospace;
    font-size: 12px;
    padding: 1px 5px;
}

.rt-prose .ProseMirror a {
    color: rgb(140, 190, 255);
    text-decoration: underline;
    text-decoration-color: rgba(140, 190, 255, 0.45);
}

/* placeholder */

.rt-prose .ProseMirror p.is-editor-empty:first-child::before {
    content: attr(data-placeholder);
    float: left;
    height: 0;
    pointer-events: none;
    color: rgba(255, 255, 255, 0.25);
    font-style: italic;
}

/* ── Typography modal ───────────────────────────────────────────────── */

.jv-typo {
    width: min(440px, 100%);
}

.jv-typo select.jr-input {
    width: 100%;
    cursor: pointer;
}

.jv-typo select.jr-input option,
.jv-typo select.jr-input optgroup {
    background: #1a1a20;
}

.jv-typo__pair {
    display: flex;
    gap: 12px;
}

.jv-typo__pair .jr-field {
    flex: 1;
}

.jv-typo__hint {
    margin: 2px 0 12px;
    font-size: 12px;
    color: rgba(255, 255, 255, 0.4);
}

/* ── Journal viewer — sidebar + bottom bar ──────────────────────────────
   The screenshot UX: a collapsible left rail (search, pagegroup jumps,
   linked project files) beside the book, and a bottom strip with the
   active pagegroup chip, in-group page jumper, and the group tag strip. */

.jv-main {
    flex: 1;
    display: flex;
    align-items: stretch;
    gap: 8px;
    min-height: 0;
}

.jv-center {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 8px;
    min-width: 0;
    min-height: 0;
}

/* sidebar */

.jvs {
    width: 210px;
    flex: none;
    display: flex;
    flex-direction: column;
    border: 1px solid rgba(255, 255, 255, 0.10);
    border-radius: 12px;
    background: rgba(0, 0, 0, 0.38);
    overflow: hidden;
    transition: width 0.18s ease, opacity 0.18s ease, border-color 0.18s ease;
}

.jvs.is-closed {
    width: 0;
    opacity: 0;
    border-color: transparent;
    pointer-events: none;
}

.jvs__top {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 12px 10px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.jvs__top::-webkit-scrollbar {
    width: 6px;
}

.jvs__top::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 3px;
}

.jvs__search {
    appearance: none;
    width: 100%;
    box-sizing: border-box;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.14);
    border-radius: 9px;
    padding: 8px 12px;
    color: #fff;
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 13px;
    outline: none;
}

.jvs__search::placeholder {
    color: rgba(255, 255, 255, 0.3);
}

.jvs__search:focus {
    border-color: rgba(120, 180, 255, 0.5);
}

.jvs__groups {
    display: flex;
    flex-direction: column;
    gap: 12px;
    align-items: stretch;
}

/* pill buttons, right-aligned label, soft blue glow — like the mock */

.jvs__group {
    appearance: none;
    text-align: right;
    padding: 8px 16px;
    border-radius: var(--ui-border-radius);
    border: 1px solid rgba(120, 180, 255, 0.45);
    background: rgba(0, 0, 0, 0.5);
    box-shadow: 0 0 10px rgba(120, 180, 255, 0.18);
    color: #fff;
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.jvs__group:hover {
    border-color: rgba(150, 200, 255, 0.8);
    box-shadow: 0 0 14px rgba(120, 180, 255, 0.35);
}

.jvs__group.is-current {
    border-color: rgba(150, 200, 255, 0.9);
    box-shadow: 0 0 16px rgba(120, 180, 255, 0.45);
}

/* linked project files */

.jvs__files {
    flex: none;
    max-height: 45%;
    overflow-y: auto;
    border-top: 1px solid rgba(255, 255, 255, 0.10);
    padding: 12px 14px 16px;
}

.jvs__files::-webkit-scrollbar {
    width: 6px;
}

.jvs__files::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.15);
    border-radius: 3px;
}

.jvs__filehead {
    margin: 0 0 10px;
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 15px;
    font-weight: 400;
    color: rgba(255, 255, 255, 0.35);
}

.jvs__proj {
    margin-bottom: 12px;
}

.jvs__projname {
    display: block;
    text-align: right;
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 14px;
    font-weight: 600;
    color: #fff;
    margin-bottom: 6px;
}

.jvs__filerow {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
}

.jvs__file {
    appearance: none;
    background: none;
    border: none;
    padding: 4px 0;
    max-width: 100%;
    color: rgba(255, 255, 255, 0.75);
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 13px;
    cursor: pointer;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.jvs__file:hover {
    color: #fff;
    text-decoration: underline;
}

.jvs__dup {
    color: #ff5d76;
    font-size: 12px;
    font-style: italic;
    margin-top: -2px;
}

.jvs__hint {
    margin: 0;
    font-size: 12px;
    line-height: 1.45;
    color: rgba(255, 255, 255, 0.35);
}

/* slim collapse handle between sidebar and book */

.jvs-toggle {
    appearance: none;
    flex: none;
    align-self: first baseline;
    width: 18px;
    height: 56px;
    border-radius: 9px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.04);
    color: rgba(255, 255, 255, 0.6);
    font-size: 14px;
    cursor: pointer;
    padding: 0;
}

.jvs-toggle:hover {
    border-color: rgba(255, 255, 255, 0.35);
    color: #fff;
}

/* bottom bar */

.jvb {
    flex: none;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 0 0px;
}

.jvb__chip {
    padding: 6px 18px;
    border-radius: 999px;
    border: 1px solid rgba(120, 180, 255, 0.45);
    background: rgba(0, 0, 0, 0.5);
    box-shadow: 0 0 10px rgba(120, 180, 255, 0.15);
    color: #fff;
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 13px;
    font-weight: 600;
    white-space: nowrap;
}

.jvb__pageno {
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 14px;
    color: rgba(255, 255, 255, 0.55);
    white-space: nowrap;
}

.jvb__pageinput {
    appearance: none;
    width: 34px;
    text-align: center;
    background: rgba(255, 255, 255, 0.07);
    border: 1px solid rgba(255, 255, 255, 0.16);
    border-radius: 6px;
    padding: 4px 2px;
    color: #fff;
    font-family: Georgia, serif;
    font-size: 13px;
    outline: none;
}

.jvb__pageinput:focus {
    border-color: rgba(120, 180, 255, 0.5);
}

.jvb__tagswrap {
    position: relative;
    flex: none;
    width: 130px;
    height: 30px;
}

.jvb__tags {
    position: absolute;
    top: 0;
    left: 0;
    width: 130px;
    display: flex;
    align-items: center;
    gap: 6px;
    overflow: hidden;
    border: 1px solid rgba(120, 180, 255, 0.35);
    border-radius: 999px;
    padding: 5px 14px;
    background: rgba(0, 0, 0, 0.4);
    transition: all 0.3s ease;
    z-index: 2;
}

.jvb__tags.is-expanded {
    padding: 5px 20px;
    overflow-x: auto;
    width: 200px;
    background: black;
    border: 1px solid rgba(120, 180, 255, 1);
    transform: scale(1.4);
}

.jvb__tags.is-expanded::placeholder {
    color: white;
}

.jvb__tags::-webkit-scrollbar {
    display: none;
}

.jvb__taginput {
    appearance: none;
    flex: 1;
    min-width: 60px;
    background: none;
    border: none;
    outline: none;
    color: #fff;
    font-family: var(--ui-font-main), Jost, system-ui, sans-serif;
    font-size: 12.5px;
}

.jvb__taginput::placeholder {
    color: rgba(255, 255, 255, 0.3);
}

/* ── Floating journal (pop-out) ──────────────────────────────────────
   A journal torn off the shelf. The outer .journal-float is the fixed
   drag frame; the inner __shell carries the position-based perspective
   chrome (transform/shadow/radii/borders) computed by
   computeFloatingShellChrome, mirroring .media-floating-panel. */

.journal-float {
    position: fixed;
    z-index: 30;
    box-sizing: border-box;
    animation: jfPopIn 0.2s ease;
}

@keyframes jfPopIn {
    from {
        opacity: 0;
        transform: scale(0);
    }

    to {
        opacity: 1;
        transform: scale(1);
    }
}

.journal-float.resizing {
    cursor: nwse-resize;
}

.journal-float.dragging {
    cursor: grabbing;
    user-select: none;
}

/* Hold-to-drag activation: a quick citrus jolt — shrink and brighten,
   then spring back and dim. Runs on the frame so it never fights the
   shell's inline perspective transform. Duration mirrors GRAB_PULSE_MS
   in JournalFloat.jsx. */

.journal-float.grab-pulse {
    animation: jfGrabPulse 0.5s infinite cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes jfGrabPulse {
    0% {
        transform: scale(1);
        filter: brightness(1);
    }

    30% {
        transform: scale(0.955);
        filter: brightness(.8) saturate(1.25);
    }

    100% {
        transform: scale(1);
        filter: brightness(1);
    }
}

.journal-float__shell {
    position: relative;
    display: flex;
    flex-direction: column;
    container-type: inline-size;
    height: 100%;
    border: none;
    min-height: 0;
    transform-style: preserve-3d;
    /* Clips .jv-backdrop to the position-driven corner radii. */
    overflow: hidden;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(0, 0, 0, 0.18)), #0b0b0e;
    backdrop-filter: blur(16px);
    /* Chrome tilt eases as it recomputes; dragging sets it per-frame. */
    transition: transform 0.35s ease;
    border-width: 4px !important;
    box-shadow: -3px 0 10px rgba(0, 0, 0, 1);
    border-radius: var(--ui-border-radius);
    corner-shape: var(--ui-corner-shape);
}

.journal-float.dragging .journal-float__shell,
.journal-float.resizing .journal-float__shell {
    transition: none;
}

.journal-float__header {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    cursor: grab;
    flex-shrink: 0;
    user-select: none;
    gap: 8px;
    height: 34px;
    min-height: 34px;
    padding: 0 12px;
    text-transform: none;
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(0, 0, 0, 0.12)), var(--layout-bg-panel-header);
    border-bottom-color: color-mix(in srgb, var(--layout-border-color) 72%, rgba(220, 196, 137, 0.55));
    border-radius: 0 !important;
}

/* The cover becomes identity chrome instead of a backdrop competing with
   the writing surface. Blur is isolated to this strip so the page below
   remains crisp and visually continuous. */

.journal-float__header::before {
    content: '';
    position: absolute;
    z-index: 0;
    inset: -18px;
    background-image: var(--journal-float-cover, none);
    background-position: center 38%;
    background-size: cover;
    filter: blur(1.5px) brightness(.8) saturate(1.25);
    transform: scale(1.1);
    pointer-events: none;
}

.journal-float__header::after {
    content: '';
    position: absolute;
    z-index: 1;
    inset: 0;
    background: linear-gradient(180deg, rgba(240, 248, 244, 0.10), rgba(7, 12, 14, 0.46)), linear-gradient(90deg, rgba(7, 12, 14, 0.62), rgba(7, 12, 14, 0.18) 52%, rgba(7, 12, 14, 0.68));
    box-shadow: inset 0 -14px 22px rgba(3, 8, 10, 0.18);
    pointer-events: none;
}

.journal-float__header>* {
    position: relative;
    z-index: 2;
}

.journal-float.dragging .journal-float__header {
    cursor: grabbing;
}

.journal-float__title {
    flex: 1 1 auto;
    min-width: 64px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: clamp(16px, 4.4cqi, 26px);
    font-weight: 400;
    line-height: 1;
    letter-spacing: 0.035em;
    text-transform: uppercase;
    color: rgba(246, 241, 234, 0.9);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.journal-float__tools {
    flex: none;
    display: flex;
    align-items: center;
    gap: 3px;
}

.journal-float__mode-btn,
.journal-float__page-turner button {
    appearance: none;
    border: 0;
    background: transparent;
    color: rgba(246, 241, 234, 0.72);
    cursor: pointer;
    transition: color 130ms cubic-bezier(0.25, 1, 0.5, 1), background 130ms cubic-bezier(0.25, 1, 0.5, 1), box-shadow 130ms cubic-bezier(0.25, 1, 0.5, 1), transform 130ms cubic-bezier(0.25, 1, 0.5, 1);
}

.journal-float__mode-btn {
    height: 40px;
    min-width: 40px;
    padding: 0 8px;
    border-radius: 9px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.journal-float__mode-btn svg {
    width: 24px;
    height: 24px;
}

.journal-float__mode-btn--format {
    gap: 3px;
    padding-inline: 8px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 23px;
}

.journal-float__mode-btn--format strong {
    font-weight: 700;
}

.journal-float__mode-btn--format em {
    font-weight: 400;
}

.journal-float__mode-btn--format span {
    text-decoration: underline;
    text-underline-offset: 3px;
}

.journal-float__mode-btn:hover:not(:disabled),
.journal-float__page-turner button:hover:not(:disabled) {
    color: rgba(255, 252, 247, 0.98);
    background: rgba(255, 255, 255, 0.08);
}

.journal-float__mode-btn:active:not(:disabled),
.journal-float__page-turner button:active:not(:disabled) {
    transform: translateY(1px);
}

.journal-float__mode-btn.is-active {
    color: #171511;
    background: linear-gradient(180deg, rgba(248, 244, 236, 0.98), rgba(214, 204, 187, 0.82));
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.32);
}

.journal-float__mode-btn:disabled,
.journal-float__page-turner button:disabled {
    opacity: 0.24;
    cursor: default;
}

.journal-float__mode-btn:focus-visible,
.journal-float__page-turner button:focus-visible,
.journal-float__window-actions .panel-header-btn:focus-visible {
    outline: 2px solid rgba(190, 220, 255, 0.95);
    outline-offset: 1px;
}

.journal-float__page-turner {
    height: 40px;
    display: inline-flex;
    align-items: center;
}

.journal-float__page-turner button {
    width: 27px;
    height: 40px;
    padding: 0;
    border-radius: 8px;
    font-family: Georgia, 'Times New Roman', serif;
    font-size: 26px;
    line-height: 1;
}

.journal-float__page-turner>span {
    width: 1px;
    height: 21px;
    background: rgba(246, 241, 234, 0.34);
}

.journal-float__window-actions {
    flex: none;
    gap: 0;
    margin-left: -2px;
}

.journal-float__window-actions .panel-header-btn {
    width: 21px;
    height: 34px;
    padding: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.journal-float__window-actions .panel-header-btn:hover {
    opacity: 1;
}

/* Header reveal rows. Their inner tracks retain max-content width so
   every tool remains reachable through native horizontal scrolling. */

.jv-float-tray {
    position: relative;
    z-index: 7;
    flex: none;
    margin: 0;
    padding: 5px 7px 4px;
    background: linear-gradient(90deg, rgba(119, 106, 69, 0.3), rgba(62, 79, 59, 0.28)), rgba(20, 25, 21, 0.94);
    border-bottom: 1px solid rgba(224, 203, 146, 0.32);
    box-shadow: 0 8px 18px rgba(0, 0, 0, 0.2);
    animation: jfTrayIn 190ms cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes jfTrayIn {
    from {
        opacity: 0;
        transform: translateY(-6px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.jv-float-tray__scroll {
    width: 100%;
    max-width: 100%;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    scrollbar-width: thin;
    scrollbar-color: rgba(240, 222, 174, 0.42) transparent;
    padding-bottom: 2px;
}

.jv-float-tray__scroll::-webkit-scrollbar {
    height: 5px;
}

.jv-float-tray__scroll::-webkit-scrollbar-track {
    background: transparent;
}

.jv-float-tray__scroll::-webkit-scrollbar-thumb {
    background: rgba(240, 222, 174, 0.35);
    border-radius: 999px;
}

.jv-float-tray__scroll:focus-visible {
    outline: 2px solid rgba(190, 220, 255, 0.78);
    outline-offset: -2px;
    border-radius: 12px;
}

.jvb--float {
    width: max-content;
    min-width: max-content;
    gap: 9px;
    padding: 1px 3px 2px;
}

.jvb--float .jr-btn {
    white-space: nowrap;
}

.journal-float__shell .jv-root.is-float {
    padding: 0;
    gap: 0;
    background: #0b0b0e;
}

.journal-float__shell .jv-root.is-float .jv-main,
.journal-float__shell .jv-root.is-float .jv-center {
    gap: 0;
}

.jv-empty-state.is-float {
    margin: auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
}

.jv-empty-state.is-float .jr-empty {
    margin: 0;
}

/* JournalView fills the shell below the header. */

.journal-float__shell .jv-root {
    flex: 1;
    height: auto;
    min-height: 0;
}

.journal-float__loading {
    margin: auto;
}

.journal-float__resize {
    position: absolute;
    right: 22px;
    bottom: 22px;
    width: 16px;
    height: 16px;
    cursor: nwse-resize;
    z-index: 6;
    border-right: 2px solid rgba(155, 220, 200, 0.4);
    border-bottom: 2px solid rgba(155, 220, 200, 0.4);
    border-radius: 0 0 6px 0;
}

.journal-float__resize:hover {
    border-color: rgba(155, 220, 200, 0.8);
}

@media (pointer: coarse) {
    .journal-float__header {
        height: 60px;
        min-height: 60px;
    }

    .journal-float__mode-btn,
    .journal-float__page-turner,
    .journal-float__page-turner button {
        height: 44px;
    }

    .journal-float__mode-btn {
        min-width: 44px;
    }
}

@media (prefers-reduced-motion: reduce) {

    .journal-float,
    .jv-float-tray {
        animation-duration: 0.01ms;
    }
}

/* ── Shelf tear-off ──────────────────────────────────────────────────
   .jr-cardwrap wraps each cover button (a button can't nest a button)
   and carries the grid sizing the card used to own. */

.jr-cardwrap {
    position: relative;
    width: 100%;
    max-width: 200px;
}

.jr-cardwrap .jr-card {
    max-width: none;
}

button.jr-card {
    background: none;
}

.jr-card__popout {
    position: absolute;
    top: -6px;
    right: -6px;
    z-index: 5;
    width: 28px;
    height: 28px;
    border: 1px solid rgba(255, 255, 255, 0.35);
    background: rgba(0, 0, 0, 0.7);
    color: #fff;
    cursor: pointer;
    font-size: 20px;
    line-height: 1;
    border-radius: var(--ui-border-radius);
    animation: jfPopIn 0.5s cubic-bezier(.3, .7, .4, 3);
    font-family: SF Pro Display;
}

.jr-card__popout:hover {
    border-color: rgba(150, 200, 255, 0.9);
    box-shadow: 0 0 10px rgba(120, 180, 255, 0.35);
}

/* ===== START OF layout.css ===== */

/* Most layout styles live in App.css. These rules define the permanent
   fullscreen host and the stable carriers that move between it and the grid. */

.tile-layout-grid {
    position: relative;
    flex: 1;
    width: 100%;
    min-height: 0;
    overflow: hidden;
}

.panel-slot-shell {
    position: relative;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    overflow: hidden;
}

.panel-husk {
    pointer-events: none;
    user-select: none;
}

.panel-husk .panel-content {
    background: transparent;
}

.panel-carrier {
    position: absolute;
    inset: 0;
    z-index: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    min-height: 0;
    overflow: hidden;
}

.fullscreen-panel-host {
    display: none;
    position: absolute;
    inset: 0;
    z-index: 14;
    min-width: 0;
    min-height: 0;
    overflow: hidden;
    background: var(--layout-bg-primary, #000);
}

.fullscreen-panel-host.is-active {
    display: block;
}

.fullscreen-panel-host>.panel-carrier {
    z-index: auto;
}

.panel-wrapper.is-fullscreen,
.panel-wrapper.is-fullscreen>.panel {
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    margin: 0;
}

.panel-wrapper.is-fullscreen .panel-header {
    cursor: default;
}

/* ===== START OF notefalls.css ===== */

/* ── Notefalls tab ─────────────────────────────────────────────────────
   Layout: a narrow date rail on the left (month/day index, today + activity
   markers), and a main column with a composer, a reverse-chron feed of
   pill-shaped entries, and a bottom session-detail drawer that slides up
   when a post is expanded. */

.nf-tab {
    position: relative;
    width: 100%;
    height: 100%;
    display: flex;
    background: #0b0b0c;
    color: rgba(255, 255, 255, 0.92);
    font-family: 'SF Pro', system-ui, sans-serif;
}

/* ── Date rail ─────────────────────────────────────────────────────── */

.nf-rail {
    user-select: none;
    -webkit-user-select: none;
}

.nf-rail {
    flex: 0 0 104px;
    overflow-y: auto;
    padding: 18px 10px 18px 18px;
    border-right: 1px solid rgba(255, 255, 255, 0.07);
    scrollbar-width: none;
}

.nf-rail::-webkit-scrollbar {
    display: none;
}

.nf-rail__group {
    display: flex;
    flex-direction: column;
}

.nf-rail__month {
    margin: 14px 0 6px;
    font-size: 12px;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.32);
}

.nf-rail__group:first-child .nf-rail__month {
    margin-top: 0;
}

.nf-rail__day {
    appearance: none;
    -webkit-appearance: none;
    background: none;
    border: 0;
    border-radius: 8px;
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    padding: 3px 8px;
    margin: 1px 0;
    color: rgba(255, 255, 255, 0.55);
    font-size: 13px;
    cursor: pointer;
    position: relative;
    transition: background 0.12s ease, color 0.12s ease;
}

.nf-rail__day:hover {
    background: rgba(255, 255, 255, 0.06);
    color: rgba(255, 255, 255, 0.9);
}

.nf-rail__day.is-active {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.nf-rail__letter {
    width: 14px;
    text-align: center;
    font-weight: 600;
    opacity: 0.6;
}

.nf-rail__num {
    flex: 1;
    text-align: left;
    font-weight: 500;
}

.nf-rail__day.is-weekend .nf-rail__letter,
.nf-rail__day.is-weekend .nf-rail__num {
    color: #6f9bf2;
}

.nf-rail__day.is-today {
    color: #ff5b4f;
}

.nf-rail__day.is-today .nf-rail__letter,
.nf-rail__day.is-today .nf-rail__num {
    color: #ff5b4f;
    font-weight: 700;
}

.nf-rail__day.is-today::after {
    content: '';
    position: absolute;
    left: -18px;
    right: -10px;
    top: 50%;
    border-top: 1px solid #ff5b4f;
    opacity: 0.7;
    pointer-events: none;
}

.nf-rail__marker {
    display: inline-flex;
    width: 12px;
    height: 12px;
    align-items: center;
    justify-content: center;
    flex: 0 0 auto;
}

.nf-rail__marker svg {
    width: 11px;
    height: 11px;
}

.nf-rail__marker--journal {
    color: rgba(255, 255, 255, 0.6);
}

.nf-rail__marker--dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #ff5b4f;
}

/* ── Main column ───────────────────────────────────────────────────── */

.nf-main {
    flex: 1 1 auto;
    position: relative;
    min-width: 0;
}

.nf-feed {
    position: absolute;
    inset: 0;
    overflow-y: auto;
    padding: 24px 28px 120px;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.nf-empty {
    margin-top: 60px;
    text-align: center;
    color: rgba(255, 255, 255, 0.4);
    font-size: 14px;
}

/* ── Composer ──────────────────────────────────────────────────────── */

.nf-composer {
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 18px;
    background: var(--ui-chat-input-bg);
    padding: 16px 18px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 6px;
    border-radius: var(--ui-border-radius);
    corner-shape: var(--ui-corner-shape);
}

.nf-composer__top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
}

.nf-composer__input {
    flex: 1;
    resize: none;
    background: none;
    border: none;
    outline: none;
    color: rgba(255, 255, 255, 0.92);
    font-family: inherit;
    font-size: 17px;
    line-height: 1.4;
    min-height: 24px;
    max-height: 220px;
}

.nf-composer__input::placeholder {
    color: rgba(255, 255, 255, 0.32);
}

.nf-autocapture {
    appearance: none;
    background: none;
    border: 0;
    flex: 0 0 auto;
    font-style: italic;
    font-size: 12px;
    color: rgba(255, 255, 255, 0.32);
    cursor: pointer;
    white-space: nowrap;
    padding: 2px 0;
    transition: color 0.12s ease;
}

.nf-autocapture.is-on {
    color: rgba(120, 200, 255, 0.7);
}

.nf-autocapture:hover {
    color: rgba(255, 255, 255, 0.7);
}

.nf-composer__media {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.nf-composer__thumb {
    position: relative;
    width: 64px;
    height: 64px;
    border-radius: 10px;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.12);
}

.nf-composer__thumb img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.nf-composer__thumbx {
    position: absolute;
    top: 2px;
    right: 2px;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    border: 0;
    background: rgba(0, 0, 0, 0.6);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    padding: 0;
}

.nf-composer__thumbx svg {
    width: 11px;
    height: 11px;
}

.nf-composer__bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.nf-iconbtn {
    appearance: none;
    width: 38px;
    height: 38px;
    border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(255, 255, 255, 0.03);
    color: rgba(255, 255, 255, 0.7);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: border-color 0.12s ease, color 0.12s ease;
}

.nf-iconbtn:hover {
    border-color: rgba(255, 255, 255, 0.4);
    color: #fff;
}

.nf-iconbtn svg {
    width: 19px;
    height: 19px;
}

.nf-postbtn {
    appearance: none;
    border: 0;
    border-radius: 999px;
    padding: 9px 26px;
    font-size: 14px;
    font-weight: 600;
    color: #fff;
    background: var(--ui-chat-header-bg, linear-gradient(180deg, #5b9dff, #3b6fe0));
    cursor: pointer;
    transition: opacity 0.12s ease, transform 0.08s ease;
}

.nf-postbtn:hover:not(:disabled) {
    transform: translateY(-1px);
}

.nf-postbtn:disabled {
    opacity: 0.35;
    cursor: default;
}

/* ── Feed rows ─────────────────────────────────────────────────────── */

.nf-row {
    appearance: none;
    -webkit-appearance: none;
    width: 100%;
    display: flex;
    align-items: center;
    gap: 14px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.08);
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.015));
    padding: 5px 12px;
    color: rgba(255, 255, 255, 0.9);
    text-align: left;
    cursor: pointer;
    transition: border-color 0.12s ease, box-shadow 0.12s ease, background 0.12s ease;
}

.nf-row:hover {
    border-color: rgba(255, 255, 255, 0.18);
}

.nf-row.is-expanded {
    border-color: #4b8bff;
    box-shadow: 0 0 0 1px rgba(75, 139, 255, 0.35), 0 0 24px rgba(75, 139, 255, 0.25);
    background: linear-gradient(180deg, rgba(75, 139, 255, 0.14), rgba(75, 139, 255, 0.04));
}

.nf-icon {
    flex: 0 0 auto;
    width: 28px;
    height: 28px;
    border-radius: 8px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.nf-icon svg {
    width: 18px;
    height: 18px;
}

.nf-icon--music svg {
    width: 20px;
    height: 20px;
}

.nf-icon--journal {
    color: rgba(255, 255, 255, 0.7);
}

.nf-icon--note {
    color: rgba(255, 255, 255, 0.4);
}

.nf-icon--ps {
    background: linear-gradient(180deg, #4f9fff, #1e5fd6);
    color: #fff;
    font-size: 12px;
    font-weight: 800;
    font-family: 'SF Pro', system-ui, sans-serif;
}

.nf-row__body {
    flex: 1;
    font-size: 17px;
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.nf-row__tag {
    flex: 0 0 auto;
    font-size: 12px;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.7);
    border: 1px solid rgba(255, 255, 255, 0.2);
    border-radius: 8px;
    padding: 2px 10px;
}

.nf-row__media {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    gap: 6px;
}

.nf-row__media img {
    width: 32px;
    height: 32px;
    border-radius: 7px;
    object-fit: cover;
    border: 1px solid rgba(255, 255, 255, 0.12);
    display: block;
}

.nf-row__mediamore {
    font-size: 11px;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.55);
    padding: 0 2px;
}

.nf-row__meta {
    flex: 0 0 auto;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 2px;
    font-size: 13px;
    color: rgba(255, 255, 255, 0.45);
    white-space: nowrap;
}

.nf-row__auto {
    font-size: 11px;
    color: #6fb0ff;
    text-decoration: underline;
    text-decoration-color: rgba(111, 176, 255, 0.4);
}

/* ── Session detail drawer ─────────────────────────────────────────── */

.nf-drawer {
    position: absolute;
    left: 28px;
    right: 28px;
    bottom: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    pointer-events: none;
    backdrop-filter: blur(20px);
}

.nf-drawer__tab {
    appearance: none;
    pointer-events: auto;
    background: #0b0b0c;
    border: 1px solid #4b8bff;
    color: #6fb0ff;
    border-radius: 999px;
    padding: 7px 22px;
    font-size: 13px;
    font-weight: 500;
    cursor: default;
    transform: translateY(50%);
    white-space: nowrap;
}

.nf-drawer__body {
    pointer-events: auto;
    width: 100%;
    max-height: 76vh;
    overflow-y: auto;
    background: var(--ui-modal-bg);
    backdrop-filter: blur(3.5px);
    border: 1px solid rgba(75, 139, 255, 0.35);
    border-radius: 22px 22px 0 0;
    box-shadow: 0 -12px 40px rgba(0, 0, 0, 0.55);
    padding: 28px 28px 24px;
    display: flex;
    gap: 16px;
}

.nf-drawer__collapse {
    appearance: none;
    flex: 0 0 auto;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    border: 1px solid rgba(255, 255, 255, 0.15);
    background: rgba(255, 255, 255, 0.04);
    color: rgba(255, 255, 255, 0.7);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.nf-drawer__collapse:hover {
    color: #fff;
    border-color: rgba(255, 255, 255, 0.4);
}

.nf-drawer__chevron svg {
    width: 14px;
    height: 14px;
}

.nf-drawer__chevron.is-up {
    transform: rotate(180deg);
}

.nf-drawer__content {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.nf-drawer__title {
    margin: 0;
    font-size: 20px;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.95);
}

.nf-drawer__meta {
    display: flex;
    gap: 18px;
    font-size: 12px;
    letter-spacing: 0.06em;
    color: rgba(255, 255, 255, 0.5);
    font-weight: 600;
}

.nf-drawer__section {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.nf-drawer__label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: rgba(255, 255, 255, 0.35);
    font-weight: 700;
}

.nf-drawer__empty {
    margin: 0;
    font-size: 14px;
    color: rgba(255, 255, 255, 0.4);
}

.nf-drawer__shots {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}

.nf-drawer__shots img {
    width: 120px;
    height: 80px;
    object-fit: cover;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.1);
}

.nf-drawer__notes {
    resize: vertical;
    min-height: 40px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 10px;
    padding: 10px 12px;
    color: rgba(255, 255, 255, 0.85);
    font-family: inherit;
    font-size: 14px;
    outline: none;
}

.nf-drawer__notes::placeholder {
    color: rgba(255, 255, 255, 0.35);
}

.nf-drawer__saving {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.35);
}

/* ── briizy capture: search, screen matches, timeline, filmstrip ──────
   Extends the existing vocabulary rather than introducing a second visual
   language: same radii, same rgba scale, same blue accent (#4b8bff / #6fb0ff). */

.nf-header__capture {
    margin-left: auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 11px;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: rgba(111, 176, 255, 0.75);
}

.nf-autocapture.is-disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.nf-autocapture__warn {
    color: #e0a33e;
    font-style: normal;
}

.nf-icon--screen {
    color: rgba(111, 176, 255, 0.75);
}

/* Search ------------------------------------------------------------- */

.nf-search {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    margin-bottom: 8px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 999px;
}

.nf-search__icon {
    flex: 0 0 auto;
    color: rgba(255, 255, 255, 0.35);
    display: inline-flex;
}

.nf-search__icon svg {
    width: 15px;
    height: 15px;
}

.nf-search__input {
    flex: 1;
    min-width: 0;
    background: none;
    border: 0;
    outline: none;
    color: rgba(255, 255, 255, 0.9);
    font-family: inherit;
    font-size: 14px;
}

.nf-search__input::placeholder {
    color: rgba(255, 255, 255, 0.3);
}

.nf-search__input::-webkit-search-cancel-button {
    display: none;
}

.nf-search__count {
    flex: 0 0 auto;
    font-size: 11px;
    color: rgba(255, 255, 255, 0.4);
    white-space: nowrap;
}

.nf-search__clear {
    appearance: none;
    flex: 0 0 auto;
    background: none;
    border: 0;
    color: rgba(255, 255, 255, 0.4);
    cursor: pointer;
    display: inline-flex;
    padding: 2px;
}

.nf-search__clear:hover {
    color: #fff;
}

.nf-search__clear svg {
    width: 12px;
    height: 12px;
}

/* Screen matches ----------------------------------------------------- */

.nf-matches {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 14px 16px;
    margin-bottom: 10px;
    border: 1px solid rgba(75, 139, 255, 0.25);
    border-radius: 16px;
    background: rgba(75, 139, 255, 0.05);
}

.nf-matches__label {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: rgba(111, 176, 255, 0.7);
    font-weight: 700;
}

.nf-matches__group {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.nf-matches__head {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    font-size: 12px;
}

.nf-matches__apps {
    color: rgba(255, 255, 255, 0.75);
    font-weight: 600;
}

.nf-matches__time {
    color: rgba(255, 255, 255, 0.4);
    white-space: nowrap;
}

.nf-matches__hit {
    appearance: none;
    display: flex;
    align-items: center;
    gap: 12px;
    width: 100%;
    text-align: left;
    padding: 8px;
    border: 1px solid transparent;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.03);
    color: inherit;
    font-family: inherit;
    cursor: pointer;
}

.nf-matches__hit:hover {
    background: rgba(255, 255, 255, 0.07);
    border-color: rgba(75, 139, 255, 0.35);
}

.nf-matches__thumb,
.nf-matches__hit .nf-frame__placeholder {
    flex: 0 0 auto;
    width: 84px;
    height: 54px;
    object-fit: cover;
    border-radius: 6px;
    border: 1px solid rgba(255, 255, 255, 0.1);
}

.nf-matches__text {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
}

.nf-matches__snippet {
    font-size: 13px;
    color: rgba(255, 255, 255, 0.85);
    line-height: 1.35;
    overflow: hidden;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
}

.nf-matches__mark {
    background: rgba(111, 176, 255, 0.25);
    color: #cfe4ff;
    border-radius: 3px;
    padding: 0 2px;
}

.nf-matches__meta {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.4);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.nf-matches__more {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.35);
    padding-left: 8px;
}

/* Frame placeholder -------------------------------------------------- */

.nf-frame__placeholder {
    display: inline-block;
    background: repeating-linear-gradient(115deg, rgba(255, 255, 255, 0.045) 0 10px, rgba(255, 255, 255, 0.02) 10px 20px);
    border-radius: 6px;
}

.nf-row__apps {
    display: block;
    font-size: 11px;
    color: rgba(255, 255, 255, 0.4);
    margin-top: 2px;
}

.nf-row__media .nf-frame__placeholder {
    width: 46px;
    height: 32px;
}

/* Timeline ----------------------------------------------------------- */

.nf-timeline {
    display: flex;
    flex-direction: column;
    gap: 4px;
    max-height: 180px;
    overflow-y: auto;
}

.nf-timeline__seg {
    appearance: none;
    display: grid;
    grid-template-columns: minmax(80px, 140px) 1fr auto;
    gap: 12px;
    align-items: baseline;
    text-align: left;
    padding: 6px 10px;
    border: 1px solid transparent;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.03);
    color: inherit;
    font-family: inherit;
    cursor: pointer;
}

.nf-timeline__seg:hover {
    background: rgba(255, 255, 255, 0.07);
}

.nf-timeline__seg.is-active {
    border-color: rgba(75, 139, 255, 0.5);
    background: rgba(75, 139, 255, 0.12);
}

.nf-timeline__app {
    font-size: 13px;
    color: rgba(255, 255, 255, 0.85);
    font-weight: 600;
}

.nf-timeline__title {
    font-size: 12px;
    color: rgba(255, 255, 255, 0.5);
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
}

.nf-timeline__time {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.4);
    white-space: nowrap;
}

/* Filmstrip ---------------------------------------------------------- */

.nf-filmstrip {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    border: 1.5px solid var(--layout-accent-cyan-glow);
    border-radius: 4px;
    background: black;
    align-items: center;
    padding: 8px 2px;
    gap: 12px;
}

.nf-filmstrip__cell {
    appearance: none;
    flex: 0 0 auto;
    padding: 0;
    border: 2px solid transparent;
    border-radius: 8px;
    background: none;
    cursor: pointer;
    line-height: 0;
}

.nf-filmstrip__cell.is-active {
    border-color: #4b8bff;
}

.nf-filmstrip__cell img,
.nf-filmstrip__cell .nf-frame__placeholder {
    width: 112px;
    height: 72px;
    object-fit: cover;
    border-radius: 6px;
}

/* Selected moment ---------------------------------------------------- */

.nf-moment {
    display: flex;
    gap: 14px;
    align-items: flex-start;
}

.nf-moment__image {
    flex: 0 0 auto;
    width: 46%;
    max-width: 420px;
    min-height: 120px;
    border-radius: 10px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    object-fit: contain;
    background: rgba(0, 0, 0, 0.3);
}

.nf-moment__side {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.nf-moment__app {
    font-size: 13px;
    color: rgba(255, 255, 255, 0.85);
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
}

.nf-moment__time {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.4);
}

.nf-moment__text {
    font-size: 12px;
    line-height: 1.45;
    color: rgba(255, 255, 255, 0.65);
    white-space: pre-wrap;
    max-height: 180px;
    overflow-y: auto;
    padding: 8px 10px;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid rgba(255, 255, 255, 0.08);
}

/* Capture settings sheet --------------------------------------------- */

.nf-drawer__tab.is-open {
    background: #4b8bff;
    color: #061020;
    cursor: pointer;
}

.nf-drawer__tab {
    cursor: pointer;
}

.nf-drawer__frames {
    color: rgba(255, 255, 255, 0.4);
}

.nf-capture {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 14px 16px;
    border: 1px solid rgba(75, 139, 255, 0.3);
    border-radius: 14px;
    background: rgba(6, 12, 26, 0.6);
}

.nf-capture__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.nf-capture__close {
    appearance: none;
    background: none;
    border: 0;
    color: rgba(255, 255, 255, 0.45);
    cursor: pointer;
    display: inline-flex;
}

.nf-capture__close:hover {
    color: #fff;
}

.nf-capture__close svg {
    width: 12px;
    height: 12px;
}

.nf-capture__row {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13px;
}

.nf-capture__state {
    color: rgba(255, 255, 255, 0.85);
}

.nf-capture__current {
    margin-left: auto;
    font-size: 11px;
    color: rgba(255, 255, 255, 0.4);
}

.nf-capture__dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    flex: 0 0 auto;
    background: rgba(255, 255, 255, 0.3);
}

.nf-capture__dot.is-capturingWindow,
.nf-capture__dot.is-capturingDisplay {
    background: #4bd97f;
}

.nf-capture__dot.is-paused {
    background: rgba(255, 255, 255, 0.35);
}

.nf-capture__dot.is-permissionRequired {
    background: #e0a33e;
}

.nf-capture__dot.is-unavailable {
    background: rgba(255, 255, 255, 0.2);
}

.nf-capture__dot.is-error {
    background: #e0473e;
}

.nf-capture__hint {
    margin: 0;
    font-size: 12px;
    line-height: 1.45;
    color: rgba(255, 255, 255, 0.5);
}

.nf-capture__hint code {
    font-size: 11px;
    padding: 1px 4px;
    border-radius: 4px;
    background: rgba(255, 255, 255, 0.08);
}

.nf-capture__actions {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}

.nf-capture__btn {
    appearance: none;
    padding: 6px 14px;
    border-radius: 999px;
    border: 1px solid rgba(255, 255, 255, 0.18);
    background: rgba(255, 255, 255, 0.05);
    color: rgba(255, 255, 255, 0.85);
    font-family: inherit;
    font-size: 12px;
    cursor: pointer;
}

.nf-capture__btn:hover:not(:disabled) {
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.35);
}

.nf-capture__btn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.nf-capture__btn.is-danger {
    border-color: rgba(224, 71, 62, 0.45);
    color: #ff9a93;
}

.nf-capture__btn.is-danger:hover:not(:disabled) {
    background: rgba(224, 71, 62, 0.15);
}

.nf-capture__storage {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.nf-capture__bar {
    height: 5px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.08);
    overflow: hidden;
}

.nf-capture__fill {
    display: block;
    height: 100%;
    border-radius: 999px;
    background: linear-gradient(90deg, #4b8bff, #6fb0ff);
}

.nf-capture__usage {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.45);
}

.nf-capture__fields {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 8px 14px;
}

.nf-capture__field {
    display: flex;
    flex-direction: column;
    gap: 4px;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(255, 255, 255, 0.4);
}

.nf-capture__field select {
    appearance: none;
    padding: 6px 10px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: rgba(255, 255, 255, 0.05);
    color: rgba(255, 255, 255, 0.88);
    font-family: inherit;
    font-size: 12px;
    text-transform: none;
    letter-spacing: normal;
    cursor: pointer;
}

.nf-capture__exclusions {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.nf-capture__details {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.45);
}

.nf-capture__details summary {
    cursor: pointer;
}

.nf-capture__details ul {
    margin: 6px 0 0;
    padding-left: 16px;
    max-height: 140px;
    overflow-y: auto;
}

.nf-capture__details code {
    font-size: 10px;
}

.nf-capture__danger {
    display: flex;
    gap: 8px;
    align-items: center;
    flex-wrap: wrap;
    padding-top: 4px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
}

/* ── Proposal inbox (§10) ────────────────────────────────────────────
   Understated on purpose: this is the surface that decides whether briizy reads
   as helpful or naggy. No colour-shouting except for high urgency. */

.nf-inbox {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 12px 14px;
    margin-bottom: 10px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.025);
}

.nf-inbox__head {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
}

.nf-inbox__count {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.35);
}

.nf-inbox__item {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 9px 10px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.03);
    border-left: 2px solid rgba(255, 255, 255, 0.12);
}

.nf-inbox__item.is-high {
    border-left-color: #e0a33e;
}

.nf-inbox__item.is-low {
    border-left-color: rgba(255, 255, 255, 0.08);
}

.nf-inbox__item.is-open {
    background: rgba(255, 255, 255, 0.06);
}

.nf-inbox__text {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.nf-inbox__title {
    font-size: 13px;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.9);
}

.nf-inbox__summary {
    font-size: 13px;
    line-height: 1.4;
    color: rgba(255, 255, 255, 0.75);
}

.nf-inbox__why {
    font-size: 11.5px;
    line-height: 1.4;
    color: rgba(255, 255, 255, 0.45);
}

.nf-inbox__actions {
    flex: 0 0 auto;
    display: flex;
    gap: 6px;
    align-items: center;
    flex-wrap: wrap;
    justify-content: flex-end;
}

.nf-capture__btn.is-accept {
    border-color: rgba(75, 217, 127, 0.45);
    color: #8ff0b4;
}

.nf-capture__btn.is-accept:hover:not(:disabled) {
    background: rgba(75, 217, 127, 0.15);
}

/* ── Assistant settings ─────────────────────────────────────────────── */

.nf-capture__assistants {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding-top: 10px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.nf-capture__consent {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    font-size: 12px;
    line-height: 1.45;
    color: rgba(255, 255, 255, 0.6);
    padding: 10px 12px;
    border-radius: 10px;
    background: rgba(75, 139, 255, 0.06);
    border: 1px solid rgba(75, 139, 255, 0.2);
}

.nf-capture__consent input {
    margin-top: 2px;
    flex: 0 0 auto;
}

.nf-capture__consent strong {
    color: rgba(255, 255, 255, 0.85);
}

.nf-capture__assistant {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 8px 10px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.02);
}

.nf-capture__assistant.is-soon {
    opacity: 0.5;
}

.nf-capture__assistant-head {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.nf-capture__assistant-toggle {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
}

.nf-capture__assistant-name {
    font-size: 13px;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.85);
}

.nf-capture__soon {
    font-size: 10px;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: rgba(255, 255, 255, 0.3);
}

.nf-capture__assistant-head select {
    appearance: none;
    margin-left: auto;
    padding: 4px 8px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: rgba(255, 255, 255, 0.05);
    color: rgba(255, 255, 255, 0.8);
    font-family: inherit;
    font-size: 11px;
    cursor: pointer;
}

.nf-capture__prompt {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 6px;
}

.nf-capture__prompt textarea {
    resize: vertical;
    background: rgba(0, 0, 0, 0.35);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 10px;
    padding: 10px 12px;
    color: rgba(255, 255, 255, 0.85);
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 11.5px;
    line-height: 1.5;
    outline: none;
}

/* ── What briizy learned (I7) ───────────────────────────────────────── */

.nf-capture__learning {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding-top: 10px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.nf-capture__learning>.nf-capture__btn {
    align-self: flex-start;
}

.nf-capture__learning-body {
    display: flex;
    flex-direction: column;
    gap: 6px;
    max-height: 220px;
    overflow-y: auto;
}

.nf-capture__fact {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 2px 10px;
    align-items: center;
    padding: 7px 10px;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.03);
}

.nf-capture__fact-text {
    font-size: 12.5px;
    color: rgba(255, 255, 255, 0.85);
}

.nf-capture__fact-meta {
    grid-column: 1;
    font-size: 10.5px;
    color: rgba(255, 255, 255, 0.35);
}

.nf-capture__fact .nf-capture__btn {
    grid-row: 1 / span 2;
    grid-column: 2;
    font-size: 11px;
    padding: 4px 10px;
}

/* ── Goals (§11) ────────────────────────────────────────────────────── */

.nf-capture__goals {
    display: flex;
    flex-direction: column;
    gap: 7px;
    padding-top: 10px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.nf-capture__goal {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 7px 10px;
    border-radius: 9px;
    background: rgba(255, 255, 255, 0.03);
}

.nf-capture__goal-title {
    flex: 1;
    min-width: 0;
    font-size: 12.5px;
    color: rgba(255, 255, 255, 0.85);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.nf-capture__goal-meta {
    font-size: 10.5px;
    color: rgba(255, 255, 255, 0.32);
    white-space: nowrap;
}

.nf-capture__goal .nf-capture__btn {
    font-size: 11px;
    padding: 4px 10px;
}

.nf-capture__goal-add {
    display: flex;
    gap: 8px;
    align-items: center;
}

.nf-capture__goal-add input {
    flex: 1;
    min-width: 0;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 9px;
    padding: 7px 11px;
    color: rgba(255, 255, 255, 0.88);
    font-family: inherit;
    font-size: 12.5px;
    outline: none;
}

.nf-capture__goal-add input::placeholder {
    color: rgba(255, 255, 255, 0.3);
}

/* ── First-run onboarding (I10) ─────────────────────────────────────── */

.nf-onboard {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 18px 20px;
    margin-bottom: 10px;
    border: 1px solid rgba(75, 139, 255, 0.4);
    border-radius: 18px;
    background: linear-gradient(180deg, rgba(75, 139, 255, 0.1), rgba(10, 14, 26, 0.7));
}

.nf-onboard__title {
    margin: 0;
    font-size: 17px;
    font-weight: 650;
    color: rgba(255, 255, 255, 0.95);
}

.nf-onboard__list {
    margin: 0;
    padding-left: 18px;
    display: flex;
    flex-direction: column;
    gap: 7px;
    font-size: 12.5px;
    line-height: 1.5;
    color: rgba(255, 255, 255, 0.7);
}

.nf-onboard__list strong {
    color: rgba(255, 255, 255, 0.92);
    font-weight: 600;
}

.nf-onboard__list em {
    color: rgba(255, 255, 255, 0.85);
    font-style: italic;
}

.nf-onboard__actions {
    display: flex;
    gap: 8px;
    align-items: center;
}

.nf-onboard__actions .nf-capture__btn {
    padding: 8px 18px;
    font-size: 13px;
}

.nf-onboard__foot {
    margin: 0;
    font-size: 11px;
    color: rgba(255, 255, 255, 0.35);
}

/* ===== START OF styles.css ===== */

/* Scoped to .forest-shell (not :root) so these variables, resets, and
   element-level defaults stay contained to the Forest panel and can't leak
   into — or be overridden by — the rest of briizOS.local, which shares this
   document. See the Forest hardening pass notes for why. */

.forest-shell {
    --bg-0: #08170f;
    --bg-1: #04100a;
    --bg-2: #103324;
    --glass: rgba(255, 255, 255, 0.08);
    --glass-2: rgba(255, 255, 255, 0.05);
    --glass-3: rgba(255, 255, 255, 0.3);
    --border: rgba(255, 255, 255, 0.12);
    --text: #e4f1dc;
    --darkText: #e0a352;
    --muted: rgba(214, 231, 222, 0.66);
    --shadowTop: 0 24px 80px rgba(23, 217, 138, 0.22);
    --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
    --radius: 24px;
    --card-w: 360px;
    width: 100%;
    height: 100%;
    margin: 0;
    overflow: hidden;
    font-family: var(--ui-font-main), Chillax, Jost, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    color: var(--text);
}

.forest-shell * {
    box-sizing: border-box;
}

.forest-shell::before {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0.25;
    background-image: radial-gradient(rgba(255, 255, 255, 0.15) 0.6px, transparent 0.7px);
    background-size: 18px 18px;
