}

.aurora-b {
    top: 8%;
    right: -160px;
    background: radial-gradient(circle, rgba(126, 190, 240, 0.38), transparent 70%);
    animation: drift-b 22s ease-in-out infinite alternate;
}

.aurora-c {
    bottom: -220px;
    left: 22%;
    background: linear-gradient(to bottom left, #2a4456, #9fb8c2, #e0aa78);
    opacity: 0.35;
    animation: drift-c 20s ease-in-out infinite alternate;
}

.topbar {
    position: absolute;
    top: 0px;
    left: 0px;
    right: 0px;
    z-index: 10;
    display: flex;
    gap: 18px;
    align-items: center;
    padding: 0px 10px;
    padding-top: 3px;
    height: 3rem;
