    inset: 8px;
    border-radius: 12px;
    background: rgba(5, 15, 10, 0.76);
    border: 1px solid rgba(255, 255, 255, 0.08);
    color: #7ef0b4;
    -webkit-text-stroke: 1px rgba(23, 217, 138, 0.55);
}

.brand h1 {
    margin: 0;
    font-size: 3.12rem;
    font-family: ZnikomitNo24;
    line-height: 1;
    letter-spacing: 0.01em;
    text-shadow: 3px 2px 1px black;
}

.brand h1 span {
    font-family: SF Pro;
    font-size: 2.5rem;
    font-weight: 100;
    color: #17d98a;
    -webkit-text-stroke: 1px rgba(228, 241, 220, 0.45);
}

.brand p {
    margin: 6px 0 0;
    font-size: 0.9rem;
}

.toolbar {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-direction: row;
    overflow: scroll;
    height: 100%;
}

.toolbar::-webkit-scrollbar {
    display: none;
}

.search-wrap {
    position: absolute;
    ;
    flex: 1;
    top: 3rem;
    left: 34px;
    min-width: 220px;
}

.collapse-all-btn {
    position: absolute;
    top: 3rem;
    right: 14px;
    z-index: 2;
    display: grid;
    width: 60px;
    height: 29px;
    padding: 0;
    align-items: center;
    justify-content: center;
    color: #b9f5d3;
    background: rgba(7, 55, 38, 0.9);
    border: 1px solid rgba(160, 244, 198, 0.25) !important;
    border-top: 0 !important;
    border-radius: 0 0 11px 11px;
    box-shadow: inset 0 -1px 0 rgba(255, 255, 255, 0.08), 0 5px 16px rgba(0, 0, 0, 0.22);
    cursor: pointer;
    transition: color 0.16s ease, background 0.16s ease, transform 0.16s ease, opacity 0.16s ease;
}

.collapse-all-btn span {
    font-family: SF Pro;
}

.collapse-all-btn:hover:not(:disabled) {
    color: #e4fbe9;
    background: rgba(13, 91, 59, 0.96);
    transform: translateY(2px);
}

.collapse-all-btn:focus-visible {
    outline: 2px solid rgba(185, 245, 211, 0.9);
    outline-offset: 2px;
}

.collapse-all-btn:disabled {
    opacity: 0.38;
    cursor: default;
}

.dim-mode .search-wrap {
    top: 1.5rem
}

.dim-mode .collapse-all-btn {
    top: 1.5rem;
    ;
}

.search-wrap::before {
    content: "⌕";
    position: absolute;
    left: 8px;
    top: 50%;
    transform: translateY(-50%);
    color: rgba(250, 205, 250, 0.307);
    font-size: 3rem;
    pointer-events: none;
}

.search-wrap input {
    width: 5%;
    padding: 2px 2px;
    padding-left: 40px;
    border-radius: 0 0 10px 10px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-top: none;
    background: rgba(0, 100, 155, 0.6);
    outline: none;
    color: white !important;
    box-shadow: inset 0 1px 0 rgba(0, 0, 0, 1);
    transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
    transition: all .3s;
}

.search-wrap input:focus {
    width: 100%;
    padding: 9px 50px;
    box-shadow: inset 0 -2px 7px rgba(0, 0, 0, 1);
}

.search-wrap input::placeholder {
    color: limegreen;
}

.ghost-btn {
    padding: 4px 6px;
    border-radius: 14px;
    color: var(--text);
    border: 1px solid rgba(255, 255, 255, .4) !important;
    background: rgba(0, 5, 0, 0.5);
}

.ghost-btn:hover {
    transform: translateY(-1px);
    background: rgba(255, 255, 255, 0.09);
    border-color: rgba(255, 255, 255, 0.16);
}

.status-pills {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(2, 1fr));
    justify-content: center;
    justify-items: center;
    align-items: center;
    text-align: center;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 4px;
    min-width: 30%;
    max-width: 30%;
    overflow: hidden;
    width: 30%;
    display: none;
}

.stat-pill {
    width: 3.5rem;
    height: 1rem;
    border-radius: 999px;
    display: flex;
    font-size: 0.5rem;
    color: white;
    font-size: 1rem;
    width: fit-content;
    padding: 0 4px;
    text-align: center;
    justify-content: center;
    display: flex;
    background: rgba(0, 0, 0, 0.1);
    ;
    border: 1px solid rgba(255, 255, 255, 0.09);
    max-width: 3.5rem;
    min-width: 3.5rem;
    overflow: hidden;
}

.stat-pill.subtle {
    color: var(--muted);
}

.hud.help-bubble {
    position: absolute;
    top: 110px;
    left: 28px;
    z-index: 7;
    padding: 10px 14px;
    border-radius: 14px;
    font-size: 0.84rem;
    color: var(--muted);
    background: rgba(8, 22, 16, 0.55);
    border: 1px solid rgba(255, 255, 255, 0.08);
    backdrop-filter: blur(14px);
}

.stage {
    position: absolute;
    inset: 0px;
    overflow: hidden;
    border-radius: 30px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: radial-gradient(circle at 50% 16%, rgba(46, 230, 160, 0.08), transparent 38%), radial-gradient(ellipse 640px 420px at 76% 68%, rgba(224, 170, 122, 0.08), transparent 70%), radial-gradient(ellipse 520px 380px at 28% 40%, rgba(158, 176, 186, 0.09), transparent 70%), radial-gradient(circle at 16% 86%, rgba(86, 160, 232, 0.14), transparent 36%), linear-gradient(160deg, #0a1a20, #16394a 50%, #0d2530);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), var(--shadow);
    touch-action: none;
    filter: brightness(1);
}

.stage::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;
    background: radial-gradient(circle at center, transparent 35%, rgba(0, 0, 0, 0.14) 100%), linear-gradient(180deg, transparent, rgba(0, 0, 0, 0.1));
}

.grid {
    position: absolute;
    inset: 0;
    pointer-events: none;
    --minor: 48px;
    --major: 240px;
    --off-x: 0px;
    --off-y: 0px;
    --major-off-x: 0px;
    --major-off-y: 0px;
    background-image: linear-gradient(rgba(42, 178, 228, 0.05) 1px, transparent 1px), linear-gradient(90deg, rgba(16, 93, 236, 0.09) 1.5px, transparent 1px), linear-gradient(rgba(178, 216, 230, .09) 1px, transparent 3px), linear-gradient(90deg, rgba(178, 216, 230, 0.09) 1px, transparent 1px);
    background-size: var(--minor) var(--minor), var(--minor) var(--minor), var(--major) var(--major), var(--major) var(--major);
    background-position: var(--off-x) var(--off-y), var(--off-x) var(--off-y), var(--major-off-x) var(--major-off-y), var(--major-off-x) var(--major-off-y);
    opacity: 0.9;
}

.world {
    position: absolute;
    inset: 0;
    transform-origin: 0 0;
    will-change: transform;
}

/* ── Grab / grabbing cursors (canvas pan + project-card drag) ───────── */

.stage {
    cursor: grab;
}

.forest-shell.is-panning,
.forest-shell.is-panning .stage,
.forest-shell:has(.project-card.forest-dragging) {
    cursor: grabbing;
}

.project-card {
    cursor: default;
}

.project-header[data-drag-handle] {
    cursor: grab;
}

[data-role="cover-drag-area"] {
    cursor: grab;
}

.project-card.forest-dragging,
.project-card.forest-dragging [data-drag-handle] {
    cursor: grabbing;
}

/* ── Timeline: add-mode toggle + milestone modal close button ───────── */

.viewer-timeline-action-btn.tl-add-toggle.forest-active {
    background: var(--accent, #16c784);
    color: #fff;
    border-color: transparent;
}

.tl-modal-close {
    margin-left: 4px;
    width: 26px;
    height: 26px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.06);
    color: var(--muted);
    font-size: 13px;
    cursor: pointer;
}

.tl-modal-close:hover {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
}

/* ── Shared right-side slideout panels (Hunter + FileHawk) ──────────── */

.cv-slideout {
    position: fixed;
    top: 0;
    right: 0;
    z-index: 14;
    width: 420px;
    max-width: 92vw;
    height: 100%;
    display: flex;
    flex-direction: column;
    background: rgba(7, 18, 14, 0.96);
    backdrop-filter: blur(18px);
    border-left: 1px solid rgba(255, 255, 255, 0.12);
    box-shadow: -24px 0 60px rgba(0, 0, 0, 0.5);
    color: var(--text, #e9efff);
    animation: cv-slidein 0.18s ease;
}

.cv-slideout.forest-hidden {
    display: none;
}

@keyframes cv-slidein {
    from {
        transform: translateX(24px);
        opacity: 0;
    }

    to {
        transform: none;
        opacity: 1;
    }
}

.cv-slideout-head {
    flex: 0 0 auto;
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding: 16px 16px 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.cv-slideout-kicker {
    display: block;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.45);
}

.cv-slideout-title h3 {
    margin: 2px 0 0;
    font-size: 17px;
    font-weight: 650;
}

.cv-slideout-head-actions {
    display: flex;
    align-items: center;
    gap: 8px;
}

.cv-slideout-sub {
    flex: 0 0 auto;
    padding: 8px 16px;
    font-size: 12px;
    color: rgba(255, 255, 255, 0.5);
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.cv-slideout-body {
    flex: 1 1 auto;
    overflow-y: auto;
    padding: 8px 12px 16px;
}

.cv-slideout-empty {
    padding: 40px 16px;
    text-align: center;
    color: rgba(255, 255, 255, 0.4);
}

.cv-slideout .forest-action-btn {
    background: rgba(255, 255, 255, 0.07);
    color: rgba(255, 255, 255, 0.9);
    border-radius: 8px;
    padding: 6px 12px;
    font-size: 13px;
    cursor: pointer;
}

.cv-slideout .forest-action-btn:hover {
    background: rgba(255, 255, 255, 0.13);
}

.cv-slideout .forest-action-btn.forest-primary {
    background: var(--accent, #16c784);
    color: #fff;
}

.cv-slideout .forest-action-btn[disabled] {
    opacity: 0.5;
    cursor: default;
}

.cv-slideout .icon-btn {
    background: none;
    color: rgba(255, 255, 255, 0.6);
    font-size: 16px;
    cursor: pointer;
    line-height: 1;
    padding: 2px 6px;
    border-radius: 6px;
}

.cv-slideout .icon-btn:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.cv-slideout .file-copy {
    min-width: 0;
    flex: 1 1 auto;
}

.cv-slideout .forest-file-name {
    font-size: 13px;
    font-weight: 550;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.cv-slideout .file-sub {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.45);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.cv-slideout .file-badge {
    flex: 0 0 auto;
}

/* Hunter */

.hunter-search-row {
    padding: 12px 16px 8px;
}

.hunter-search-input {
    width: 100%;
    box-sizing: border-box;
    padding: 9px 12px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: var(--text, #fff);
    font-size: 14px;
    outline: none;
}

.hunter-search-input:focus {
    border-color: var(--accent, #16c784);
    background: rgba(255, 255, 255, 0.09);
}

.hunter-type-chips {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    padding: 0 16px 10px;
}

.hunter-type-chip {
    font-size: 11px;
    padding: 4px 9px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: rgba(255, 255, 255, 0.6);
    cursor: pointer;
}

.hunter-type-chip.forest-active {
    background: var(--accent, #16c784);
    border-color: transparent;
    color: #fff;
}

.hunter-dirs-section {
    padding: 0 16px 6px;
    font-size: 12px;
}

.hunter-dirs-toggle {
    cursor: pointer;
    color: rgba(255, 255, 255, 0.55);
    padding: 6px 0;
}

.hunter-dir-row {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 2px 0;
}

.hunter-dir-path {
    flex: 1 1 auto;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: rgba(255, 255, 255, 0.6);
}

.hunter-dir-default {
    color: rgba(255, 255, 255, 0.4);
    padding: 4px 0;
}

.hunter-dirs-list {
    margin-bottom: 6px;
}

.hunter-results-region {
    padding: 4px 12px 16px;
}

.hunter-section-label,
.hunter-count {
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: rgba(255, 255, 255, 0.45);
    padding: 6px 4px;
}

.hunter-results {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.hunter-result {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 10px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.03);
    border: 1px solid transparent;
}

.hunter-result:hover {
    background: rgba(255, 255, 255, 0.06);
}

.hunter-result.forest-selected {
    border-color: var(--accent, #16c784);
    background: rgba(22, 199, 132, 0.08);
}

/* Result rows: show the full file path, wrapping instead of truncating.
   .cv-slideout-scoped so it wins over the legacy .hunter-result grid rule. */

.cv-slideout .hunter-result {
    display: flex;
    align-items: flex-start;
}

.cv-slideout .hunter-result .file-sub {
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
    overflow-wrap: anywhere;
    line-height: 1.4;
}

.hunter-check {
    width: 16px;
    height: 16px;
    flex: 0 0 auto;
    accent-color: var(--accent, #16c784);
}

.hunter-add-btn {
    flex: 0 0 auto;
}

.hunter-loading,
.hunter-empty {
    padding: 24px 16px;
    text-align: center;
    color: rgba(255, 255, 255, 0.45);
    font-size: 13px;
}

.hunter-addbar {
    position: sticky;
    bottom: 0;
    padding: 10px 4px 4px;
    background: linear-gradient(180deg, transparent, rgba(7, 18, 14, 0.96) 40%);
}

.hunter-addbar .forest-action-btn {
    width: 100%;
}

/* FileHawk */

.fh-group {
    margin-bottom: 14px;
}

.fh-group-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    padding: 4px 6px;
}

.fh-group-name {
    font-size: 13px;
    font-weight: 600;
}

.fh-group-meta {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.4);
}

.fh-group.has-missing .fh-group-meta {
    color: #fca5a5;
}

.fh-row {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 7px 10px;
    border-radius: 9px;
    background: rgba(255, 255, 255, 0.03);
    margin-top: 4px;
}

.fh-status {
    flex: 0 0 auto;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #4ade80;
}

.fh-modified .fh-status {
    background: #fbbf24;
}

.fh-missing .fh-status {
    background: #f87171;
}

.fh-missing {
    background: rgba(248, 113, 113, 0.08);
}

.fh-row-actions {
    display: flex;
    align-items: center;
    gap: 6px;
    flex: 0 0 auto;
}

.fh-row-tag {
    font-size: 11px;
    color: rgba(255, 255, 255, 0.4);
    text-transform: capitalize;
}

.fh-row .tiny-btn {
    background: rgba(255, 255, 255, 0.08);
    color: rgba(255, 255, 255, 0.7);
    border-radius: 6px;
    width: 24px;
    height: 24px;
    cursor: pointer;
}

.fh-row .tiny-btn:hover {
    background: rgba(248, 113, 113, 0.3);
    color: #fff;
}

#filehawkBtn.has-alert {
    color: #fca5a5;
    border-color: rgba(248, 113, 113, 0.5);
}

.fh-badge {
    display: inline-block;
    min-width: 16px;
    padding: 0 5px;
    margin-left: 4px;
    border-radius: 999px;
    background: #f87171;
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    text-align: center;
}

.forest-empty-state {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    z-index: 2;
    pointer-events: none;
    padding: 24px;
}

.empty-card {
    width: min(560px, 88vw);
    padding: 34px;
    border-radius: 28px;
    text-align: center;
    background: linear-gradient(180deg, rgba(19, 40, 24, 0.8), rgba(8, 17, 11, 0.8));
    border: 1px solid rgba(255, 255, 255, 0.12);
    box-shadow: var(--shadow);
    backdrop-filter: blur(18px);
}

.empty-kicker {
    display: inline-block;
    margin-bottom: 14px;
    padding: 8px 12px;
    border-radius: 999px;
    font-size: 0.75rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.76);
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.09);
}

.empty-card h2 {
    margin: 0 0 12px;
    font-size: clamp(1.7rem, 2vw, 2.2rem);
    line-height: 1.1;
}

.empty-card p {
    margin: 0;
    color: var(--muted);
    line-height: 1.6;
}

.forest-drop-overlay {
    position: absolute;
    inset: 0;
    z-index: 11;
    display: grid;
    place-items: center;
    background: rgba(6, 9, 18, 0.52);
    backdrop-filter: blur(10px);
    opacity: 1;
    transition: opacity 0.18s ease;
}

.forest-drop-overlay.forest-hidden {
    opacity: 0;
    pointer-events: none;
}

.drop-panel {
    width: min(720px, 86vw);
    padding: 38px 42px;
    border-radius: 32px;
    text-align: center;
    background: linear-gradient(180deg, rgba(13, 32, 23, 0.88), rgba(7, 18, 13, 0.88));
    border: 1px solid rgba(255, 255, 255, 0.16);
    box-shadow: 0 40px 120px rgba(0, 0, 0, 0.48), 0 0 0 1px rgba(23, 217, 138, 0.12);
}

.drop-icon {
    width: 88px;
    height: 88px;
    margin: 0 auto 18px;
    display: grid;
    place-items: center;
    font-size: 2.8rem;
    border-radius: 28px;
    background: linear-gradient(135deg, rgba(61, 123, 232, 0.45), rgba(23, 217, 138, 0.35));
    border: 1px solid rgba(255, 255, 255, 0.14);
    box-shadow: 0 18px 50px rgba(23, 217, 138, 0.25);
}

.drop-panel h2 {
    margin: 0 0 10px;
    font-size: clamp(1.7rem, 2vw, 2.25rem);
}

.drop-panel p {
    margin: 0;
    color: var(--muted);
    line-height: 1.65;
}

/* The visible grass/dirt bar. The chips live in .tag-strip, a taller
   transparent scroller layered on top, so bloomed tags can rise above the
   grass line without being clipped by the strip's horizontal scrolling. */

.tag-strip-ground {
    position: absolute;
    left: -10px;
    right: -10px;
    bottom: -1px;
    height: 48px;
    z-index: 8;
    border-radius: var(--ui-border-radius) var(--ui-border-radius) 0 0;
    border: 1px solid rgba(255, 255, 255, 0.12);
    backdrop-filter: blur(18px);
    box-shadow: 0 16px 50px rgba(0, 0, 0, 0.28), inset 0 0 60px black;
    ;
    background: linear-gradient(to bottom, lightgreen, darkgreen 30%, brown, darkred, rgb(69, 32, 13));
}

.tag-strip {
    position: absolute;
    left: -10px;
    right: -10px;
    bottom: -1px;
    z-index: 8;
    display: flex;
    gap: 10px;
    align-items: center;
    height: 104px;
    padding: 56px 14px 0;
    overflow-x: auto;
    overflow-y: hidden;
    scrollbar-width: none;
    /* Transparent sky above the grass must not swallow canvas clicks. */
    pointer-events: none;
}

.tag-strip>* {
    pointer-events: auto;
}

.dim-mode .tag-strip-ground {
    background: linear-gradient(to bottom, lightgreen, teal 30%, darkblue, darkslategray);
}

.tag-strip::-webkit-scrollbar {
    display: none;
}

.tag-strip-empty {
    color: var(--muted);
    font-size: 0.84rem;
}

.global-tag {
    transition: all .15s cubic-bezier(.3, .75, .7, 1.2);
    display: inline-flex;
    align-items: center;
    gap: 8px;
    flex-wrap: nowrap;
    text-wrap: nowrap;
    width: 80px;
    overflow: hidden;
    padding: 2px 5px;
    border-radius: 999px;
    color: rgba(255, 255, 255, 0.94);
    background: rgba(255, 255, 255, 0.1);
    border: .5px solid rgba(255, 255, 255, .7) !important;
}

.global-tag span {
    font-size: 0.78rem;
    color: rgba(255, 255, 255, 0.72);
}

.global-tag:hover {
    width: 120px;
    transform: translateY(-1px);
    background: rgba(255, 255, 255, 0.1);
    border-color: rgba(255, 255, 255, 0.16);
}

/* ── Tag blooms: an active filter sprouts out of the grass on a stem ──── */

.global-tag-slot {
    position: relative;
    display: inline-flex;
    flex: none;
}

.global-tag-slot .global-tag {
    position: relative;
    z-index: 1;
    cursor: pointer;
}

/* The chip itself is the flower head: lifted above the grass line on the
   stem, warmed up, and sized to show the full tag name while active.
   --bloom-lift/--bloom-dur/--bloom-delay/--bloom-flutter are set per slot
   from the tag's name hash, so each flower grows a little differently. */

.global-tag-slot.is-bloomed .global-tag {
    transform: translateY(calc(-1 * var(--bloom-lift, 56px)));
    width: auto;
    min-width: 80px;
    max-width: 170px;
    color: #53331f;
    background: linear-gradient(180deg, #fff3d6, #ffd3e0);
    border-color: rgba(255, 224, 138, 0.95) !important;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35), 0 0 16px rgba(255, 214, 130, 0.5);
}

.global-tag-slot.is-bloomed .global-tag span {
    color: rgba(83, 51, 31, 0.65);
}

.global-tag-slot.is-bloomed .global-tag:hover {
    transform: translateY(calc(-3px - var(--bloom-lift, 56px)));
    background: linear-gradient(180deg, #fff7e2, #ffdfe8);
    border-color: #ffe08a !important;
}

.tag-bloom-sprite {
    position: absolute;
    left: 50%;
    bottom: -6px;
    width: 28px;
    height: calc(var(--bloom-lift, 56px) + 16px);
    transform: translateX(-50%);
    transform-origin: bottom center;
    z-index: 0;
    cursor: pointer;
}

.tag-bloom-sprite .bloom-stem {
    stroke: #3fa34d;
    stroke-width: 2.6;
    stroke-linecap: round;
}

.tag-bloom-sprite .bloom-leaf {
    fill: #46b258;
    transform-box: fill-box;
    animation: bloom-leaf-flutter var(--bloom-flutter, 3.4s) ease-in-out infinite alternate;
}

.tag-bloom-sprite .bloom-leaf.left {
    transform-origin: right center;
}

.tag-bloom-sprite .bloom-leaf.right {
    fill: #2f8f41;
    transform-origin: left center;
    animation-duration: calc(var(--bloom-flutter, 3.4s) * 0.82);
    animation-delay: 0.4s;
}

.tag-bloom-sprite .bloom-petals ellipse {
    fill: #ff9db8;
}

.tag-bloom-sprite .bloom-petals .crown {
    fill: #ffb3c7;
}

.global-tag-slot.is-sprouting .global-tag {
    animation: bloom-sprout-chip var(--bloom-dur, 0.5s) ease-out var(--bloom-delay, 0s) backwards;
}

.global-tag-slot.is-sprouting .tag-bloom-sprite {
    animation: bloom-sprout-stem var(--bloom-dur, 0.5s) ease-out var(--bloom-delay, 0s) backwards;
}

.global-tag-slot.is-wilting .global-tag {
    animation: bloom-wilt-chip 0.32s ease-in forwards;
}

.global-tag-slot.is-wilting .tag-bloom-sprite {
    animation: bloom-wilt-stem 0.32s ease-in forwards;
}

@keyframes bloom-sprout-chip {
    0% {
        transform: translateY(0) scale(0.9);
    }

    62% {
        transform: translateY(calc(var(--bloom-lift, 56px) * -1.12)) scale(1.04);
    }

    82% {
        transform: translateY(calc(var(--bloom-lift, 56px) * -0.95)) scale(1);
    }

    100% {
        transform: translateY(calc(var(--bloom-lift, 56px) * -1)) scale(1);
    }
}

@keyframes bloom-sprout-stem {
    0% {
        transform: translateX(-50%) scaleY(0);
    }

    62% {
        transform: translateX(-50%) scaleY(1.12);
    }

    82% {
        transform: translateX(-50%) scaleY(0.95);
    }

    100% {
        transform: translateX(-50%) scaleY(1);
    }
}

@keyframes bloom-wilt-chip {
    0% {
        transform: translateY(calc(var(--bloom-lift, 56px) * -1)) rotate(0deg);
    }

    35% {
        transform: translateY(calc(var(--bloom-lift, 56px) * -1.07)) rotate(-3deg);
    }

    100% {
        transform: translateY(0) rotate(0deg);
    }
}

@keyframes bloom-wilt-stem {
    0% {
        transform: translateX(-50%) scaleY(1);
    }

    35% {
        transform: translateX(-50%) scaleY(1.06);
    }

    100% {
        transform: translateX(-50%) scaleY(0);
    }
}

@keyframes bloom-leaf-flutter {
    from {
        transform: rotate(-4deg);
    }

    to {
        transform: rotate(7deg);
    }
}

.project-card {
